-- 只保留技术类（interview/tech、middleware、spring、arch），共 266 条。
--
-- 处理说明：
--   * 跳过与库内已有题目重复的条目（按标题去重），保留原有人工版本；
--   * 去掉原文的 frontmatter、作者/公众号推广块与 offercome.cn 外链配图；
--   * 难度按答案长度粗分：<220 字简单 / <700 中等 / 其余困难；
--   * source 字段记录来源文章，仅后台可见；
--   * id 固定从 1001 起，配合 INSERT IGNORE 可重复执行。
--
-- 前置：需先执行 migration-v8-taxonomy-align.sql（分类骨架就绪）。
-- ============================================================
USE `codeinterview`;

INSERT IGNORE INTO `question`
  (`id`, `category_id`, `title`, `content_md`, `answer_md`
   , `difficulty`, `status`, `source`, `created_by`, `published_at`)
VALUES
  (1001, 208, '分布式锁都要考虑哪些因素？', '分布式锁都要考虑哪些因素？', '1、互斥性，这个是锁的最基本要求
2、可重入性，同一个线程可以重复多次获得锁
3、支持阻塞、非阻塞两种特性
4、支持锁超时，为了防止线程意外退出，没有正常释放锁，导致其他线程无法正常获取到锁。加锁时间超过一定时间，会自动释放锁', 1, 1, 'technology-talk/arch/case/Redis分布式锁.md', 1, NOW(3)),
  (1002, 208, '技术架构，高可用有哪些策略？', '技术架构，高可用有哪些策略？', '* 多云架构、异地多活、异地备份
* 主备切换，如redis缓存、mysql数据库，主备节点会实时数据同步、备份。如果主节点不可用，自动切换到备用节点
* 微服务，无状态化架构，业务集群化部署，有心跳检测，能最短时间检测到不可用的服务。
* 通过熔断、限流，解决流量过载问题，提供过载保护
* 重视web安全，解决攻击和XSS问题', 1, 1, 'technology-talk/arch/system/【高并发、高性能、高可用】系统设计经验.md', 1, NOW(3)),
  (1003, 208, '什么是熔断？', '什么是熔断？', '熔断，其实是对调用链路中某个资源出现不稳定状态时（如：调用超时或异常比例升高），对这个资源的调用进行限制，让请求快速失败，避免影响到其它的资源而导致级联错误。

当资源被降级后，在接下来的`降级时间窗口`内，对该资源的调用都自动熔断（默认是抛出 `BlockException`）

目前市面上的熔断框架很多，如：`Sentinel`、`Hystrix`、`Resilience4j` 等，这些框架的设计理念都差不多。

本文重点讲下 Sentinel 是如何在项目中使用的

Sentinel (分布式系统的流量防卫兵) 是阿里开源的一套用于服务容错的综合性解决方案。它以流量为切入点, 从`流量控制`、`熔断降级`、`系统负载保护`等多个维度来保护服务的稳定性。', 2, 1, 'technology-talk/arch/system/外部接口大量超时，把整个系统拖垮，引发雪崩！', 1, NOW(3)),
  (1004, 208, '讲了这么多了，可能有同学要问了，那什么是中台？', '讲了这么多了，可能有同学要问了，那什么是中台？', '> 中台是`企业级能力复用平台`。 抽象核心的底层能力，平台化包装，快速赋能前台业务。通过底层的确定性来应对前台业务的不确定性。

**可能有同学会问，平台化和中台化有什么区别？**

`关于这个问题，ThoughtWorks首席咨询师王健老师给出了很好的解释！`

> 中台化是平台化的下一站，是平台不断对于自身治理演进、打破技术边界、逐渐拥抱业务、容纳业务、具备更强的业务属性的过程。中台关注为前台业务赋能，真正为前台而生。

划重点：中台的诞生就是为了更好的服务前台，如果前台业务单一，或业务逻辑并不复杂，其实没必要花那么大的精力搞中台建设，得不偿失。', 2, 1, 'technology-talk/arch/system/中台不是万能药！.md', 1, NOW(3)),
  (1005, 208, '前台、中台、后台的定位分别是什么？', '前台、中台、后台的定位分别是什么？', '* 前台：直接面向用户，讲究的轻量化、灵活多变、快速响应、快速上线
* 中台：直接为前台提供服务，讲究的核心能力抽象、配置化、稳定、以不变应万变
* 后台：主要负责企业的核心数据，设计企业安全、审计、合规等法律限制，对稳定性、安全性有较高要求。', 1, 1, 'technology-talk/arch/system/中台不是万能药！.md', 1, NOW(3)),
  (1006, 208, '如何建设中台？', '如何建设中台？', '中台建设没有固定模板，不同公司的设计方案也是千差万别。把控一点，能快速响应前台业务需求。一般企业会设计类似流程引擎这种支持通过`界面拖拽`的方式，来配置不同的业务流程。

平台提供了若干基础组件功能，定义好每个组件的规范、输入、输出，不同业务流程通过选择不同模块来编排自己的业务流程，从而快速满足业务需求。

对变化频繁的接口，我们会设计`SPI接口`，支持业务方`自定义代码实现`，`动态加载`到我们的平台，然后由平台统一调度请求。

当然不同人开发的接口性能也不太一样，发布前除了要做性能压测外，我们还会提供一些基础服务治理功能，比如：`接口超时处理`、`重试机制`、`流量控制`、`降级`、`熔断`等稳定性方案，保障系统的高可用。', 2, 1, 'technology-talk/arch/system/中台不是万能药！.md', 1, NOW(3)),
  (1007, 208, '中台建设可能遇到的问题？', '中台建设可能遇到的问题？', '任何事情都不会是一帆风顺，搭建中台也会遇到很多问题，遇到最多的就是，这个功能到底是由中台来做，还是由业务研发来做？

这个很容易导致中台部门和业务部门之间的扯皮，严重影响业务的落地速度。这就需要一个强有力、善于跨部门沟通的中台负责人，对该业务领域有丰富的业务经验，能从技术视角预测未来的业务走势，从而对功能归属做出定位判断，再结合强有力的沟通，推动该事情落地。

当然，这个结论是否正确，还需要漫长的时间验证，长时间的正确决策会慢慢巩固你的中台权威，形成正向循环。

中台建设是一个自上而下的过程，大家是一个集体，一荣俱荣，千万不能有小帮派思想，一盘散沙很难成事，这个需要总负责人在公司有很高的话语权。甚至把中台建设设定成公司的战略，跟业务有着对等的地位。

当然也不是所有的公司都要搞中台建设，如果公司的业务线不超过三条，或者各业务线的通用模块并不多，最好不要搞中台建设。中台建设是业务发展到一定阶段的自然产物，当投入和产出严重失衡时，我们便可以从中台视角，通过技术手段对其优化，降低公司成本。', 2, 1, 'technology-talk/arch/system/中台不是万能药！.md', 1, NOW(3)),
  (1008, 140, '进程和线程的区别？', '进程和线程的区别？', '- 调度：进程是资源管理的基本单位，线程是程序执行的基本单位。
- 切换：线程上下文切换比进程上下文切换要快得多。
- 拥有资源： 进程是拥有资源的一个独立单位，线程不拥有系统资源，但是可以访问隶属于进程的资源。
- 系统开销： 创建或撤销进程时，系统都要为之分配或回收系统资源，如内存空间，I/O设备等，OS 所付出的开销显著大于在创建或撤销线程时的开销，进程切换的开销也远大于线程切换的开销。', 1, 1, 'technology-talk/interview/tech/操作系统那点破事.md', 1, NOW(3)),
  (1009, 140, '线程与协程的区别？', '线程与协程的区别？', '- 线程和进程都是同步机制，而协程是异步机制。
- 线程是抢占式，而协程是非抢占式的。需要用户释放使用权切换到其他协程，因此同一时间其实只有一个协程拥有运行权，相当于单线程的能力。
- 一个线程可以有多个协程，一个进程也可以有多个协程。
- 协程不被操作系统内核管理，而完全是由程序控制。线程是被分割的CPU资源，协程是组织好的代码流程，线程是协程的资源。但协程不会直接使用线程，协程直接利用的是执行器关联任意线程或线程池。
- 协程能保留上一次调用时的状态', 2, 1, 'technology-talk/interview/tech/操作系统那点破事.md', 1, NOW(3)),
  (1010, 140, '进程间通信方式有哪些？', '进程间通信方式有哪些？', '<br />答案：<br />1、管道<br />管道这种通讯方式有两种限制，一是半双工的通信，数据只能单向流动，二是只能在具有亲缘关系的进程间使用。进程的亲缘关系通常是指父子进程关系。<br />管道可以分为两类：匿名管道和命名管道。匿名管道是单向的，只能在有亲缘关系的进程间通信； 命名管道以磁盘文件的方式存在，可以实现本机任意两个进程通信。<br />2、信号 <br />信号是一种比较复杂的通信方式，信号可以在任何时候发给某一进程，而无需知道该进程的状态。   <br />**Linux系统中常用信号：**
:::info
（1）SIGHUP：用户从终端注销，所有已启动进程都将收到该进程。系统缺省状态下对该信号的处理是终止进程。<br />（2）SIGINT：程序终止信号。程序运行过程中，按 Ctrl+C 键将产生该信号。<br />（3）SIGQUIT：程序退出信号。程序运行过程中，按 Ctrl+\\\\ 键将产生该信号。<br />（4）SIGBUS和SIGSEGV：进程访问非法地址。<br />（5）SIGFPE：运算中出现致命错误，如除零操作、数据溢出等。<br />（6）SIGKILL：用户终止进程执行信号。shell下执行 kill -9 发送该信号。<br />（7）SIGTERM：结束进程信号。shell下执行 kill 进程pid 发送该信号。<br />（8）SIGALRM：定时器信号。<br />（9）SIGCLD：子进程退出信号。如果其父进程没有忽略该信号也没有处理该信号，则子进程退出后将形成僵尸进程。
:::

3、信号量：信号量是一个计数器，可以用来控制多个进程对共享资源的访问。它常作为一种锁机制，防止某进程正在访问共享资源时，其他进程也访问该资源。因此，主要作为进程间以及同一进程内不同线程之间的同步手段。<br />4、消息队列：消息队列是消息的链接表，包括Posix消息队列和System V消息队列。有足够权限的进程可以向队列中添加消息，被赋予读权限的进程则可以读走队列中的消息。消息队列克服了信号承载信息量少，管道只能承载无格式字节流以及缓冲区大小受限等缺点。<br />5、共享内存：共享内存就是映射一段能被其他进程所访问的内存，这段共享内存由一个进程创建，但多个进程都可以访问。共享内存是最快的 IPC 方式，它是针对其他进程间通信方式运行效率低而专门设计的。它往往与其他通信机制，如信号量，配合使用，来实现进程间的同步和通信。<br />6、Socket：与其他通信机制不同的是，它可用于不同机器间的进程通信。 

  **优缺点：**

- 管道：速度慢，容量有限；
- Socket：任何进程间都能通讯，但速度慢；
- 消息队列：容量受到系统限制，且要注意第一次读的时候，要考虑上一次没有读完数据的问题；
- 信号量：不能传递复杂消息，只能用来同步；
- 共享内存区：能够很容易控制容量，速度快，但要保持同步，比如一个进程在写的时候，另一个进程要注意读写的问题，相当于线程中的线程安全，当然，共享内存区同样可以用作线程间通讯，不过没这个必要，线程间本来就已经共享了同一进程内的一块内存', 3, 1, 'technology-talk/interview/tech/操作系统那点破事.md', 1, NOW(3)),
  (1011, 140, '什么是分页？', '什么是分页？', '<br />把内存空间划分为大小相等且固定的块，作为主存的基本单位。因为程序数据存储在不同的页面中，而页面又离散的分布在内存中，因此需要一个页表来记录映射关系，以实现从页号到物理块号的映射。

访问分页系统中内存数据需要两次的内存访问 (一次是从内存中访问页表，从中找到指定的物理块号，加上页内偏移得到实际物理地址；第二次就是根据第一次得到的物理地址访问内存取出数据)。 <br />', 1, 1, 'technology-talk/interview/tech/操作系统那点破事.md', 1, NOW(3)),
  (1012, 140, '什么是虚拟内存？', '什么是虚拟内存？', '<br />虚拟内存就是说，让物理内存扩充成更大的逻辑内存，从而让程序获得更多的可用内存。虚拟内存使用部分加载的技术，让一个进程或者资源的某些页面加载进内存，从而能够加载更多的进程，甚至能加载比内存大的进程，这样看起来好像内存变大了，这部分内存其实包含了磁盘或者硬盘，并且就叫做虚拟内存。', 1, 1, 'technology-talk/interview/tech/操作系统那点破事.md', 1, NOW(3)),
  (1013, 140, '虚拟内存的实现方式?', '虚拟内存的实现方式?', '<br />虚拟内存中，允许将一个作业分多次调入内存。釆用连续分配方式时，会使相当一部分内存空间都处于暂时或 永久 的空闲状态，造成内存资源的严重浪费，而且也无法从逻辑上扩大内存容量。因此，虚拟内存的实需要建立在离散分配的内存管理方式的基础上。

**虚拟内存的实现有以下三种方式：**

- 请求分页存储管理
- 请求分段存储管理
- 请求段页式存储管理', 1, 1, 'technology-talk/interview/tech/操作系统那点破事.md', 1, NOW(3)),
  (1014, 140, '中断和轮询的区别？', '中断和轮询的区别？', '<br />轮询：CPU对特定设备轮流询问。中断：通过特定事件提醒CPU。 <br />轮询：效率低等待时间长，CPU利用率不高。中断：容易遗漏问题，CPU利用率不高', 1, 1, 'technology-talk/interview/tech/操作系统那点破事.md', 1, NOW(3)),
  (1015, 140, '什么是用户态和内核态？', '什么是用户态和内核态？', '<br />1、内核态：内核态运行的程序可以访问计算机的任何数据和资源，不受限制，包括外围设备，比如网卡、硬盘等。处于内核态的 CPU 可以从一个程序切换到另外一个程序，并且占用 CPU 不会发生抢占情况。<br /> 2、用户态：用户态运行的程序只能受限地访问内存，只能直接读取用户程序的数据，并且不允许访问外围设备，用户态下的 CPU 不允许独占，也就是说 CPU 能够被其他程序获取。

将操作系统的运行状态分为用户态和内核态，主要是为了对访问能力进行限制，防止随意进行一些比较 危险的操作导致系统的崩溃，比如设置时钟、内存清理，这些都需要在内核态下完成 。', 2, 1, 'technology-talk/interview/tech/操作系统那点破事.md', 1, NOW(3)),
  (1016, 225, '如何写简历？', '如何写简历？', '面试官每天可能看几十上百封简历，一定让自己的简历突出，才能在茫茫人海中抓人眼球。

**一封优秀的简历有以下几个特点：**

- 排版一定要工整，不要搞些花里胡哨的东西 
- 中文和数字英文之间加上空格的话看起来会舒服一点
- 工作经历最好采用时间倒序排序，毕竟面试官关心的是最新的工作内容。
- 项目经历要简明扼要，避免长篇大论，关键突出自己的亮点。项目不在于多而在于精。
- 面试官一般是参照简历中的项目展开询问，所以简历上的内容一定要非常熟悉。比如，你写了高并发的项目经历，面试官大概率会很感兴趣围绕了高并发展开考察。
- 简历上不建议标注薪资
- 简历一定要真实，不要写自己不会的东西，或者带有欺骗性的东西

> 特别注意，作为一名技术人，简历中提到的技术术语一定要规范，给人一种很专业的感觉。比如：MySQL不要写成mysql，Java不要写成 java', 2, 1, 'technology-talk/interview/tech/面试那点破事.md', 1, NOW(3)),
  (1017, 225, '简历包含哪些内容？', '简历包含哪些内容？', '**1、个人信息**

主要包含姓名、电话、邮箱、籍贯、学历等个人基本信息。

**2、求职意向**

主要是个人的求职岗位，如：资深研发工程师、架构师、技术总监、团队负责人等

**3、教育经历**

主要包含起止时间、学校、专业、学历等

**4、专业技能**
这个是简历中的核心，是你的技术画像，可以让面试官先对你有个初步了解，你的技术方向，擅长点，是否满足求职岗位的需求。
在描述自己的专业技能时，结合自身情况，合理使用“了解、熟悉、精通” 等层级，保证真实，不要夸大

**5、工作经历**

主要是在每家公司任职的起始时间、公司名称、工作岗位，以及概要描述下主要工作内容

注意：一定要真实，现在大部分公司发offer前都会进行背调，如果有造假，很容易被发现。

**6、项目经历**

主要分为三小块内容。

- 项目描述。用简练的语言描述下项目核心内容，让面试官对这个项目有一个快速了解，方面你后面展开交流时，频道能对齐，不至于鸡同鸭讲
> 很多候选人感觉面试挺顺畅的，问题也都答上来了，最后却没了下文。很大一部分就是沟通没对齐，直白来讲，就是你一个人在那自 hign。
> 你仔细想想，如果面试官都没听懂你在说什么？又怎么能断定你很优秀，最后还不是被pass掉。

- 技术栈。如：spring boot、dubbo、kafka、redis、es、cobar、mysql 等
- 职责描述。主要是讲你在项目中承担什么角色，负责哪些功能模块的技术方案设计、代码开发等。

同时最好能列举几个有挑战的技术难点及解决方案，描述要言简意赅，不要搞成流水账，具体细节可以在面试时展开交流

**加分项（**项目亮点**）**，比如：

- 经过你的优化改造后，QSP 提升了多少；RT 降低了多少；
- 研发效率提升了多少；研发成本降低了多少；
- 系统扩展性方面有哪些优化？类似业务开发接入时间由之前的10天降为现在的2天
- 负责双十一大促营销活动的方案设计，单日 GMV 成交 1个亿 +
- 描述事项的关键点，从 0 到 1 搭建系统
- 负责 「营销系统」演进的架构设计
- 支持了社区的「 Feed 流动态」从 1.0 到 2.0 的升级
- 其他有挑战的事情（值得拿出来show）

> 该部分是整个面试过程的重点，面试官大部分时间是围绕着你参与的项目展开考察。
> 所以项目一定要非常熟悉，面试前最好在脑海中对简历里的项目像放电影一样做下复盘，清晰的还原当时的整个过程，加深印象。

**7、其他**

- 个人评价，如：良好的表达能力、沟通能力、团队协助能力、抗压能力等
- 个人获奖荣誉，如：自己的博客、参与开源框架 pr、发表的专利、学术论文、ACM竞赛获奖、之前公司拿过的一些荣誉奖项等
- 如果自己的 Github 活跃，也可以写上', 3, 1, 'technology-talk/interview/tech/面试那点破事.md', 1, NOW(3)),
  (1018, 225, '如何自我介绍？', '如何自我介绍？', '1、面带微笑，充满自信，控制好说话的语速，可以适当慢一点。注意把控好时间节奏，最好控制在3到5分钟

2、简单介绍下个人履历，呆过哪些公司，哪些岗位，负责过哪些事情，简历中的一些亮点项目可以在这里简单提下，吸引面试官的兴趣，为后面的深入面谈埋下伏笔。尤其是最近的项目可以重点介绍下。

3、工作中取得过什么业绩，个人收获哪些成长。适当拔下高度，比如：关注业务，主动思考技术如何更好的服务业务；有大局观，当面临团队合作不顺畅时，不计较个人得失，更关注公司层面拿结果。

4、个人的兴趣爱好，最好与工作相关。比如：阅读、写博客等

5、结束语，自我评价，比如：团队协助能力、拿结果能力。最好与面试的公司做下关联，非常喜欢 ××× 公司，××× 业务，巧妙的拉近与面试官的关系。

> 注意：核心是show 出自己的技术实力，擅长的技能，做过的一些成功的事情。', 2, 1, 'technology-talk/interview/tech/面试那点破事.md', 1, NOW(3)),
  (1019, 208, '面对复杂业务，架构设计有什么通用思路？', '面对复杂业务，架构设计有什么通用思路？', '业务理解转化能力、思维抽象能力、软件建模能力、高并发、高性能、高可用的分布式系统架构设计能力。

1、“拆分” ，降低架构复杂度。

2、认知抽象，架构模式有通用性

3、平台化、中台化系统衍化建设。

详细内容请查看 [人人都是架构师？？？谈何容易！！](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247484929&idx=1&sn=d8cb3306dea9f1b92fd30d59da3f536a&scene=21#wechat_redirect)', 2, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1020, 208, '谈谈对 DDD 的理解？', '谈谈对 DDD 的理解？', '通过实体、值对象、聚合根、领域服务、领域对象、限界上下文、资源库，指导微服务落地，将一个大的复杂业务域拆分成若干业务子域。定义领域模型（包含数据、行为），相似业务聚合。

更多内容，参考 [DDD是如何解决复杂业务扩展问题？](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247484859&idx=1&sn=bcf2167350e473d9fde2f03fe812086b&scene=21#wechat_redirect)', 2, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1021, 208, '项目中用过哪些设计模式？', '项目中用过哪些设计模式？', '工厂、装饰、克隆、代理、适配器、观察者、策略、模板、单例、责任链、门面等23种软件设计模式，这是软件开发的基本功，每一种设计模式都要非常熟悉。否则很难写出扩展性很高的代码。

之前写过三篇文章，每一种模式都有详细介绍：

[1、解决复杂业务架构，软件设计模式系列（第一期）](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247485170&idx=1&sn=b97e57fcc0af6101531b022e578bc64f&scene=21#wechat_redirect)

[2、解决复杂业务架构，软件设计模式系列（第二期）](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247485309&idx=1&sn=1209b7e3324440f7893847a935b3af5f&scene=21#wechat_redirect)

[3、解决复杂业务架构，软件设计模式系列（第三期）](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247485697&idx=1&sn=d0a3fd3fe1d5d70eb576d69d1d5a8399&scene=21#wechat_redirect)', 2, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1022, 208, '面对海量数据，什么是垂直拆分、水平拆分？', '面对海量数据，什么是垂直拆分、水平拆分？', '1、垂直拆分可以分为垂直分库、垂直分表

- **垂直分库**：结合DDD领域驱动设计，将一个大的业务域拆分为若干业务子域，比如电商可以拆分为商户、商品、库存、权限、会员、营销、交易、支付、履约、订单、结算、仓储、物流、财务等。每个子域都有自己独立的数据库。
- **垂直分表**：将一个有很多字段的表，按字段的大小、使用频率等特点，拆分为多张表。比如：将用户表拆分为 用户基本信息表 和 用户扩展表。

2、水平拆分

由于单台机器的性能有限，无法支撑海量数据存储。我们引入逻辑表概念，采用集群模式，将一张逻辑表拆分成多张物理表分散存储在不同服务器，通过分表键路由，比如：时间、区域、用户id等。

特点：虽然有多张表，但每张表的表结构都是一样的，区别是数据不一样。所有表的数据合并起来才是这个业务表的完整数据。

> 画外音：数据量大，就分表；并发高，就分库

更多内容，参考 [单台 MySQL 支撑不了这么多的并发请求，我们该怎么办？](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247484864&idx=1&sn=e25652505319d4d13dcf5fc8e265bcae&scene=21#wechat_redirect)', 2, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1023, 208, '分库分表，全局主键ID有哪些生成方案？', '分库分表，全局主键ID有哪些生成方案？', '* 1、UUID，生成的是 32 位的字符串，虽然可以做到全局唯一性，但我们一般推荐使用整型。
* 2、基于一个单表做自增主键
* 3、雪花算法，生成一个 64 位的 Long 类型数据。组成结构：正数位（占1位）+ 时间戳（占41位）+ 工作机器id（10位）+ 序列号部分（12位）
* 4、数据库号段模式，对不同的业务类型定义初始值和步长，业务系统引入SDK，本地缓存预申请一定数据量的主键ID值，满足一定的并发要求。
* 5、TinyID，滴滴的开源框架
* 6、Redis 的 incr 命令
* 7、Leaf，美团的开源框架
* 8、uid-generator，百度的开源框架', 2, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1024, 208, 'SQL 优化，有哪些方案？', 'SQL 优化，有哪些方案？', '1. SQL 查询时，尽量不要使用 select * ，而是 select 具体字段
2. 如果只有一条查询结果（或者最大值、最小值），建议使用 limit 1
3. where 语句中尽量避免使用 or来连接条件。or 可能会导致索引失效，从而全表扫描
4. 优化 limit 分页
5. 优化 like 语句，不要把 % 放到前面
6. where 语句的条件字段要充分，查询的数据都是有用的，避免在上层的业务代码中做 filter
7. 避免在 索引列使用mysql 内置函数、表达式操作，会导致索引失效
8. 优先使用 inner join，如果使用 left join  要小表驱动大表
9. 尽量避免在 where 语句中使用 ！= 、<>
10. 使用联合索引时，要注意索引列的顺序
11. where 、 order by 涉及的列上建索引，避免全表扫描
12. 尽量采用 `覆盖索引`，减少`回表`
13. 如果检索的结果不会有重复的记录，建议使用 union all 替换 union
14. 索引不宜太多，一般控制在 `5个`以内
15. 索引尽量避免建在有`大量重复数据的字段`上，如：性别
16. 尽量使用 varchar 代替 char
17. 如果字段类型是字符串，where 时一定要用引号括起来，否则会索引失效
18. 万能方案，使用 MySQL 自带的诊断命令 explain 分析优化 SQL

[MySQL的explain，你真的会用吗？](https://mp.weixin.qq.com/s/nmT-LCOyChTmbON3bCMoiA)

19. show profile分析，了解SQL执行的线程的状态以及消耗的时间
20. 数据量太大，考虑分库分表 或者借助 es 查询', 3, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1025, 208, '高性能，有哪些方案？', '高性能，有哪些方案？', '1. 流量入口采用LVS、Nginx， 通过负载均衡算法，将大流量压力均匀、平稳的分摊到下游的多台微服务机器上，从而减轻单台服务器的压力。
2. 性能不够，缓存来凑。引入多级缓存，如：Guava、caffeine 本地缓存、Redis 分布式缓存。但是要注意缓存key集中失效、穿透、雪崩、热点、大 key、缓存数据一致性、并发更新等问题。
3. 对于前端的一些 JS、CSS、图片等静态文件，可以借助 CDN 加速
4. 分库分表。关系型数据库存储，如果数据量过大可以分表，如果要提高吞吐量可以分库。当然一些复杂的查询可以借助 ES 来实现
5. DB 索引设计。设计表结构时，我们要考虑后期对表数据的查询操作，设计合理的索引结构，一旦表索引建立好了之后，也要注意后续的查询操作，避免索引失效。
6. 数据库的SQL 索引优化
7. 对于一些海量数据的存储与查询，可以考虑 NoSQL，如：Hbase、MongoDB、TiDB等
8. 异步化。梳理业务流程，非核心逻辑可以异步化处理，如：线程池、MQ、延迟任务等
9. 并行化。梳理业务流程，画出时序图，分清楚哪些是串行？哪些是并行？充分利用多核CPU的并行化处理能力
10. 引入 MQ 中间件，对大流量削峰填谷，借助 MQ 中间件对下游系统起到缓冲作用。
11. 缓存预热，如：大促秒杀，提前将热点数据预热到缓存中
12. 预计算，如：抢红包场景，可以提前计算好红包金额缓存起来，发红包时直接使用即可。
13. 减少 IO 次数。如：数据库和缓存的批量读写、RPC的批量接口调用、或者通过冗余数据的方式减少 RPC 调用。索引/分布式计算代替全表扫描、零拷贝减少IO复制次数、分库分表增加连接数
14. 减少 IO 数据包大小。如：采用轻量级的通信协议、`合适的数据结构`（比如 PB 协议）、去掉接口中的多余字段、减少缓存key的大小、压缩缓存value等。
15. 加快IO速度。`顺序读写`代替随机读写、硬件上SSD提升等；
16. 各种池化技术。如：HTTP请求池、线程池（考虑CPU密集型还是IO密集型设置核心参数）、数据库和Redis连接池等。
17. 代码逻辑优化。将一些多次查询的结果通过 Context 上下文传递，或者采用更高效的算法或者类
18. JVM 优化。如：新生代和老年代的大小、GC算法的选择等，尽可能减少GC频率和耗时。
19. 锁选择。如：读多写少的场景用乐观锁，或者考虑通过分段锁的方式减少锁冲突。', 3, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1026, 208, '高可用，有哪些方案？', '高可用，有哪些方案？', '1. 限流。保证系统最大可用性，如：秒杀。包括前端限流、Nginx接入层的限流、服务端的限流。
2. 熔断策略。对于网络不稳定，可以自动将接口熔断，并按配置的恢复时间检查恢复
3. 降级。临时关闭一些非核心业务，释放更多的系统资源让给核心业务。
4. 接口设置超时配置，防止慢请求拖垮系统，引发雪崩效应。
5. 接口重试、幂等策略
6. 故障转移。如果一个节点挂了，会自动将流量切到对等节点。如：Nginx、MySQL、Redis 都具备这种能力。
7. MQ场景的消息可靠性保证，如：producer端的重试机制、broker侧的持久化、consumer端的ack机制等。
8. 灰度发布，先小流量部署，观察系统日志和业务指标，等运行平稳后再推全量。
9. 监控报警：全方位的监控体系，包括最基础的CPU、内存、磁盘、网络的监控，以及Web服务器、JVM、数据库、各类中间件的监控和业务指标的监控。
10. 灾备演练：类似当前的“混沌工程”，对系统进行一些破坏性手段，观察局部故障是否会引起可用性问题。', 2, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1027, 208, '接口性能优化，有哪些技巧？', '接口性能优化，有哪些技巧？', '1. 优化代码逻辑，如：将一些无关联的操作并行化处理；多次查询，可以考虑采用Context上下文传递
2. 串行改为并行。对于没有上下文依赖的接口调用采用`并行化`处理，JDK 里面提供了 `CompleteFuture` 可以实现该功能。
3. 批量思想。`读写一样`，`批量操作`。比如：
   - 连续调用多次的单个查询，我们可以考虑合并请求，开批量接口。将一个 100次 循环的单个查询替换成一个支持 100 个id的批量查询。这里要特别说明一点，集合的大小要做限制，建议控制每次请求的记录条数在500以内。
   - `写操作`也是一样道理，可以批量处理。
4. 池化思想。如：线程池、对象池、数据库连接池、HttpClient 连接池、HTTP 的 Keep-Alive 长连接 等，避免资源频繁的创建和销毁，可以循环使用。
5. 线程池合理设计。线程池可以让任务并行处理，如果参数不合理，影响执行效率。重点关注几个参数：`核心线程数`、`最大线程数`、`阻塞队列`
6. 分批查询。避免一次查询太过数据，如果是远程接口可能导致接口超时，要做分页处理。将一次获取所有的数据的请求，改成分多次获取，每次只获取一部分用户的数据，最后进行合并和汇总。
7. 异步处理。将一些非核心的业务逻辑从`同步执行`中剥离出去，比如：发短信、邮件等，异步化来进行处理。有两种实现方式：
   - 封装成 `Runnable` 任务，交由`线程池`异步处理
   - 封装成 MQ 消息，借助 主流的 MQ 框架通过 `发布/订阅` 方式处理
8. 事件回调。如果被调用接口耗时很长，不要一直阻塞等待，可以参考` IO多路复用模型`，先去做别的事，等被调用接口处理完，通过`事件回调`，触发我们之前埋入的`回调函数`
9. 锁粒度。为了解决多线程并发修改某个共享数据，会引入`锁`，如：`synchronized`、`ReentrantLock` 、`Redis 分布式锁`  等。如果加锁的粒度过粗，影响接口的性能。只需要在`共享临界资源`加锁即可，不涉及共享资源的，就不必要加锁。
10. 缓存。`性能不够，缓存来凑`。借助 本地缓存 `Guava`、`Caffeine` 等；分布式缓存 `Redis` 、`memcached`等 来加速。两者通常可以互补，本地缓存没有网络开销，但受内存大小限制；分布式缓存能支持更大的容量上限，扩容更方便，但有约近似 1 ms 的网络开销。
   - 本地缓存和分布式缓存可以一起使用，但要注意`数据一致性`问题
11. 预热思想。提前把要经过复杂计算的数据计算好，并提前预热到缓存中，需要时，直接去缓存取即可。
   - 像一些`双 11`大促活动，一般会将各种热点数据通过`定时任务`提前预热
12. 数据异构。将一些高频信息，经过计算或转换处理后，存储到缓存中，下次可以直接使用，避免每次查库
13. 索引优化。不管什么业务都涉及到数据库存储，SQL 索引优化是关键点，如：`有没有加索引`、`加了索引有没有生效`、`索引建立是否合理` 等。
   - 写完 SQL 后，可以通过 `explain` 查看执行计划
   - 前文「SQL优化，有哪些方案？」列举了详细优化方案
14. 开启数据库的慢查询日志，有针对性的收集`慢 SQL`，并优化
15. 避免`大事务`。事务中避免嵌套 `RPC` 远程调用
16. 深度分页。会扫描太多的数据行，可以考虑`标签记录法`，根据`主键id`快速定位、查找
17. 分库分表。数据量大时，可以分库分表
18. 数据压缩。如果涉及网络传输，选型合适的序列化框架，并对内容压缩
19. 优化程序结构。比如，你的程序创建多不必要的对象、或者程序逻辑混乱，多次重复查数据库、又或者你的实现逻辑算法不是最高效的，等等。
20. 数据过期策略。一张表的数据量太大的情况下，对DB的查询性能是非常有影响的，建议合理的设计数据过期策略，历史数据定期放入history表，或者备份到离线表中，减少线上大量数据的存储。
21. 技术方案
   - 如果数据太大，可以先采用`文件/MQ` 等暂存数据，后面再慢慢保存到数据库中
22. NoSQL。如果数据量太多，可以考虑引入 NoSQL，比如 Hbase、Elasticsearch 等
23. 增加监控，比如 ：`Prometheus`，将一些慢响应接口、或者异常太多接口收集起来，用于`监控`、`报警`。我们可以采集的信息：
   - 接口响应时间
   - 调用第三方服务耗时
   - 慢查询sql耗时
   - cpu使用情况
   - 内存使用情况
   - 磁盘使用情况
   - 数据库使用情况
24. 也可以引入类似 `skywalking` 这样的分布式链路跟踪系统，串联一个接口请求的完整链路。支持查看链路的各个环节的耗时，指导我们优化系统。
25. 与业务保持沟通，找到平衡点。技术不是万能的，无论白猫黑猫，能抓到老鼠就是好猫', 3, 1, 'technology-talk/interview/tech/项目亮点.md', 1, NOW(3)),
  (1028, 230, 'Docker 三大核心是什么？', 'Docker 三大核心是什么？', '<br />**1、镜像**<br />Docker的镜像是创建容器的基础，类似虚拟机的快照，可以理解为一个面向Docker容器引擎的只读模板。<br />通过镜像启动一个容器，一个镜像是一个可执行的包，其中包括运行应用程序所需要的所有内容包含代码，运行时间，库、环境变量、和配置文件。<br />Docker镜像也是一个压缩包，只是这个压缩包不只是可执行文件，环境部署脚本，它还包含了完整的操作系统。因为大部分的镜像都是基于某个操作系统来构建，所以很轻松的就可以构建本地和远端一样的环境，这也是Docker镜像的精髓。<br />**2、 容器**<br />Docker 容器是从镜像创建的运行实例，它可以被启动、停止和删除。所创建的每一个容器都是相互隔离、互不可见，以保证平台的安全性。可以把容器看做是一个简易版的linux环境（包括root用户权限、镜像空间、用户空间和网络空间等）和运行在其中的应用程序。<br />**3、仓库**<br />仓库注册服务器上往往存放着多个仓库，每个仓库中包含了多个镜像，每个镜像有不同标签（tag）。<br />仓库分为公开仓库（Public）和私有仓库（Private）两种形式。<br />最大的公开仓库是 Docker Hub：https://hub.docker.com，存放了数量庞大的镜像供用户下载。', 2, 1, 'technology-talk/interview/tech/Docker 那点破事.md', 1, NOW(3)),
  (1029, 230, 'Docker 后台的标准运行过程是什么？', 'Docker 后台的标准运行过程是什么？', '<br />当利用 docker run 来创建容器时， Docker 在后台的标准运行过程是：

- 检查本地是否存在指定的镜像。当镜像不存在时，会从公有仓库下载；
- 利用镜像创建并启动一个容器；
- 分配一个文件系统给容器，在只读的镜像层外面挂载一层可读写层；
- 从宿主主机配置的网桥接口中桥接一个虚拟机接口到容器中；
- 分配一个地址池中的 IP 地址给容器；
- 执行用户指定的应用程序，执行完毕后容器被终止运行。', 1, 1, 'technology-talk/interview/tech/Docker 那点破事.md', 1, NOW(3)),
  (1030, 230, '什么是 Docker 镜像？', '什么是 Docker 镜像？', '<br />Docker image 是 Docker 容器的源。换言之，Docker images 用于创建 Docker 容器（containers）。镜像（Images）通过 Docker build 命令创建。<br />当 run 镜像时，它启动成一个 容器（container）进程。 做好的镜像由于可能非常庞大，常注册存储在诸如 registry.hub.docker.com 这样的公共平台上。<br />镜像常被分层设计，每层可单独成为一个小镜像，由多层小镜像再构成大镜像，这样碎片化的设计为了使镜像在互联网上共享时，最小化传输数据。', 2, 1, 'technology-talk/interview/tech/Docker 那点破事.md', 1, NOW(3)),
  (1031, 230, '如何控制容器占用系统资源（CPU，内存）的份额？', '如何控制容器占用系统资源（CPU，内存）的份额？', '<br />使用docker create命令创建容器或使用docker run 创建并运行容器的时候，可以使用 -c|–cpu-shares[=0]参数来调整同期使用CPU的权重，使用-m|–memory参数来调整容器使用内存的大小。', 1, 1, 'technology-talk/interview/tech/Docker 那点破事.md', 1, NOW(3)),
  (1032, 230, 'Dockerfile 配置文件中的 COPY 和 ADD 指令有什么不同？', 'Dockerfile 配置文件中的 COPY 和 ADD 指令有什么不同？', '<br />虽然 ADD 和 COPY 功能相似，推荐 COPY <br />那是因为 COPY 比 ADD 更直观易懂。 COPY 只是将本地文件拷入容器这么简单，而 ADD 有一些其它特性功能（诸如，本地归档解压和支持远程网址访问等），这些特性在指令本身体现并不明显。因此，有必要使用 ADD 指令的最好例子是需要在本地自动解压归档文件到容器中的情况，如 ADD rootfs.tar.xz', 1, 1, 'technology-talk/interview/tech/Docker 那点破事.md', 1, NOW(3)),
  (1033, 230, 'Docker 应用流程？', 'Docker 应用流程？', '<br />1、开始，所有都有赖于 `Dockerfile` 配置文件。Dockerfile 配置文件就是创建 Docker image (镜像) 的源代码。<br />2、一旦 Dockerfile 配置好了，通过 `Docker build `命令并生成 image（镜像） ，镜像就是 Dockerfile 配置文件中 `源代码` 的 `编译版本`。<br />3、生成镜像 ，就可以在 registry（注册中心） 发布它。镜像类似 git 的资源库 ，你可以推送你的镜像，也可取回库中的镜像<br />4、可以使用 镜像 去启动运行 containers（容器）。运行中的容器在许多方面，与虚拟机非常相似，但容器的运行不需要依赖虚拟管理软件的运行。', 2, 1, 'technology-talk/interview/tech/Docker 那点破事.md', 1, NOW(3)),
  (1034, 230, 'Docker Image 和 Docker Layer 区别？', 'Docker Image 和 Docker Layer 区别？', '<br />1、Image ：一个 Docker Image 是由一系列 Docker 只读层（read-only Layer） 创建出来的。<br />2、Layer： 在 Dockerfile 配置文件中完成的一条配置指令，即表示一个 Docker 层（Layer）。<br />如下 Dockerfile 文件包含 4 条指令，每条指令创建一个层（Layer）。
```
FROM ubuntu:15.04
RUN make /app
COPY . /app
CMD python /app/app.py
```
注意：每层只对其前一层进行某些进化', 2, 1, 'technology-talk/interview/tech/Docker 那点破事.md', 1, NOW(3)),
  (1035, 102, '并行与并发的区别？', '并行与并发的区别？', '从操作系统的角度来看，线程是CPU分配的最小单位。

1、并行就是同一时刻，两个线程都在执行。要求有两个CPU去分别执行两个线程。

2、并发就是同一时刻，只有一个执行，但是一个时间段内，两个线程都执行了。并发的实现依赖于CPU切换线程，因为切换的时间特别短，所以基本对于用户是无感知的。', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1036, 102, '什么是进程？线程？', '什么是进程？线程？', '1、进程：进程是代码在数据集合上的一次运行活动，是操作系统进行资源分配和调度的基本单位。

2、线程：线程是进程的一个执行路径，一个进程中至少有一个线程，进程中的多个线程共享进程的资源，线程是处理器任务调度和执行的基本单位。

**资源开销：**

每个进程都有独立的代码和数据空间（程序上下文），程序之间的切换会有较大的开销；线程可以看做轻量级的进程，同一类线程共享代码和数据空间，每个线程都有自己独立的运行栈和程序计数器（PC），线程之间切换的开销小。

**包含关系：**

如果一个进程内有多个线程，则执行过程不是一条线的，而是多条线（线程）共同完成的；线程是进程的一部分，所以线程又被称为轻量级进程。

**内存分配：**

同一进程的线程共享本进程的地址空间和资源，而进程之间的地址空间和资源是相互独立的

**影响关系：**

一个进程崩溃后，在保护模式下不会影响其他进程。但是一个线程崩溃整个进程都死掉。所以多进程要比多线程健壮。

**执行过程：**

每个独立的进程有程序运行的入口， 顺序执行序列和程序出口。但是线程不能独立执行，必须依存在应用程序中，由应用程序提供多个线程执行控制，两者均可并发执行', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1037, 102, '线程有几种创建方式？', '线程有几种创建方式？', 'Java中创建线程主要有三种方式，分别为继承Thread类、实现Runnable接口、实现Callable接口。

* 1、继承Thread类，重写run()方法，调用start()方法启动线程
* 2、实现 Runnable 接口，重写run()方法，最后通过Thread包装并启动 new Thread(task).start();
* 3、实现Callable接口，重写call()方法，这种方式可以通过 FutureTask 获取任务执行的返回值', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1038, 102, 'Runnable 和 Callable 区别？', 'Runnable 和 Callable 区别？', '* 1、Callable 重写的方法是call()，Runnable 重写的方法是run()。 
* 2、Callable的任务执行后有返回值，而 Runnable 任务无返回值 
* 3、Call方法会抛出异常，run方法不可以 
* 4、运行Callable任务可以拿到一个Future对象，表示异步计算的结果。它提供了检查计算是否完成的方法，以等待计算的完成，并检索计算的结果。通过Future对象可以了解任务执行情况，可取消任务的执行，还可获取执行结果', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1039, 102, '为什么调用 start() 方法时会执行 run() 方法，那怎么不直接调用 run() 方法？', '为什么调用 start() 方法时会执行 run() 方法，那怎么不直接调用 run() 方法？', 'JVM 执行 start 方法，会先创建一条线程，由创建出来的新线程去执行thread的run方法，这才起到多线程的效果。
如果直接调用Thread的run()方法，那么run方法还是运行在主线程中，相当于顺序执行，就起不到多线程的效果。', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1040, 102, '线程有哪些常用的调度方法？', '线程有哪些常用的调度方法？', '**1、线程等待与通知**

在Object类中有一些函数可以用于线程的等待与通知。

**线程等待的方法：**

- wait()：当一个线程A调用一个共享变量的 wait()方法时， 线程A会被阻塞挂起， 发生下面几种情况才会返回 ：
   - （1） 线程A调用了共享对象 notify()或者 notifyAll()方法；
   - （2）其他线程调用了线程A的 interrupt() 方法，线程A抛出InterruptedException异常返回。
- wait(long timeout) ：这个方法相比 wait() 方法多了一个超时参数，它的不同之处在于，如果线程A调用共享对象的wait(long timeout)方法后，没有在指定的 timeout ms时间内被其它线程唤醒，那么这个方法还是会因为超时而返回。
- wait(long timeout, int nanos)，其内部调用的是 wait(long timout）函数。

**唤醒线程方法：**

- notify() : 一个线程A调用共享对象的 notify() 方法后，会唤醒一个在这个共享变量上调用 wait 系列方法后被挂起的线程。一个共享变量上可能会有多个线程在等待，具体唤醒哪个等待的线程是随机的。
- notifyAll() ：不同于在共享变量上调用 notify() 函数会唤醒被阻塞到该共享变量上的一个线程，notifyAll()方法则会唤醒所有在该共享变量上由于调用 wait 系列方法而被挂起的线程。

Thread类也提供了一个方法用于等待的方法：

- join()：如果一个线程A执行了thread.join()语句，其含义是：当前线程A等待thread线程终止之后才 从`thread.join()`返回。

**2、线程休眠**

- sleep(long millis) :Thread类中的静态方法，当一个执行中的线程A调用了Thread 的sleep方法后，线程A会暂时让出指定时间的执行权，但是线程A所拥有的监视器资源，比如锁还是持有不让出的。指定的睡眠时间到了后该函数会正常返回，接着参与 CPU 的调度，获取到 CPU 资源后就可以继续运行。

**3、让出优先权**

- yield() ：Thread类中的静态方法，当一个线程调用 yield 方法时，实际就是在暗示线程调度器当前线程请求让出自己的CPU 。

**4、线程中断**

Java 中的线程中断是一种线程间的协作模式，通过设置线程的中断标志并不能直接终止该线程的执行，而是被中断的线程根据中断状态自行处理。

- void interrupt() ：中断线程，例如，当线程A运行时，线程B可以调用线程 interrupt() 方法来设置线程的中断标志为true 并立即返回。设置标志仅仅是设置标志，线程A实际并没有被中断， 会继续往下执行。
- boolean isInterrupted() 方法：检测当前线程是否被中断。
- boolean interrupted() 方法：检测当前线程是否被中断，与 isInterrupted 不同的是，该方法如果发现当前线程被中断，则会清除中断标志。', 3, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1041, 102, '线程有几种状态？', '线程有几种状态？', 'Java 线程有六种状态：

| **状态** | **说明** |
| --- | --- |
| NEW | 初始状态：线程被创建，但还没有调用start()方法 |
| RUNNABLE | 运行状态：Java线程将操作系统中的就绪和运行两种状态笼统的称作“运行” |
| BLOCKED | 阻塞状态：表示线程阻塞于锁 |
| WAITING | 等待状态：表示线程进入等待状态，进入该状态表示当前线程需要等待其他线程做出一些特定动作（通知或中断） |
| TIME_WAITING | 超时等待状态：该状态不同于 WAITIND，它是可以在指定的时间自行返回的 |
| TERMINATED | 终止状态：表示当前线程已经执行完毕 |', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1042, 102, '什么是线程上下文切换？', '什么是线程上下文切换？', '使用多线程的目的是为了充分利用CPU，但是我们知道，并发其实是一个CPU来处理多个线程。

为了让用户感觉多个线程是在同时执行的， CPU 资源的分配采用了时间片轮转也就是给每个线程分配一个时间片，线程在时间片内占用 CPU 执行任务。当线程使用完时间片后，就会处于就绪状态并让出 CPU 让其他线程占用，这就是上下文切换。', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1043, 102, '线程间有哪些通信方式？', '线程间有哪些通信方式？', '**1、volatile和synchronized关键字**

关键字volatile可以用来修饰字段（成员变量），就是告知程序任何对该变量的访问均需要从共享内存中获取，而对它的改变必须同步刷新回共享内存，它能保证所有线程对变量访问的可见性。

关键字synchronized可以修饰方法或者以同步块的形式来进行使用，它主要确保多个线程在同一个时刻，只能有一个线程处于方法或者同步块中，它保证了线程对变量访问的可见性和排他性。

**2、等待/通知机制**

可以通过Java内置的等待/通知机制（wait()/notify()）实现一个线程修改一个对象的值，而另一个线程感知到了变化，然后进行相应的操作。

**3、管道输入/输出流**

管道输入/输出流和普通的文件输入/输出流或者网络输入/输出流不同之处在于，它主要用于线程之间的数据传输，而传输的媒介为内存。

管道输入/输出流主要包括了如下4种具体实现：PipedOutputStream、PipedInputStream、 PipedReader和PipedWriter，前两种面向字节，而后两种面向字符。

**4、使用Thread.join()**

如果一个线程A执行了thread.join()语句，其含义是：当前线程A等待thread线程终止之后才从thread.join()返回。线程Thread除了提供join()方法之外，还提供了 join(long millis) 和 join(long millis,int nanos) 两个具备超时特性的方法。

**5、使用ThreadLocal**

ThreadLocal，即线程变量，是一个以ThreadLocal对象为键、任意对象为值的存储结构。这个结构被附带在线程上，也就是说一个线程可以根据一个ThreadLocal对象查询到绑定在这个线程上的一个值。

可以通过 set(T) 方法来设置一个值，在当前线程下再通过get()方法获取到原先设置的值。', 3, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1044, 102, '原子性、可见性、有序性的理解？', '原子性、可见性、有序性的理解？', '原子性、有序性、可见性是并发编程中非常重要的基础概念，JMM的很多技术都是围绕着这三大特性展开。

**1、原子性**：原子性指的是一个操作是不可分割、不可中断的，要么全部执行并且执行的过程不会被任何因素打断，要么就全都不执行。

**2、可见性**：可见性指的是一个线程修改了某一个共享变量的值时，其它线程能够立即知道这个修改。

**3、有序性**：有序性指的是对于一个线程的执行代码，从前往后依次执行，单线程下可以认为程序是有序的，但是并发时有可能会发生指令重排。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1045, 102, '什么是指令重排？', '什么是指令重排？', '在执行程序时，为了提高性能，编译器和处理器常常会对指令做重排序。重排序分3种类型。

1、编译器优化的重排序。编译器在不改变单线程程序语义的前提下，可以重新安排语句的执行顺序。

2、指令级并行的重排序。现代处理器采用了指令级并行技术（Instruction-Level Parallelism，ILP）来将多条指令重叠执行。如果不存在数据依赖性，处理器可以改变语句对应 机器指令的执行顺序。

3、内存系统的重排序。由于处理器使用缓存和读/写缓冲区，这使得加载和存储操作看上去可能是在乱序执行。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1046, 102, '什么是 AQS ？', '什么是 AQS ？', 'AbstractQueuedSynchronizer 抽象同步队列，简称 AQS ，它是Java并发包的基础，并发包中的锁就是基于 AQS 实现的。

- AQS是基于一个FIFO的双向队列，其内部定义了一个节点类Node，Node 节点内部的 SHARED 用来标记该线程是获取共享资源时被阻挂起后放入AQS 队列的， EXCLUSIVE 用来标记线程是 取独占资源时被挂起后放入AQS 队列
- AQS 使用一个 volatile 修饰的 int 类型的成员变量 state 来表示同步状态，修改同步状态成功即为获得锁，volatile 保证了变量在多线程之间的可见性，修改 State 值时通过 CAS 机制来保证修改的原子性
- 获取state的方式分为两种，独占方式和共享方式，一个线程使用独占方式获取了资源，其它线程就会在获取失败后被阻塞。一个线程使用共享方式获取了资源，另外一个线程还可以通过CAS的方式进行获取。
- 如果共享资源被占用，需要一定的阻塞等待唤醒机制来保证锁的分配，AQS 中会将竞争共享资源失败的线程添加到一个变体的 CLH 队列中。

先简单了解一下CLH：Craig、Landin and Hagersten 队列，是 **单向链表实现的队列**。申请线程只在本地变量上自旋，**它不断轮询前驱的状态**，如果发现 **前驱节点释放了锁就结束自旋**

AQS 中的队列是 CLH 变体的虚拟双向队列，通过将每条请求共享资源的线程封装成一个节点来实现锁的分配：

AQS 中的 CLH 变体等待队列拥有以下特性：

- AQS 中队列是个双向链表，也是 FIFO 先进先出的特性
- 通过 Head、Tail 头尾两个节点来组成队列结构，通过 volatile 修饰保证可见性
- Head 指向节点为已获得锁的节点，是一个虚拟节点，节点本身不持有具体线程
- 获取不到同步状态，会将节点进行自旋获取锁，自旋一定次数失败后会将线程阻塞，相对于 CLH 队列性能较好', 3, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1047, 102, 'ReentrantLock 实现原理？', 'ReentrantLock 实现原理？', 'ReentrantLock 是可重入的独占锁，只能有一个线程可以获取该锁，其它获取该锁的线程会被阻塞而被放入该锁的阻塞队列里面。

看看ReentrantLock的加锁操作：

```java
 // 创建非公平锁
    ReentrantLock lock = new ReentrantLock();
    // 获取锁操作
    lock.lock();
    try {
        // 执行代码逻辑
    } catch (Exception ex) {
        // ...
    } finally {
        // 解锁操作
        lock.unlock();
    }
```
new ReentrantLock()构造函数默认创建的是非公平锁 NonfairSync。

**公平锁 FairSync**

1、公平锁是指多个线程按照申请锁的顺序来获取锁，线程直接进入队列中排队，队列中的第一个线程才能获得锁
2、公平锁的优点是等待锁的线程不会饿死。缺点是整体吞吐效率相对非公平锁要低，等待队列中除第一个线程以外的所有线程都会阻塞，CPU 唤醒阻塞线程的开销比非公平锁大

**非公平锁 NonfairSync**

1、非公平锁是多个线程加锁时直接尝试获取锁，获取不到才会到等待队列的队尾等待。但如果此时锁刚好可用，那么这个线程可以无需阻塞直接获取到锁
2、非公平锁的优点是可以减少唤起线程的开销，整体的吞吐效率高，因为线程有几率不阻塞直接获得锁，CPU 不必唤醒所有线程。缺点是处于等待队列中的线程可能会饿死，或者等很久才会获得锁

**默认创建的对象lock()的时候：**

1、如果锁当前没有被其它线程占用，并且当前线程之前没有获取过该锁，则当前线程会获取到该锁，然后设置当前锁的拥有者为当前线程，并设置 AQS 的状态值为1 ，然后直接返回。如果当前线程之前己经获取过该锁，则这次只是简单地把 AQS 的状态值加1后返回。
2、如果该锁已经被其他线程持有，非公平锁会尝试去获取锁，获取失败的话，则调用该方法线程会被放入 AQS 队列阻塞挂起。', 3, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1048, 102, 'ReentrantLock 如何实现公平锁？', 'ReentrantLock 如何实现公平锁？', 'new ReentrantLock() 构造函数默认创建的是非公平锁 NonfairSync

```
public ReentrantLock() {
    sync = new NonfairSync();
}
```

同时也可以在创建锁构造函数中传入具体参数创建 公平锁 FairSync

```
ReentrantLock lock = new ReentrantLock(true);
// true 代表公平锁，false 代表非公平锁
public ReentrantLock(boolean fair) {
    sync = fair ? new FairSync() : new NonfairSync();
}
```

FairSync、NonfairSync 代表公平锁和非公平锁，两者都是 ReentrantLock 静态内部类，只不过实现不同锁语义。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1049, 102, '非公平锁和公平锁的区别？', '非公平锁和公平锁的区别？', '1、非公平锁在调用 lock 后，首先就会调用 CAS 进行一次抢锁，如果这个时候恰巧锁没有被占用，那么直接就获取到锁返回了。

2、非公平锁在 CAS 失败后，和公平锁一样都会进入到 tryAcquire 方法，在 tryAcquire 方法中，如果发现锁这个时候被释放了（state == 0），非公平锁会直接 CAS 抢锁，但是公平锁会判断等待队列是否有线程处于等待状态，如果有则不去抢锁，乖乖排到后面。', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1050, 102, '什么是 ReadWriteLock？', '什么是 ReadWriteLock？', 'ReentrantLock 某些时候有局限，如果使用ReentrantLock，可能本身是为了防止线程A在写数据，线程B在读数据造成的数据不一致，但这样，如果线程C在读数据、线程D也在读数据，读数据是不会改变数据的，没有必要加锁，但是还是加锁了，降低了程序的性能。
因为这个，才诞生了读写锁ReadWriteLock。ReadWriteLock是一个读写锁接口，ReentrantReadWriteLock是ReadWriteLock接口的一个具体实现，实现了读写的分离，读锁是共享的，写锁是独占的，读和读之间不会互斥，读和写、写和读、写和写之间才会互斥，提升了读写的性能', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1051, 102, '什么是 CAS?', '什么是 CAS?', 'CAS叫做Compare And Swap，⽐较并交换，主要是通过处理器的指令来保证操作的原⼦性。是一种无锁的非阻塞算法的实现。

**CAS 指令包含 3 个参数**：共享变量的内存地址 A、预期的值 B 和要修改的新值 C。

只有当内存中地址 A 处的值等于 B 时，才能将内存中地址 A 处的值更新为新值 C。作为一条 CPU 指令，CAS 指令本身是能够保证原子性 。

- 更多内容，[CAS原理分析，解决银行转账ABA难题](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247484878&idx=1&sn=fdecdb6611c433d9ed3d80e899f8f9d4&scene=21#wechat_redirect)', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1052, 102, 'CAS 有什么风险？', 'CAS 有什么风险？', '**1、ABA 问题**

并发环境下，假设初始条件是A，去修改数据时，发现是A就会执行修改。但是看到的虽然是A，中间可能发生了A变B，B又变回A的情况。此时A已经非彼A，数据即使成功修改，也可能有问题。

**怎么解决ABA问题？**

- 加版本号

每次修改变量，都在这个变量的版本号上加1，这样，刚刚A->B->A，虽然A的值没变，但是它的版本号已经变了，再判断版本号就会发现此时的A已经被改过了。参考乐观锁的版本号，这种做法可以给数据带上了一种实效性的检验。
Java提供了AtomicStampReference类，它的compareAndSet方法首先检查当前的对象引用值是否等于预期引用，并且当前印戳（Stamp）标志是否等于预期标志，如果全部相等，则以原子方式将引用值和印戳标志的值更新为给定的更新值。

**2、循环时间长开销**

自旋CAS，如果一直循环执行，一直不成功，会给 CPU 带来非常大的执行开销。

**怎么解决循环性能开销问题？**

在Java中，很多使用自旋CAS的地方，会有一个自旋次数的限制，超过一定次数，就停止自旋。

**3、只能保证一个变量的原子操作**

CAS 保证的是对一个变量执行操作的原子性，如果对多个变量操作时，CAS 目前无法直接保证操作的原子性。

**怎么解决只能保证一个变量的原子操作问题？**

- 可以考虑改用锁来保证操作的原子性
- 可以考虑合并多个变量，将多个变量封装成一个对象，通过AtomicReference来保证原子性。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1053, 102, 'JUC 并发包用过哪些线程安全的类？', 'JUC 并发包用过哪些线程安全的类？', '- ConcurrentHashMap
- CountDownLatch、CyclicBarrier
- Semaphore
- BlockingQueue
- ThreadPoolExecutor
- ReentrantLock、ReentrantReadWriteLock
- CompletableFuture', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1054, 102, 'ThreadLocal 是什么？', 'ThreadLocal 是什么？', 'ThreadLocal，也就是线程本地变量。如果你创建了一个ThreadLocal变量，那么访问这个变量的每个线程都会有这个变量的一个本地拷贝，多个线程操作这个变量的时候，实际是操作自己本地内存里面的变量，从而起到线程隔离的作用，避免了线程安全问题。', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1055, 102, 'ThreadLocal 实现原理？', 'ThreadLocal 实现原理？', '- Thread类有一个类型为 ThreadLocal.ThreadLocalMap 的实例变量 threadLocals，即每个线程都有一个属于自己的ThreadLocalMap。
- ThreadLocalMap内部维护着Entry数组，每个Entry代表一个完整的对象，key是ThreadLocal本 身，value是ThreadLocal的泛型值。
- 每个线程在往ThreadLocal里设置值的时候，都是往自己的ThreadLocalMap里存，读也是以某个 ThreadLocal作为引用，在自己的map里找对应的key，从而实现了线程隔离。

**ThreadLocal 内存结构图：**

由结构图是可以看出：

- Thread对象中持有一个ThreadLocal.ThreadLocalMap的成员变量。
- ThreadLocalMap内部维护了Entry数组，每个Entry代表一个完整的对象，key是ThreadLocal本身，value是ThreadLocal的泛型值。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1056, 102, 'Java 有哪些原子性的方法？', 'Java 有哪些原子性的方法？', '1、循环原子类，例如 AtomicInteger，实现i++原子操作
2、JUC 包下的锁，如 ReentrantLock ，对i++操作加锁 lock.lock() 来实现原子性
3、使用 synchronized，对 i++ 操作加锁', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1057, 102, '原子操作类有哪些？', '原子操作类有哪些？', '当程序更新一个变量时，如果多线程同时更新这个变量，可能得到期望之外的值，比如变量i=1，A线程更新i+1，B线程也更新i+1，经过两个线程操作之后可能i不等于3，而是等于2。因为A和B线程在更新变量i的时候拿到的i都是1，这就是线程不安全的更新操作，**一般我们会使用synchronized来解决这个问题，synchronized会保证多线程不会同时更新变量i。**

其实除此之外，还有更轻量级的选择，Java从JDK 1.5开始提供了`java.util.concurrent.atomic`包，这个包中的原子操作类提供了一种用法简单、性能高效、线程安全地更新一个变量的方式。

因为变量的类型有很多种，所以在Atomic包里一共提供了13个类，属于4种类型的原子更新方式，分别是基本类型、原子更新数组、原子更新引用和原子更新属性（字段）。

`Atomic 包里的类基本都是使用Unsafe实现的包装类。`

1、**原子的方式更新基本类型**，Atomic包提供了以下3个类：

- AtomicBoolean：原子更新布尔类型。
- AtomicInteger：原子更新整型。
- AtomicLong：原子更新长整型。

**2、原子的方式更新数组里的某个元素**，Atomic包提供了以下4个类：

- AtomicIntegerArray：原子更新整型数组里的元素。
- AtomicLongArray：原子更新长整型数组里的元素。
- AtomicReferenceArray：原子更新引用类型数组里的元素。

**3、引用类型**。原子更新基本类型的AtomicInteger，只能更新一个变量，如果要原子更新多个变量，就需要使用这个原子更新引用类型提供的类。Atomic包提供了以下3个类：

- AtomicReference：原子更新引用类型。
- AtomicReferenceFieldUpdater：原子更新引用类型里的字段。
- AtomicMarkableReference：原子更新带有标记位的引用类型。可以原子更新一个布尔类型的标记位和引用类型。构造方法是AtomicMarkableReference（V initialRef，boolean initialMark）。

**4、字段更新**。如果需原子地更新某个类里的某个字段时，就需要使用原子更新字段类，Atomic包提供了以下3个类进行原子字段更新：

- AtomicIntegerFieldUpdater：原子更新整型的字段的更新器。
- AtomicLongFieldUpdater：原子更新长整型字段的更新器。
- AtomicStampedReference：原子更新带有版本号的引用类型。该类将整数值与引用关联起来，可用于原子的更新数据和数据的版本号，可以解决使用CAS进行原子更新时可能出现的 ABA问题。', 3, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1058, 102, 'AtomicInteger 实现原理？', 'AtomicInteger 实现原理？', '一句话概括：**使用CAS实现**。

以 AtomicInteger 的添加方法为例：

```
  public final int getAndIncrement() {
        return unsafe.getAndAddInt(this, valueOffset, 1);
    }
```
通过Unsafe类的实例来进行添加操作，来看看具体的CAS操作：
```
    public final int getAndAddInt(Object var1, long var2, int var4) {
        int var5;
        do {
            var5 = this.getIntVolatile(var1, var2);
        } while(!this.compareAndSwapInt(var1, var2, var5, var5 + var4));

        return var5;
    }
```
compareAndSwapInt 是一个native方法，基于CAS来操作int类型变量。其它的原子操作类基本都是大同小异。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1059, 102, '死锁的条件？', '死锁的条件？', '1、互斥条件：该资源任意一个时刻只由一个线程占用。

2、请求与保持条件：一个进程因请求资源而阻塞时，对已获得的资源保持不放。

3、环路等待：若干进程之间形成一种头尾相接的循环等待资源关系

4、不可剥夺：线程已获得的资源在末使用完之前不能被其他线程强行剥夺，只有自己使用完毕后才释 放资源。', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1060, 102, '死锁如何排查？', '死锁如何排查？', '可以使用jdk自带的命令行工具，基本就可以看到死锁的信息
1、使用 jps 查找运行的 Java 进程id：jps -l
2、使用 jstack 查看线程堆栈信息：jstack -l 进程id', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1061, 102, '什么是 CountDownLatch？', '什么是 CountDownLatch？', '1、协调子线程结束动作，等待所有子线程运行结束

例如：我们很多人喜欢玩的王者荣耀，开黑的时候，得等所有人都上线之后，才能开打。

2、协调子线程开始动作，统一各线程动作开始的时机

**3、核心方法**

- await()：等待latch 为0；
- boolean await(long timeout, TimeUnit unit)：等待latch减为0，但是可以设置超时时间。比如有玩家超时未确认，那就重新匹配，总不能为了某个玩家等到天荒地老。
- countDown()：latch数量减1；
- getCount()：获取当前的latch数量。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1062, 102, '什么是 CyclicBarrier？', '什么是 CyclicBarrier？', 'CyclicBarrier的字面意思：可循环使用（Cyclic）的屏障（Barrier）。它要做的事情是，让一 组线程到达一个屏障（也可以叫同步点）时被阻塞，直到最后一个线程到达屏障时，屏障才会开门，所有被屏障拦截的线程才会继续运行。

它和CountDownLatch类似，都可以协调多线程的结束动作，在它们结束后都可以执行特定动作，但是为什么要有CyclicBarrier，因为CyclicBarrier可以重复利用。', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1063, 102, 'CountDownLatch 和 CyclicBarrier 区别？', 'CountDownLatch 和 CyclicBarrier 区别？', '| **CyclicBarrier** | **CountDownLatch** |
| --- | --- |
| CyclicBarrier是可重用的，其中的线程会等待所有的线程完成任务。届时，屏障将被拆除，并可以选择性地做一些特定的动作。 | CountDownLatch是一次性的，不同的线程在同一个计数器上工作，直到计数器为0. |
| CyclicBarrier面向的是线程数 | CountDownLatch面向的是任务数 |
| 在使用CyclicBarrier时，你必须在构造中指定参与协作的线程数，这些线程必须调用await()方法 | 使用CountDownLatch时，则必须要指定任务数，至于这些任务由哪些线程完成无关紧要 |
| CyclicBarrier可以在所有的线程释放后重新使用 | CountDownLatch在计数器为0时不能再使用 |
| 在CyclicBarrier中，如果某个线程遇到了中断、超时等问题时，则处于await的线程都会出现问题 | 在CountDownLatch中，如果某个线程出现问题，其他线程不受影响 |', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1064, 102, '什么是 Semaphore？', '什么是 Semaphore？', 'Semaphore（信号量）是用来控制同时访问特定资源的线程数量，它通过协调各个线程，以保证合理的使用公共资源。

它可以用于做流量控制，特别是公用资源有限的应用场景，比如数据库连接。

Semaphore的构造方法Semaphore（int permits）接受一个整型的数字，表示可用的许可证数量。Semaphore（10）表示允许10个线程获取许可证，也就是最大并发数是10。Semaphore的用法也很简单，首先线程使用 Semaphore的acquire()方法获取一个许可证，使用完之后调用release()方法归还许可证，还可以用tryAcquire()方法尝试获取许可证。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1065, 102, '什么是 Exchanger？', '什么是 Exchanger？', 'Exchanger（交换者）是一个用于线程间协作的工具类。Exchanger用于进行线程间的数据交换。它提供一个同步点，在这个同步点，两个线程可以交换彼此的数据。

这两个线程通过 exchange方法交换数据，如果第一个线程先执行exchange()方法，它会一直等待第二个线程也执行exchange方法，当两个线程都到达同步点时，这两个线程就可以交换数据，将本线程生产出来的数据传递给对方。

假如两个线程有一个没有执行exchange()方法，则会一直等待，如果担心有特殊情况发生，避免一直等待，可以使用exchange(V x, long timeOut, TimeUnit unit)设置最大等待时长。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1066, 102, 'ThreadPoolExecutor 核心参数？', 'ThreadPoolExecutor 核心参数？', '线程池有七大参数，需要重点关注corePoolSize、maximumPoolSize、workQueue、handler这四个。

1、corePoolSize

此值是用来初始化线程池中核心线程数，当线程池中线程池数< corePoolSize时，系统默认是添加一个任务创建一个线程。当线程数 = corePoolSize时，新任务会追加到workQueue中。

2、maximumPoolSize

maximumPoolSize表示允许的最大线程数 = (非核心线程数+核心线程数)，当BlockingQueue也满了，但线程池中总线程数 < maximumPoolSize时候就会再次创建新的线程。

3、keepAliveTime

非核心线程 =(maximumPoolSize - corePoolSize ) ，非核心线程闲置下来不干活最多存活时间。

4、unit

线程池中非核心线程保持存活的时间的单位

- TimeUnit.DAYS; 天
- TimeUnit.HOURS; 小时
- TimeUnit.MINUTES; 分钟
- TimeUnit.SECONDS; 秒
- TimeUnit.MILLISECONDS; 毫秒
- TimeUnit.MICROSECONDS; 微秒
- TimeUnit.NANOSECONDS; 纳秒

5、workQueue

线程池等待队列，维护着等待执行的Runnable对象。当运行当线程数= corePoolSize时，新的任务会被添加到workQueue中，如果workQueue也满了则尝试用非核心线程执行任务，等待队列应该尽量用有界的。

6、threadFactory

创建一个新线程时使用的工厂，可以用来设定线程名、是否为daemon线程等等。

7、handler

corePoolSize、workQueue、maximumPoolSize都不可用的时候执行的拒绝策略。

**参数关联关系：**

- 判断线程池中的线程数，是否大于设置的核心线程数
- 如果没有，创建新线程来执行任务，直到达到核心线程数
- 此时进来的任务，放入队列，等待线程空闲时执行任务
- 如果队列已经满了，判断是否达到了线程池设置的最大线程数
- 如果已经达到了最大线程数，则执行指定的拒绝策略

其他：

- 更多内容，参考 [史上最全ThreadPoolExecutor梳理（上篇）](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247484808&idx=1&sn=13a9422ddf4e082b6e1e058debb91b62&scene=21#wechat_redirect)
- 更多内容，参考 [史上最全ThreadPoolExecutor梳理（下篇）](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247484808&idx=2&sn=2c54ec628da625b89cab0b6cf461f425&scene=21#wechat_redirect)', 3, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1067, 102, '线程池 拒绝策略？', '线程池 拒绝策略？', '* 1、AbortPolicy：直接丢弃任务，抛出异常，这是默认策略
* 2、CallerRunsPolicy：只用调用者所在的线程来处理任务
* 3、DiscardOldestPolicy：丢弃等待队列中最旧的任务，并执行当前任务
* 4、DiscardPolicy：直接丢弃任务，也不抛出异常
* 5、使用RejectedExecutionHandler接口，自定义实现', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1068, 102, '线程池 有哪几种工作队列？', '线程池 有哪几种工作队列？', '* 1、ArrayBlockingQueue：用数组实现的有界阻塞队列，按FIFO排序。
* 2、LinkedBlockingQueue：基于链表结构的阻塞队列，按FIFO排序任务，容量可以选择进行设置，不设置的话，将是一个无边界的阻塞队列，最大长度为Integer.MAX_VALUE，吞吐量通常要高于ArrayBlockingQuene；newFixedThreadPool线程池使用了这个队列
* 3、DelayQueue：是一个任务定时周期的延迟执行的队列。根据指定的执行时间从小到大排序，否则根据插入到队列的先后排序。newScheduledThreadPool线程池使用了这个队列。
* 4、PriorityBlockingQueue：有优先级的无界阻塞队列
* 5、SynchronousQueue：无元素存储的阻塞队列，每个插入操作必须等到另一个线程调用移除操作，否则插入操作一直处于阻塞状态，吞吐量通常要高于LinkedBlockingQuene，newCachedThreadPool线程池使用了这个队列。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1069, 102, '线程池 execute 和 submit 有什么区别？', '线程池 execute 和 submit 有什么区别？', '1、execute 用于提交不需要返回值的任务

```
threadsPool.execute(new Runnable() { 
    @Override public void run() { 
        // TODO Auto-generated method stub } 
    });
```

2、submit()方法用于提交有返回值的任务。线程池会返回一个future类型的对象，通过这个 future对象可以判断任务是否执行成功，并且可以通过future的get()方法来获取返回值

```
Future<Object> future = executor.submit(harReturnValuetask); 
try { 
    Object s = future.get(); 
} catch (InterruptedException e) { 
    // 处理中断异常 
} catch (ExecutionException e) { 
    // 处理无法执行任务异常 
} finally { 
    // 关闭线程池 
    executor.shutdown();
}
```', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1070, 102, '线程池怎么关闭？', '线程池怎么关闭？', '通过调用线程池的`shutdown`或`shutdownNow`方法来关闭线程池。它们的原理是遍历线程池中的工作线程，然后逐个调用线程的interrupt方法来中断线程，所以无法响应中断的任务可能永远无法终止。

**shutdown() 将线程池状态置为shutdown，并不会立即停止**：

* 1、停止接收外部submit的任务
* 2、内部正在跑的任务和队列里等待的任务，会执行完
* 3、等到第二步完成后，才真正停止

**shutdownNow() 将线程池状态置为stop。一般会立即停止，事实上不一定**：

* 1、和shutdown()一样，先停止接收外部提交的任务
* 2、忽略队列里等待的任务
* 3、尝试将正在跑的任务interrupt中断
* 4、返回未执行的任务列表

**shutdown 和 shutdownnow 简单来说区别如下：**

* 1、shutdownNow()能立即停止线程池，正在跑的和正在等待的任务都停下了。这样做立即生效，但是风险也比较大。
* 2、shutdown()只是关闭了提交通道，用submit()是无效的；而内部的任务该怎么跑还是怎么跑，跑完再彻底停止线程池。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1071, 102, '线程池的线程数如何配置？', '线程池的线程数如何配置？', '线程在Java中属于稀缺资源，线程池不是越大越好也不是越小越好。任务分为计算密集型、IO密集型、混合型。

**1、计算密集型**

大部分都在用CPU跟内存，加密，逻辑操作业务处理等。计算密集型一般推荐线程池不要过大，一般是CPU数 + 1，+1是因为可能存在**页缺失**(就是可能存在有些数据在硬盘中需要多来一个线程将数据读入内存)。如果线程池数太大，可能会频繁的进行线程上下文切换跟任务调度。获得当前CPU核数代码如下：

```
Runtime.getRuntime().availableProcessors();
```

**2、IO密集型**

数据库链接，网络通讯传输等。线程数适当大一点，机器的CPU核数*2

**3、混合型**

可以考虑根据情况将它拆分成CPU密集型和IO密集型任务，如果执行时间相差不大，拆分可以提升吞吐量，反之没有必要。', 2, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1072, 102, '常见的线程池？', '常见的线程池？', '通过工具类`Excutors`创建出来

* 1、newFixedThreadPool (固定数目线程的线程池)
* 2、newCachedThreadPool (可缓存线程的线程池)
* 3、newSingleThreadExecutor (单线程的线程池)
* 4、newScheduledThreadPool (定时及周期执行的线程池)', 1, 1, 'technology-talk/interview/tech/JAVA 并发那点破事.md', 1, NOW(3)),
  (1073, 100, 'JAVA 语言特点？', 'JAVA 语言特点？', '1、跨平台。JAVA 的 class 文件是运行在虚拟机上的，虚拟机在不同平台有不同版本，所以说 JAVA 是跨平台的，“一次编写，到处运行（Write Once，Run any Where）”

2、面向对象。具有封装、继承、多态特点

3、支持多线程。C++ 语言没有内置的多线程机制，因此必须调用操作系统的多线程功能来进行多线程 程序设计，而 Java 语言却提供了多线程支持；

4、网络编程方便。Java 语言诞生本身就是为简化网络编程设计的，因此 Java 语言不仅支 持网络编程而且很方便', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1074, 100, '面向对象和面向过程的区别？', '面向对象和面向过程的区别？', '**1、面向过程：**

- 优点：性能比面向对象高，因为类调用时需要实例化，开销比较大，比较消耗资源，比如单片机、嵌 入式开发、Linux/Unix等一般采用面向过程开发，性能是最重要的因素。
- 缺点：没有面向对象易维护、易复用、易扩展。

**2、面向对象：**

- 优点：易维护、易复用、易扩展，由于面向对象有封装、继承、多态性的特性，可以设计出低耦合 的系统，使系统更加灵活、更加易于维护。
- 缺点：性能比面向过程低。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1075, 100, 'JAVA 支持哪些数据类型？', 'JAVA 支持哪些数据类型？', '- 1、**基本数据类型（8个）**
   - 整数型：byte、short、int、long
   - 浮点型：float、double
   - 字符型：char 
   - 布尔型：boolean 
- 2、**引用数据类型（3个）**
   - 类、接口、数组', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1076, 100, '接口和抽象类有什么区别？', '接口和抽象类有什么区别？', '答案

1. 接口是抽象类的变体，接口中所有的方法都是抽象的。而抽象类是声明方法的存在而不去实现它的类。

2. 接口可以多继承，抽象类不行。

3. 接口定义方法，不能实现，默认是 public abstract，而抽象类可以实现部分方法。

4. 接口中基本数据类型为 public static final 并且需要给出初始值，而抽类象不是的。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1077, 100, '重载和重写什么区别？', '重载和重写什么区别？', '**1、重写：**

- 参数列表必须完全与被重写的方法相同，否则不能称其为重写而是重载.
- 返回的类型必须一直与被重写的方法的返回类型相同，否则不能称其为重写而是重载。
- 访问修饰符的限制一定要大于被重写方法的访问修饰符
- 重写方法一定不能抛出新的检查异常或者比被重写方法申明更加宽泛的检查型异常。

**2、重载：**

- 必须具有**不同的参数列表**；
- 可以有不同的返回类型，只要参数列表不同就可以了；
- 可以有**不同的访问修饰符**；
- 可以抛出**不同的异常**；', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1078, 100, '构造器是否可被重写（override）？', '构造器是否可被重写（override）？', '构造器不能被继承，因此不能被重写，但可以被重载。每一个类必须有自己的构造函数，负责构造自己 这部分的构造。子类不会覆盖父类的构造函数，相反必须一开始调用父类的构造函数', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1079, 100, 'JDK、JRE、JVM 三者有什么关系？', 'JDK、JRE、JVM 三者有什么关系？', '1、JDK（全称 Java Development Kit），拥有 JRE 所拥有的一切，还有编译器（javac）和工具（如 javadoc 和 jdb）。能独立创建、编译、运行程序。
> JDK = JRE + java开发工具（javac.exe/java.exe/jar.exe)

2、JRE（全称 Java Runtime Environment），包括 Java 虚拟机（JVM），Java 类库，java 命令和其他的一些基础构件。能运行已编译好的程序，但不能创建程序
> JRE = JVM + java核心类库

3、JVM （全称 Java Virtual Machine），java虚拟机。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1080, 100, '什么是字节码?', '什么是字节码?', 'Java之所以可以“`一次编译，到处运行`”，一是因为 JVM 针对各种操作系统、平台都进行了定制。二是因为无论在什么平台，都可以编译成固定格式的字节码（.class文件）供JVM使用。因此，也可以看出字节码对于Java生态的重要性。 

字节码文件由十六进制值组成，而JVM以两个十六进制值为一组，即以字节为单位进行读取。在Java中一般是用`javac命令`编译源代码为字节码文件。

Java语言通过字节码的方式，在一定程度上解决了传统解释型语言执行效率低的问题，同时又保留了`解释型语言`可移植的特点。所以Java程序运行时比较高效，而且，由于字节码并不专对一种特定的机器， 因此，Java程序无须重新编译便可在多种不同的计算机上运行。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1081, 100, '访问修饰符 public、private、protected？', '访问修饰符 public、private、protected？', 'Java中，可以使用访问控制符来保护对类、变量、方法和构造方法的访问。Java 支持 4 种不同的访问权 限。 

1、default (即默认，什么也不写）: 在同一包内可见，不使用任何修饰符。使用对象：类、接口、变量、方法。 2、private : 在同一类内可见。使用对象：变量、方法。注意：不能修饰类（外部类） 

3、public : 对所有类可见。使用对象：类、接口、变量、方法 

4、protected : 对同一包内的类和所有子类可见。使用对象：变量、方法。注意：不能修饰类（外部类）', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1082, 100, 'JAVA 创建对象有哪些方式？', 'JAVA 创建对象有哪些方式？', '1、new关键字
```
Person p1 = new Person();
```

2、Class.newInstance
```
Person p1 = Person.class.newInstance();
```

3、Constructor.newInstance
```
Constructor<Person> constructor = Person.class.getConstructor();
Person p1 = constructor.newInstance();
```

4、clone
```
Person p1 = new Person();
Person p2 = p1.clone();
```

5、反序列化
```
Person p1 = new Person();
byte[] bytes = SerializationUtils.serialize(p1);
Person p2 = (Person)SerializationUtils.deserialize(bytes);
```', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1083, 100, '值传递和引用传递的区别？', '值传递和引用传递的区别？', '**1、值传递：**

指的是在方法调用时，传递的参数是按值的拷贝传递，传递的是值的拷贝，也就是说传递后就 互不相关了。

**2、引用传递：**

指的是在方法调用时，传递的参数是按引用进行传递，其实传递的是引用的地址，也就是变 量所对应的内存空间的地址。也就是说传递前和传递后都指向同一个引用（同一个内存空间）
> 基本类型作为参数被传递时肯定是值传递；引用类型作为参数被传递时也是值传递，只不过“值”为对应的引用', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1084, 100, '为什么要有 hashCode?', '为什么要有 hashCode?', '以`HashSet 如何检查重复`为例子来说明为什么要有 hashCode。

当你把对象加入 HashSet 时，HashSet 会先计算对象的 hashcode 值来判断对象加入的位置，同时也会与其他已经加入的对象的 hashcode 值作比较，如果没有相符的hashcode，HashSet会假设对象没有重复出现。

但是如果发现有相同 hashcode 值的对象，这时会调用 equals()方法来检查 hashcode 相等的对象是否真的相同。如果两者相同，HashSet 就不会让其添加成功。如果不同的话，就会重新散列到其他位置。这样我们就大大减少了 equals 的次数，大大提高执行速度', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1085, 100, 'String 有哪些特性?', 'String 有哪些特性?', '1、不变性：String 是只读字符串，是一个典型的 immutable 对象，对它进行任何操作，其实都是创建一个新的对象，再把引用指向该对象。不变模式的主要作用在于当一个对象需要被多线程共享并频繁访问时，可以保证数据的一致性； 

2、常量池优化：String 对象创建之后，会在字符串常量池中进行缓存，如果下次创建同样的对象时，会直接返回缓存的引用 

3、final：使用 final 来定义 String 类，表示 String 类不能被继承，提高了系统的安全性。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1086, 100, 'String、StringBuffer、StringBuilder 区别？', 'String、StringBuffer、StringBuilder 区别？', '答案

1、String。采用 `final`修饰，对象不可变，线程安全。如果对一个已经存在的String对象修改，会重新创建一个新对象，并把值放进去。

2、StringBuffer，采用 `synchronized` 关键字修饰，线程安全

3、StringBuilder，非线程安全，但效率会更高些，适用于单线程。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1087, 100, 'HashMap 用 String 做 key 有什么好处？', 'HashMap 用 String 做 key 有什么好处？', 'HashMap 通过 key 的 hashcode 来确定 value 的存储位置，因为字符串是不可变的，所以当创建字符串后，它的 hashcode 被缓存下来，不需要再次计算，所以相比于其他对象更快。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1088, 100, 'Integer 和 int 有什么区别?', 'Integer 和 int 有什么区别?', '- Integer是int的包装类；int是基本数据类型；
- Integer变量必须实例化后才能使用；int变量不需要；
- Integer实际是对象的引用，指向此new的Integer对象；int是直接存储数据值 ；
- Integer的默认值是null；int的默认值是0

- final 变量：被修饰的变量不可变，不可变分为 引用不可变 和 对象不可变 ，final 指的是 引用不可变 ，final 修饰的变量必须初始化，通常称被修饰的变量为常量 。
- final 方法：被修饰的方法不允许被覆盖，子类可以使用该方法。
- final 类：被修饰的类不能被继承，所有方法不能被重写。 

2、finally 作为异常处理的一部分，它只能在 try/catch 语句中，并且附带一个语句块表示这段语句最终 一定被执行（无论是否抛出异常），经常被用在释放资源。

3、finalize 是在 java.lang.Object 里定义的方法，也就是说每一个对象都有这么个方法，这个方法在 gc 启动，该对象被回收的时候被调用。

 一个对象的 finalize 方法只会被调用一次，finalize 被调用不一定会立即回收该对象，所以有可能调用 finalize 后，该对象又不需要被回收了，然后到了真正要被回收的时候，因为前面调用过一次，所以不会 再次调用 finalize 了，进而产生问题，因此不推荐使用 finalize 方法。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1089, 100, '能否在 static 环境中访问非static变量？', '能否在 static 环境中访问非static变量？', 'static 变量在Java中是属于类的，它在所有的实例中的值是一样的。当类被Java虚拟机载入的时候，会对static 变量进行初始化。如果你的代码尝试不用实例来访问非static的变量，编译器会报错，因为这些变量还没有被创建出来，还没有跟任何实例关联上。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1090, 100, 'Error 和 Exception 区别？', 'Error 和 Exception 区别？', 'JAVA 标准库内建了一些通用的异常，这些类以`Throwable`为顶层父类。

Throwable又派生出 Error类 和 Exception 类 。

**1、错误：** Error 属于程序无法处理的错误 ，我们没办法通过 catch 来进行捕获。例如，系统崩溃，内存不足，堆栈溢出等，编译器不会对这类错误进行检测，一旦这类错误发生，通常应用程序会被终止，仅靠应用程序本身无法恢复。

**2、异常：** Exception以及他的子类，代表程序运行时发送的各种不期望发生的事件。可以被Java异常处理机制使用，是异常处理的核心。 Exception 又可以分为运行时异常 (RuntimeException，又叫非受检查异常) 和非运行时异常 (又叫受检查异常) 。

> 非受检查异常和受检查异常之间的区别：
> <br/>是否强制要求调用者必须处理此异常，如果强制要求调用者必须进行处理，那么就使用受检查异常，否则就选择非受检查异常', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1091, 100, '什么是非受检查异常？', '什么是非受检查异常？', '非受检查异常：包括 `RuntimeException` 类及其子类，表示 JVM 在运行期间可能出现的异常。 Java 编译器不会检查运行时异常。例如： NullPointException(空指针) 、 NumberFormatException（字符串转换为数字） 、 IndexOutOfBoundsException(数组越界) 、 ClassCastException(类转换异常) 、ArrayStoreException(数据存储异常，操作数组时类型不一致) 等。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1092, 100, '什么是 受检查异常？', '什么是 受检查异常？', '受检查异常：是Exception 中除 RuntimeException 及其子类之外的异常。 Java 编译器会检查受检查异常。
常见的受检查异常有：`IO 相关的异常`、 `ClassNotFoundException` 、 `SQLException` 等。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1093, 100, '常见异常有哪些？', '常见异常有哪些？', '- java.lang.IllegalAccessError：违法访问错误。当一个应用试图访问、修改某个类的域（Field）或者调用其方法，但是又违反域或方法的可见性声明，则抛出该异常。
- java.lang.InstantiationError：实例化错误。当一个应用试图通过Java的new操作符构造一个抽象类或者接口时抛出该异常.
- java.lang.OutOfMemoryError：内存不足错误。当可用内存不足以让Java虚拟机分配给一个对象时抛出该错误。
- java.lang.StackOverflowError：堆栈溢出错误。当一个应用递归调用的层次太深而导致堆栈溢出或者陷入死循环时抛出该错误。
- java.lang.ClassCastException：类造型异常。假设有类A和B（A不是B的父类或子类），O是A的实例，那么当强制将O构造为类B的实例时抛出该异常。该异常经常被称为强制类型转换异常。
- java.lang.ClassNotFoundException：找不到类异常。当应用试图根据字符串形式的类名构造类，而在遍历CLASSPAH之后找不到对应名称的class文件时，抛出该异常。
- java.lang.ArithmeticException：算术条件异常。譬如：整数除零等。
- java.lang.ArrayIndexOutOfBoundsException：数组索引越界异常。当对数组的索引值为负数或大于等于数组大小时抛出。
- java.lang.IndexOutOfBoundsException：索引越界异常。当访问某个序列的索引值小于0或大于等于序列大小时，抛出该异常。
- java.lang.InstantiationException：实例化异常。当试图通过newInstance()方法创建某个类的实例，而该类是一个抽象类或接口时，抛出该异常。
- java.lang.NoSuchFieldException：属性不存在异常。当访问某个类的不存在的属性时抛出该异常。
- java.lang.NoSuchMethodException：方法不存在异常。当访问某个类的不存在的方法时抛出该常。
- java.lang.NullPointerException：空指针异常。当应用试图在要求使用对象的地方使用了null时，抛出该异常。譬如：调用null对象的实例方法、访问null对象的属性、计算null对象的长度、使用throw语句抛出null等等。
- java.lang.NumberFormatException：数字格式异常。当试图将一个String转换为指定的数字类型，而该字符串确不满足数字类型要求的格式时，抛出该异常。
- java.lang.StringIndexOutOfBoundsException：字符串索引越界异常。当使用索引值访问某个字符串中的字符，而该索引值小于0或大于等于序列大小时，抛出该异常', 3, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1094, 100, '什么是反射？', '什么是反射？', '反射是在运行状态中，对于任意一个类，都能够知道这个类的所有属性和方法；对于任意一个对象，都能够调用它的任意一个方法和属性；这种动态获取的信息以及动态调用对象的方法的功能称为 Java 语言的反射机制。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1095, 100, '反射的优缺点？', '反射的优缺点？', '**1、优点：**

能够运行时动态获取类的实例，提高灵活性；可与动态编译结合

```
Class.forName(''com.mysql.jdbc.Driver.class'');  // 加载MySQL的驱动类。
```

**2、缺点：**

使用反射性能较低，需要解析字节码，将内存中的对象进行解析。其解决方案是：通过 `setAccessible(true)`，关闭JDK的安全检查来提升反射速度；多次创建一个类的实例时，有缓存会快很多；ReflflectASM工具类，通过字节码生成的方式加快反射速度。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1096, 100, '如何获取反射中的 Class 对象？', '如何获取反射中的 Class 对象？', '1、Class.forName(“类的路径”)；当你知道该类的全路径名时，你可以使用该方法获取 Class 类对象。
```
Class clz = Class.forName("java.lang.String");
```

2、类名.class。这种方法只适合在编译前就知道操作的 Class。
```
Class clz = String.class;
```

3、对象名.getClass()
```
String str = new String("Hello");
Class clz = str.getClass();
```

4、如果是基本类型的包装类，可以调用包装类的Type属性来获得该包装类的Class对象。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1097, 100, '反射 API 有几类？', '反射 API 有几类？', '反射 API 用来生成 JVM 中的类、接口或则对象的信息。

* Class 类：反射的核心类，可以获取类的属性，方法等信息。
* Field 类：Java.lang.reflec 包中的类，表示类的成员变量，可以用来获取和设置类中的属性值。
* Method 类：Java.lang.reflec 包中的类，表示类的方法，它可以用来获取类中的方法信息或者执行方法。
* Constructor 类：Java.lang.reflec 包中的类，表示类的构造方法。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1098, 100, '为什么引入反射？', '为什么引入反射？', '答案
 ： 
1、反射让开发人员可以通过外部类的全路径名创建对象，并使用这些类，实现一些扩展的功能。 

2、反射让开发人员可以枚举出类的全部成员，包括构造函数、属性、方法。以帮助开发者写出正确的代码。

3、测试时可以利用反射 API 访问类的私有成员，以保证测试代码覆盖率', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1099, 100, '什么是泛型 ?', '什么是泛型 ?', '泛型是 JDK1.5 的一个新特性，泛型就是将类型参数化，其在编译时才确定具体的参数。这种参数类型可以用在类、接口和方法的创建中，分别称为泛型类、泛型接口、泛型方法

泛型是一种语法糖。泛型只存在于编译阶段，而不存在于运行阶段。在编译后的 class 文件中，是没有泛型这个概念的。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1100, 100, '泛型的优点？', '泛型的优点？', '1、类型安全

- 泛型的主要目标是提高 Java 程序的类型安全
- 编译时期就可以检查出因 Java 类型不正确导致的 ClassCastException 异常
- 符合越早出错代价越小原则

2、消除强制类型转换

- 泛型的一个附带好处是，使用时直接得到目标类型，消除许多强制类型转换
- 所得即所需，这使得代码更加可读，并且减少了出错机会

3、潜在的性能收益

- 由于泛型的实现方式，支持泛型（几乎）不需要 JVM 或类文件更改
- 所有工作都在编译器中完成
- 编译器生成的代码跟不使用泛型（和强制类型转换）时所写的代码几乎一致，只是更能确保类型安全而已', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1101, 100, '什么是限定通配符和非限定通配符 ?', '什么是限定通配符和非限定通配符 ?', '```
1、限定通配符

对类型进行了限制。有两种限定通配符，一种是 <? extends T>  它通过确保类型必须是T的子类来设定类型的上界。另一种是 <? super T> 它通过确保类型必须是T的父类来设定类型的下界。泛型类型必须用限定内的类型来进行初始化，否则会导致编译错误。 

2、非限定通配符 ？

可以用任意类型来替代。如 List<?> 的意思是这个集合是一个可以持有任意类型的集合，它可以是 List<A> ，也可以是 List<B> ，或者 List<C> 等等。
```', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1102, 100, '序列化、反序列化是什么？', '序列化、反序列化是什么？', '1、序列化：序列化是把对象转换成有序字节流，以便在网络上传输或者保存在本地文件中。核心作用是对象状态的保存与重建。我们都知道，Java对象是保存在JVM的堆内存中的，也就是说，如果JVM堆不存在了，那么对象也就跟着消失了。 
而序列化提供了一种方案，可以让你在即使JVM停机的情况下也能把对象保存下来的方案。就像我们平时用的U盘一样。把Java对象序列化成可存储或传输的形式（如二进制流），比如保存在文件中。这样，当再次需要这个对象的时候，从文件中读取出二进制流，再从二进制流中反序列化出对象。 

2、反序列化：客户端从文件中或网络上获得序列化后的对象字节流，根据字节流中所保存的对象状态及描述信息，通过反序列化重建对象。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1103, 100, '什么是 serialVersionUID ？', '什么是 serialVersionUID ？', 'serialVersionUID 用来表明类的不同版本间的兼容性。
 Java 的序列化机制是通过在运行时判断类的 serialVersionUID 来验证版本一致性的。在进行反序列化时，JVM会把传来的字节流中的 serialVersionUID 与本地相应实体（类）的serialVersionUID进行比较，如果相同就认为是一致的，可以进行反序列化，否则就会出现序列化版本不一致的异常。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1104, 100, '为什么要显示指定 serialVersionUID 值?', '为什么要显示指定 serialVersionUID 值?', '如果不显示指定serialVersionUID，JVM在序列化时会根据属性自动生成一个serialVersionUID, 然后与属性一起序列化， 再进行持久化或网络传输。在反序列化时，JVM会再根据属性自动生成一个新版serialVersionUID，然后将这个新版serialVersionUID与序列化时生成的旧版 serialVersionUID 进行比较，如果相同则反序列化成功，否则报错。

如果显示指定了，JVM在序列化和反序列化时仍然都会生成一个serialVersionUID，但值为我们显示指定的值，这样在反序列化时新旧版本的serialVersionUID就一致了。 

在实际开发中，不显示指定serialVersionUID的情况会导致什么问题? 如果我们的类写完后不再修改，那当然不会有问题，但这在实际开发中是不可能的，我们的类会不断迭代， 一旦类被修改了， 那旧对象反序列化就会报错。所以在实际开发中， 我们都会显示指定一个serialVersionUID，值是多少无所谓， 只要不变就行。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1105, 100, 'AQS （AbstractQueuedSynchronizer 抽象队列同步器 ）的原理？', 'AQS （AbstractQueuedSynchronizer 抽象队列同步器 ）的原理？', 'AQS内部维护一个state状态位，尝试加锁的时候通过CAS(CompareAndSwap)修改值，如果成功设置为 1，并且把当前线程ID赋值，则代表加锁成功。
一旦获取到锁，其他的线程将会被阻塞进入阻塞队列自旋，获得锁的线程释放锁的时候将会唤醒阻塞队列中的线程，释放锁的时候则会把state重新置为0，同时当前线程ID置为空。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1106, 100, 'Java 都用过哪些锁？', 'Java 都用过哪些锁？', '- 乐观锁、悲观锁
- 分布式锁
- 独占锁、共享锁
- 互斥锁
- 读写锁
- 公平锁、非公平锁
- 可重入锁
- 自旋锁
- 分段锁
- 锁升级（无锁|偏向锁|轻量级锁|重量级锁）
- 锁优化技术（锁粗化、锁消除）
- 更多详细内容，[一文全面梳理各种锁机制](https://mp.weixin.qq.com/s?__biz=Mzg2NzYyNjQzNg==&mid=2247484801&idx=1&sn=66bb92c8b3a5f3617d2a8eea0a526cf5&scene=21#wechat_redirect)', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1107, 100, 'HashMap 原理？', 'HashMap 原理？', '内部由数组和链表组成，非线程安全。JDK1.7和1.8的主要区别在于头插和尾插方式的修改，头插容易导致HashMap链表死循环，并且1.8之后加入红黑树对性能有提升。

- put插入：key 计算hash值，取模，找到数组位置，如果数组中没有元素直接存入，反之，则判断key是否相同，key相同就覆盖，否则就会插入到链表的尾部。如果链表的⻓度超过8且数据总量超过64，则会转换成红黑树。最后判断元素个数是否超过默认的⻓度（16）*负载因子（0.75），也就是12，超过则进行扩容。
- get查询：计算出hash值，然后去数组查询，是红黑树就去红黑树查，链表就遍历链表查询就可以了。

红黑树的时间复杂度 O(logn)；链表的时间复杂度 O(n)，当链表过长时，红黑树能大大提高查询性能。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1108, 100, 'HashMap 线程不安全体现在哪里？', 'HashMap 线程不安全体现在哪里？', 'HashMap 1.7 中扩容时，因为采用的是头插法，所以会可能会有循环链表产生，导致数据有问题，在 1.8 版本已修复，改为了尾插法
在任意版本的 HashMap 中，如果在插入数据时多个线程命中了同一个槽，可能会有数据覆盖的情况发生，导致线程不安全。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1109, 100, 'ConcurrentHashMap 如何保证线程安全的？', 'ConcurrentHashMap 如何保证线程安全的？', 'ConcurrentHashmap在JDK1.7和1.8的版本改动比较大。

- 1.7 使用Segment + HashEntry 分段锁的方式实现，Segment继承于ReentrantLock，HashEntry存储键值对数据。
- 1.8 采用数组+ 链表 + 红黑树。锁设计上抛弃了Segment分段锁，采用 CAS + synchronized 实现。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1110, 100, 'ArrayList 和 LinkedList 区别？', 'ArrayList 和 LinkedList 区别？', '**1、Arraylist**

- 非线程安全
- 底层采用数组存储
- 插入、删除元素，时间复杂度受位置影响。默认是添加在列表的末尾，如果在位置 k 插入或删除一个元素，需要将k后面的元素后移或前移一位。
- 支持随机访问，根据索引下标序号，可以快速定位元素
- 需要连续的内存空间，中间不能有碎片

**2、LinkedList**

- 非线程安全
- 底层采用双向循环链表存储
- 插入、删除元素，时间复杂度不受位置影响，只需要更改位置 k的前后指针地址，时间复杂度为 O(1)
- 不支持高效的随机访问
- 不需要连续的内存空间', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1111, 100, '什么是 ReentrantLock ？', '什么是 ReentrantLock ？', 'java
ReentrantLock 意为可重入锁，其底层使用 AQS 实现。有两种模式，一种是公平锁，一种是非公平锁。

- 公平模式下等待线程入队列后会严格按照队列顺序去执行
- 非公平模式下等待线程入队列后有可能会出现插队情况

**公平锁：**

- 第一步：**获取状态的 state 的值**
   - 如果 state=0 即代表锁没有被其它线程占用，执行第二步。
   - 如果 state!=0 则代表锁正在被其它线程占用，执行第三步。
- 第二步：**判断队列中是否有线程在排队等待**
   - 如果不存在则直接将锁的所有者设置成当前线程，且更新状态 state 。
   - 如果存在就入队。
- 第三步：**判断锁的所有者是不是当前线程**
   - 如果是则更新状态 state 的值。
   - 如果不是，线程进入队列排队等待。

**非公平锁：**

- 获取状态的 state 的值
   - 如果 state=0 即代表锁没有被其它线程占用，则设置当前锁的持有者为当前线程，该操作用 CAS 完成。
   - 如果不为0或者设置失败，代表锁被占用进行下一步。
- 此时**获取 state 的值**
   - 如果是，则给state+1，获取锁
   - 如果不是，则进入队列等待
   - 如果是0，代表刚好线程释放了锁，此时将锁的持有者设为自己
   - 如果不是0，则查看线程持有者是不是自己', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1112, 100, 'ThreadLocal 原理?', 'ThreadLocal 原理?', 'ThreadLocal有一个静态内部类ThreadLocalMap，ThreadLocalMap又包含了一个Entry数组，Entry本身是一个弱引用，他的key是指向ThreadLocal的弱引用，Entry具备保存key -- value键值对的能力。
在使用完之后调用remove方法删除Entry对象，避免出现内存泄露。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1113, 100, '字符流与字节流的区别？', '字符流与字节流的区别？', '- 读写的时候，字节流是按字节读写，字符流按字符读写。
- 字节流适合所有类型文件的数据传输，因为计算机字节（Byte）是电脑中表示信息含义的最小单位。字符流只能够处理纯文本数据，其他类型数据不行，但是字符流处理文本要比字节流处理文本要方便。
- 在读写文件需要对内容按行处理，比如比较特定字符，处理某一行数据的时候一般会选择字符流。
- 只是读写文件，和文件内容无关时，一般选择字节流。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1114, 100, '怎么保证线程安全？', '怎么保证线程安全？', '- synchronized 关键字
   - 可以用于代码块，方法（静态方法，同步锁是当前字节码对象；实例方法，同步锁是实例对象）
- lock锁机制

```
Lock lock = new ReentrantLock();
lock. lock();
try {
    System. out. println("获得锁");
} catch (Exception e) {
   
} finally {
    System. out. println("释放锁");
    lock. unlock();
}
```', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1115, 100, 'IO 模型有哪五种？', 'IO 模型有哪五种？', '1、同步阻塞IO。当 应用B 发起读取数据申请时，如果内核数据没有准备好，应用B会一直处于等待数据状态，直到内核把数据准备好了交给应用B才结束。

2、非阻塞IO。当应用B发起读取数据申请时，如果内核数据没有准备好会即刻告诉应用B，不会让B在这里等待。

3、IO复用模型。进程通过将一个或多个fd传递给select，阻塞在select操作上，select帮我们侦测多个fd是否准备就绪，当有fd准备就绪时，select返回数据可读状态，应用程序再调用recvfrom读取数据。

4、信号IO。信号驱动IO不是用循环请求询问的方式去监控数据就绪状态，而是在调用sigaction时候建立一个SIGIO的信号联系，当内核数据准备好之后再通过SIGIO信号通知线程数据准备好后的可读状态，当线程收到可读状态的信号后，此时再向内核发起recvfrom读取数据的请求，因为信号驱动IO的模型下应用线程在发出信号监控后即可返回，不会阻塞，所以这样的方式下，一个应用线程也可以同时监控多个fd。

5、异步IO。解决了应用程序需要先后查看数据是否就绪、发送接收数据请求两个阶段的模式，在异步IO的模式下，只需要向内核发送一次请求就可以完成状态查询和数据拷贝的所有操作。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1116, 100, 'JMM 是什么？', 'JMM 是什么？', 'JMM 就是 Java内存模型(java memory model)。因为在不同的硬件生产商和不同的操作系统下，内存的访问有一定的差异，所以会造成相同的代码运行在不同的系统上会出现各种问题。所以java内存模型(JMM)屏蔽掉各种硬件和操作系统的内存访问差异，以实现让java程序在各种平台下都能达到一致的并发效果。

Java内存模型规定所有的变量都存储在主内存中，包括实例变量，静态变量，但是不包括局部变量和方法参数。每个线程都有自己的工作内存，线程的工作内存保存了该线程用到的变量和主内存的副本拷贝，线程对变量的操作都在工作内存中进行。线程不能直接读写主内存中的变量。

每个线程的工作内存都是独立的，线程操作数据只能在工作内存中进行，然后刷回到主存。这是 Java 内存模型定义的线程基本工作方式。', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1117, 100, '什么是单例模式懒汉式？', '什么是单例模式懒汉式？', '```
// 懒汉式
public class Singleton {
    // 延迟加载保证多线程安全
    Private volatile static Singleton singleton;
    private Singleton(){}
    public static Singleton getInstance(){
        if(singleton == null){
            synchronized(Singleton.class){
                if(singleton == null){
                    singleton = new Singleton();
                }
            }
        }
        return singleton;
    }
}
```

- 使用 volatile 是**防止指令重排序，保证对象可见**，防止读到半初始化状态的对象
- 第一层if(singleton == null) 是为了防止有多个线程同时创建
- synchronized 是加锁防止多个线程同时进入该方法创建对象
- 第二层if(singleton == null) 是防止有多个线程同时等待锁，一个执行完了后面一个又继续执行的情况', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1118, 100, '深拷贝、浅拷贝是什么？', '深拷贝、浅拷贝是什么？', '- 浅拷贝并不是真的拷贝，只是**复制指向某个对象的指针**，而不复制对象本身，新旧对象还是共享同一块内存。
- 深拷贝会另外**创造一个一模一样的对象**，新对象跟原对象不共享内存，修改新对象不会影响到原对象。', 1, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1119, 100, '一个对象的内存布局是怎么样的?', '一个对象的内存布局是怎么样的?', '**1、对象头**: 对象头又分为 **MarkWord** 和 **Class Pointer ** 两部分。

- **MarkWord**: 包含一系列的标记位，比如对象的hashcode、分代年龄、轻量级锁指针、重量级锁指针、GC标记、偏向锁线程ID、偏向锁时间戳
- **ClassPointer**: 用来指向对象对应的 Class 对象（其对应的元数据对象）的内存地址。在 32 位系统占 4 字节，在 64 位系统中占 8 字节。

**2、Length **: 只在数组对象中存在，用来记录数组的长度，占用 4 字节

**3、Instance data**: 对象实际数据，对象实际数据包括了对象的所有成员变量，其大小由各个成员变量的大小决定。(这里不包括静态成员变量，因为其是在方法区维护的)

**4、Padding**: Java 对象占用空间是 8 字节对齐的，即所有 Java 对象占用 bytes 数必须是 8 的倍数，因为当我们从磁盘中取一个数据时，不会说我想取一个字节就是一个字节，都是按照一块儿一块儿来取的，这一块大小是 8 个字节，所以为了完整，padding 的作用就是补充字节，**保证对象是 8 字节的整数倍**', 2, 1, 'technology-talk/interview/tech/JAVA基础那点破事.md', 1, NOW(3)),
  (1120, 101, '常见的集合有哪些？', '常见的集合有哪些？', 'Java集合类主要由两个根接口Collection和Map派生出来的，Collection派生出了三个子接口：List、Set、Queue（Java5 新增的队列），因此Java集合大致也可分成List、Set、Queue、Map 四种接口。

> Collection 是一个接口；Collections 是一个工具类；Map 不是 Collection 的子接口', 1, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1121, 101, '线程安全的集合？', '线程安全的集合？', '**1、线程安全**

- Hashtable：比HashMap 多了个线程安全。
- ConcurrentHashMap: 是一种高效但是线程安全的集合。
- Vector：比Arraylist多了个同步化机制。
- Stack：栈，也是线程安全的，继承于Vector。

**2、线性不安全**

- HashMap
- Arraylist
- LinkedList
- HashSet
- TreeSet
- TreeMap', 1, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1122, 101, 'ArrayList 与 LinkedList 区别？', 'ArrayList 与 LinkedList 区别？', '1、是否保证线程安全： ArrayList 和 LinkedList 都不保证线程安全 

2、底层数据结构： Arraylist 底层使用的是Object数组；LinkedList 底层使用的是双向循环链表

3、插入和删除是否受元素位置的影响： ArrayList 采用数组存储，所以插入和删除元素的时间复杂度受元素位置的影响。 比如：执行 add(E e) 方法的时候， ArrayList 会默认在将指定的元素追加到此列表的末尾，这种情况时间复杂度就是O(1)。但是如果要在指定位置 i 插入和删除元素的话（ add(int index, E element) ）时间复杂度就为 O(n-i)。因为在进行上述操作的时候集合中第 i 和第 i 个元素之后的(n-i)个元素都要执行向后位/向前移一位的操作。 LinkedList 采用链表存储，所以插入，删除元素时间复杂度不受元素位置的影响，都是近似 O（1）而数组为近似 O（n） 

4、是否支持快速随机访问： LinkedList 不支持高效的随机元素访问，而ArrayList 实现了RandomAccess 接口，所以有随机访问功能。快速随机访问就是通过元素的序号快速获取元素对象( get(int index) 方法) 

5、内存空间占用： ArrayList 的空间浪费主要体现在list列表的结尾会预留一定的容量空间，而LinkedList的空间花费则体现在它的每一个元素都需要消耗比ArrayList更多的空间（因为要存放直接后继和直接前驱以及数据）', 2, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1123, 101, 'ArrayList 与 Vector 区别？', 'ArrayList 与 Vector 区别？', '1、Vector是线程安全的，ArrayList 不是线程安全的。其中，Vector在关键性的方法前面都加了synchronized 关键字，来保证线程的安全性。如果有多个线程会访问到集合，那最好是使用 Vector，因为不需要我们自己再去考虑和编写线程安全的代码。 

2、ArrayList 在底层数组不够用时在原来的基础上扩展 0.5倍，Vector是扩展 1 倍，这样ArrayList 就有利于节约内存空间', 1, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1124, 101, 'HashMap 底层数据结构？', 'HashMap 底层数据结构？', '1、JDK1.7 ，由“数组+链表”组成，数组是 HashMap 的主体，链表则是主要为了解决哈希冲突而存在的。 

2、JDK1.8 ，由“数组+链表+红黑树”组成。当链表过长，则会严重影响 HashMap 的性能，红黑树搜索时间复杂度是 O(logn)，而链表是 O(n)。因此，JDK1.8 对数据结构做了进一步的优化，引入了红黑树，链表和红黑树在达到一定条件会进行转换：

- 当链表超过 8 且数据总量超过 64 才会转红黑树。
- 将链表转换成红黑树前会判断，如果当前数组的长度小于 64，那么会选择先进行数组扩容，而不 是转换为红黑树，以减少搜索时间。', 2, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1125, 101, '为什么在解决 hash 冲突的时候，不直接用红黑树？而选择先用链表，再转红黑树?', '为什么在解决 hash 冲突的时候，不直接用红黑树？而选择先用链表，再转红黑树?', '因为红黑树需要进行左旋，右旋，变色这些操作来保持平衡，而单链表不需要。当元素小于 8 个的时候，此时查询，链表结构能保证查询性能。当元素大于 8 个时， 红黑树搜索时间复杂度是 O(logn)，而链表是 O(n)，此时需要红黑树来加快查询速度，但是新增节点的效率变慢了。
因此，如果一开始就用红黑树结构，元素太少，新增效率又比较慢，无疑是浪费性能。', 1, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1126, 101, 'HashMap 默认负载因子是多少？为什么是 0.75，不是 0.6 或者 0.8 ？', 'HashMap 默认负载因子是多少？为什么是 0.75，不是 0.6 或者 0.8 ？', 'HashMap 的默认构造函数：
 
```
int threshold; // 容纳键值对的最大值
final float loadFactor; // 负载因子
int modCount;
int size;
```

Node[] table的初始化长度length (默认值是16)，Load factor为负载因子 (默认值是0.75)，threshold是HashMap 所能容纳键值对的最大值。threshold = length * Load factor。也就是说，在数组定义好长度之后，负载因子越大，所能容纳的键值对个数越多。 
默认的loadFactor是0.75，0.75 是对空间和时间效率的一个平衡选择，一般不要修改，除非在时间和空间比较特殊的情况下 ： 

- 如果内存空间很多而又对时间效率要求很高，可以降低负载因子Load factor的值 。
- 相反，如果内存空间紧张而对时间效率要求不高，可以增加负载因子loadFactor的值，这个值可以 大于1', 2, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1127, 101, 'HashMap 的 put 方法流程？', 'HashMap 的 put 方法流程？', '以JDK1.8为例，简要流程如下：

1、首先根据 key 的值计算 hash 值，找到该元素在数组中存储的下标；

2、如果数组是空的，则调用 resize 进行初始化；

3、如果没有哈希冲突直接放在对应的数组下标里；

4、如果冲突了，且 key 已经存在，就覆盖掉 value；

5、如果冲突后，发现该节点是红黑树，就将这个节点挂在树上；

6、如果冲突后是链表，判断该链表是否大于 8 ，如果大于 8 并且数组容量小于 64，就进行扩容；如果链表节点大于 8 并且数组的容量大于 64，则将这个结构转换为红黑树；否则，链表插入键值对，若key 存在，就覆盖掉 value。', 2, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1128, 101, 'HashMap 扩容方式？', 'HashMap 扩容方式？', 'HashMap 在容量超过负载因子所定义的容量之后，就会扩容。Java 里的数组是无法自动扩容的，方法是将 HashMap 的大小扩大为原来数组的两倍，并将原来的对象放入新的数组中。', 1, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1129, 101, 'HashMap 为什么线程不安全？', 'HashMap 为什么线程不安全？', '1、多线程下扩容死循环。JDK1.7中的 HashMap 使用头插法插入元素，在多线程的环境下，扩容的时候有可能导致环形链表的出现，形成死循环。因此，JDK1.8使用尾插法插入元素，在扩容时会保持链表元素原本的顺序，不会出现环形链表的问题。

2、多线程的put可能导致元素的丢失。多线程同时执行 put 操作，如果计算出来的索引位置是相同的，那会造成前一个 key 被后一个 key 覆盖，从而导致元素的丢失。此问题在JDK 1.7和 JDK 1.8 中都存在。

3、put和get并发时，可能导致get为null。线程1执行put时，因为元素个数超出threshold而导致rehash，线程2此时执行get，有可能导致这个问题。此问题在JDK 1.7和 JDK 1.8 中都存在。', 2, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1130, 101, 'ConcurrentHashMap 实现原理是？', 'ConcurrentHashMap 实现原理是？', '1、JDK1.7中的 ConcurrentHashMap 是由 Segment 数组结构和HashEntry 数组结构组成，即 ConcurrentHashMap 把哈希桶切分成小数组（Segment ），每个小数组有 n 个 HashEntry 组成。

其中，Segment 继承 ReentrantLock，所以 Segment 是一种可重入锁，扮演锁的角色；HashEntry 用于存储键值对数据。

首先将数据分为一段一段的存储，然后给每一段数据配一把锁，当一个线程占用锁访问其中一个段数据 时，其他段的数据也能被其他线程访问，能够实现真正的并发访问。

2、JDK1.8 中的ConcurrentHashMap 选择了与 HashMap 相同的数组+链表+红黑树结构；在锁的实现上，抛弃了原有的 Segment 分段锁，采用 CAS + synchronized 实现更加低粒度的锁。
将锁的级别控制在了更细粒度的哈希桶元素级别，也就是说只需要锁住这个链表头结点（红黑树的根节点），就不会影响其他的哈希桶元素的读写，大大提高了并发度。', 2, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1131, 101, 'JDK1.7 与 JDK1.8 ConcurrentHashMap 区别？', 'JDK1.7 与 JDK1.8 ConcurrentHashMap 区别？', '1、数据结构：取消了`Segment`分段锁的数据结构，取而代之的是 `数组+链表+红黑树` 结构。

2、保证线程安全机制：JDK1.7采用Segment的分段锁机制实现线程安全，其中`segment`继承自`ReentrantLock`。JDK1.8 采用`CAS+Synchronized`保证线程安全。

3、锁的粒度：原来是对需要进行数据操作的Segment加锁，现调整为对每个数组元素加锁（Node）。

4、链表转化为红黑树：定位结点的hash算法简化会带来弊端，Hash冲突加剧，因此在链表节点数量大于8时，会将链表转化为红黑树进行存储。

5、查询时间复杂度：从原来的遍历链表O(n)，变成遍历红黑树O(logN)。', 2, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1132, 101, 'ConcurrentHashMap 和 Hashtable 哪个效率更高？', 'ConcurrentHashMap 和 Hashtable 哪个效率更高？', 'ConcurrentHashMap 效率要高于Hashtable，因为Hashtable给整个哈希表加了一把大锁从而实现线程安全。

而ConcurrentHashMap 的锁粒度更低，在JDK1.7中采用分段锁实现线程安全，在JDK1.8 中采用 CAS+Synchronized 实现线程安全。', 1, 1, 'technology-talk/interview/tech/JAVA集合那点破事.md', 1, NOW(3)),
  (1133, 103, 'JVM 内存结构？', 'JVM 内存结构？', 'JAVA 程序在运行的过程中会把他管理的内存划分为若干个不同的数据区域，**每一块儿的数据区域所负责的功能都是不同的，他们也有不同的创建时间和销毁时间**。紫色区域代表是线程共享的区域。

**1、程序计数器**

程序计数器是**程序控制流的指示器，循环，跳转，异常处理，线程的恢复等工作都需要依赖程序计数器去完成**。程序计数器是**线程私有**的，它的**生命周期是和线程保持一致**的，我们知道，N 个核数的 CPU 在同一时刻，最多有 N个线程同时运行，在我们真实的使用过程中可能会创建很多线程，JVM 的多线程其实是通过线程轮流切换，分配处理器执行时间来实现的。既然涉及的线程切换，所以每条线程必须有一个独立的程序计数器。

**2、虚拟机栈**

虚拟机栈，其描述的就是线程内存模型，**也可以称作线程栈**，也是每个**线程私有**的，**生命周期与线程保持一致**。在每个方法执行的时候，jvm 都会同步创建一个栈帧去存储局部变量表，操作数栈，动态连接，方法出口等信息。一个方法的生命周期就贯彻了一个栈帧从入栈到出栈的全部过程。

**3、本地方法栈**

本地方法栈的概念很好理解，我们知道，java底层用了很多c的代码去实现，而其调用c端的方法上都会有native，代表本地方法服务，而本地方法栈就是为其服务的。

**4、堆**
可以说是 JVM 中最大的一块儿内存区域了，它是所有线程共享的，不管你是初学者还是资深开发，多少都会听说过堆，毕竟几乎所有的对象都会在堆中分配。

**5、方法区**

方法区也是所有**线程共享**的区域，它**存储**了被 jvm 加载的**类型信息、常量、静态变量等数据**。运行时常量池就是方法区的一部分，编译期生成的各种字面量与符号引用就存储在其中。

**6、直接内存**

这部分数据并**不是 JVM 运行时数据区的一部分**，nio 就会使用到直接内存，也可以说**堆外内存**，通常会**配合虚引用一起去使用**，就是为了资源释放，会将堆外内存开辟空间的信息存储到一个队列中，然后GC会去清理这部分空间。堆外内存优势在 IO 操作上，对于网络 IO，使用 Socket 发送数据时，能够节省堆内存到堆外内存的数据拷贝，所以性能更高。看过 Netty 源码的同学应该了解，Netty 使用堆外内存池来实现零拷贝技术。对于磁盘 IO 时，也可以使用内存映射，来提升性能。另外，更重要的几乎不用考虑堆内存烦人的 GC 问题。但是既然是内存。也会受到本机总内存的限制，', 3, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1134, 103, '什么是 JVM 内存模型 ？', '什么是 JVM 内存模型 ？', 'Java 内存模型（下文简称 JMM）就是在底层处理器内存模型的基础上，定义自己的多线程语义。它明确指定了一组排序规则，来保证线程间的可见性。

这一组规则被称为 Happens-Before, JMM 规定，要想保证 B 操作能够看到 A 操作的结果（无论它们是否在同一个线程），那么 A 和 B 之间必须满足 Happens-Before 关系：

- 单线程规则：一个线程中的每个动作都 happens-before 该线程中后续的每个动作
- 监视器锁定规则：监听器的解锁动作 happens-before 后续对这个监听器的锁定动作
- volatile 变量规则：对 volatile 字段的写入动作 happens-before 后续对这个字段的每个读取动作
- 线程 start 规则：线程 start() 方法的执行 happens-before 一个启动线程内的任意动作
- 线程 join 规则：一个线程内的所有动作 happens-before 任意其他线程在该线程 join() 成功返回之前
- 传递性：如果 A happens-before B, 且 B happens-before C, 那么 A happens-before C 

怎么理解 happens-before 呢？如果按字面意思，比如第二个规则，线程（不管是不是同一个）的解锁动作发生在锁定之前？这明显不对。happens-before 也是为了保证可见性，比如那个解锁和加锁的动作，可以这样理解，线程1释放锁退出同步块，线程2加锁进入同步块，那么线程2就能看见线程1对共享对象修改的结果。

Java 提供了几种语言结构，包括 volatile、final 和 synchronized，它们旨在帮助程序员向编译器描述程序的并发要求，其中：

- volatile ： 保证可见性和有序性
- synchronized ： 保证可见性和有序性; 通过管程（Monitor）保证一组动作的原子性
- final ： 通过禁止在构造函数初始化和给 final 字段赋值这两个动作的重排序，保证可见性（如果this 引用逃逸就不好说可见性了）

编译器在遇到这些关键字时，会插入相应的内存屏障，保证语义的正确性。 

有一点需要注意的是，synchronized 不保证同步块内的代码禁止重排序，因为它通过锁保证同一时刻只有一个线程访问同步块（或临界区），也就是说同步块的代码只需满足 as-if-serial 语义 ， 只要单线程的执行结果不改变，可以进行重排序。 

所以说，Java 内存模型描述的是多线程对共享内存修改后彼此之间的可见性。另外，还确保正确同步的Java 代码可以在不同体系结构的处理器上正确运行。', 3, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1135, 103, '垃圾对象是怎么找到的？', '垃圾对象是怎么找到的？', '**1、引用计数算法**

就是给对象添加一个计数器，每当有一个地方引用它的时候，计数器就加1。每当有一个引用失效的时候，计数器就减1

**当计数器的值为0的时候，那么该对象就是垃圾了。**这种方案的原理很简单，而且判定的效率也非常高，但是却可能会有其他的额外情况需要考虑。

比如两个**对象循环引用**，a 对象引用了 b 对象，b 对象也引用了 a 对象，a、b 对象却没有再被其他对象所引用了，其实正常来说这两个对象已经是垃圾了，因为没有其他对象在使用了，但是计数器内的数值却不是 0，所以引用计数算法就无法回收它们。这种算法是比较**直接的找到垃圾**，然后去回收，也被称为"直接垃圾收集"。

**2、可达性分析法**

这也是**JVM 默认使用**的寻找垃圾算法它的原理就是定义了一系列的根，我们把它称为 **"GC Roots"** ，从 **"GC Roots"** 开始往下进行搜索，走过的路径我们把它称为 **"引用链"** ，当一个对象到 **"GC Roots"** 之间没有任何引用链相连时，那么这个对象就可以被当做垃圾回收了。

如图，**根可达算法**就可以**避免**计数器算法不好解决的**循环引用问题**，Object 6、Object 7、Object 8 彼此之间有引用关系，但是**没有与"GC Roots" 相连，那么就会被当做垃圾所回收**。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1136, 103, 'GC Roots 有哪些?', 'GC Roots 有哪些?', '**固定的GC Roots 对象**和**不固定的临时GC Roots对象。**

**固定的GC Roots:**

- 在**虚拟机栈(栈帧的本地变量表)中所引用的对象**，譬如各个线程被调用的方法堆栈中使用到的参数、局部变量、临时变量等。
- 在方法区中类静态属性引用的对象，譬如 Java 类的**引用静态变量**。
- 在方法区中**常量引用的对象**，譬如字符串常量池中的引用。
- 在方法区栈中 **JNI (譬如 Native 方法)引用的对象**。
- Java **虚拟机内部的引用**，如基本数据类型对应的 Class 对象，一些常驻的异常对象(空指针异常、OOM等)，还有类加载器。
- 所有**被 Synchronized 持有的对象**。
- 反应 Java 虚拟机内部情况的 **JMXBean、JVMTI 中注册的回调本地代码缓存等**。

**临时GC Roots:**

- **为什么会有临时的 GC Roots ？**:目前的垃圾回收大部分都是**分代收集和局部回收**，如果只针对某一部分区域进行局部回收，那么就必须要考虑的**当前区域的对象有可能正被其他区域的对象所引用**，这时候就要将这部分关联的对象也添加到 GC Roots 中去来确保根可达算法的准确性。这种算法是利用了**逆向思维**，找到使用的对象，剩下的就是垃圾，也被称为"间接垃圾收集"。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1137, 103, '四种引用类型 ?', '四种引用类型 ?', '**1、强引用**

"Object o = new Object()" 就是一种强引用关系，这也是我们在代码中最常用的一种引用关系。无论任何情况下，只要强引用关系还存在，垃圾回收器就不会回收掉被引用的对象。

**2、软引用**

当内存空间不足时，就会回收软引用对象。
```
// 软引用   
SoftReference<String> softRef = new SoftReference<String>(str);
```

软引用用来描述那些有用但是没必要的对象。

**3、弱引用**

弱引用要比软引用更弱一点，它**只能够存活到下次垃圾回收之前**。也就是说，垃圾回收器开始工作，会回收掉所有只被弱引用关联的对象。
```
WeakReference<String> weakRef = new WeakReference<String>(str);
```

在 **ThreadLocal** 中就使用了弱引用来防止内存泄漏。

**4、虚引用**

虚引用是最弱的一种引用关系，它的唯一作用是用来作为一种通知。如零拷贝(Zero Copy)，开辟了堆外内存，虚引用在这里使用，会将这部分信息存储到一个队列中，以便于后续对堆外内存的回收管理。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1138, 103, '垃圾回收算法？', '垃圾回收算法？', '**1、标记清除**

这种算法的实现是很简单的，有两种方式

- 标记出垃圾，然后清理掉
- 标记出存货的对象，回收其他空间

**缺点：**

- 随着对象越来越多，那么所需要消耗的时间就会越来越多
- 标记清除后会导致碎片化，如果有大对象分配很有可能分配不下而出发另一次的垃圾收集动作

**2、标记复制**

这种算法解决了第一种算法碎片化的问题。就是**开辟两块完全相同的区域**，对象只在其中一篇区域内分配，然后**标记**出那些**存活的对象，按顺序整体移到另外一个空间**，如下图，可以看到回收后的对象是排列有序的，这种操作只需要移动指针就可以完成，效率很高，**之后就回收移除前的空间**。

缺点：

- 浪费过多的内存，使现有的**可用空间变为**原先的**一半**

**3、标记整理法**

这种算法可以说是结合了前两种算法，既有标记删除，又有整理功能。

这种算法就是通过标记清除算法找到存活的对象，然后将所有**存活的对象，向空间的一端移动**，然后回收掉其他的内存。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1139, 103, '什么是 STW ?', '什么是 STW ?', 'Java 中**Stop-The-World机制简称 STW** ，是在执行垃圾收集算法时，Java 应用程序的其他所有线程都被挂起（除了垃圾收集帮助器之外）。**Java 中一种全局暂停现象，全局停顿**，所有 Java 代码停止，native 代码可以执行，但不能与 JVM 交互。', 1, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1140, 103, '为什么需要 STW ?', '为什么需要 STW ?', '在 java 应用程序中**引用关系**是不断发生**变化**的，那么就会有会有很多种情况来导致**垃圾标识**出错。想想一下如果 Object a 目前是个垃圾，GC 把它标记为垃圾，但是在清除前又有其他对象指向了 Object a，那么此刻 Object a 又不是垃圾了，那么如果没有 STW 就要去无限维护这种关系来去采集正确的信息。再举个例子，到了秋天，道路上洒满了金色的落叶，环卫工人在打扫街道，却永远也无法打扫干净，因为总会有不断的落叶。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1141, 103, '垃圾回收器是怎样寻找 GC Roots ？', '垃圾回收器是怎样寻找 GC Roots ？', '我们在前面说明了根可达算法是通过 GC Roots 来找到存活的对象的，也定义了 GC Roots，那么垃圾回收器是怎样寻找GC Roots 的呢？首先，**为了保证结果的准确性，GC Roots枚举时是要在STW的情况下进行的**，但是由于 JAVA 应用越来越大，所以也不能逐个检查每个对象是否为 GC Root，那将消耗大量的时间。一个很自然的想法是，用空间换时间，在某个时候把栈上代表引用的位置全部记录下来，这样到真正 GC 的时候就可以直接读取，而不用再一点一点的扫描了。事实上，大部分主流的虚拟机也正是这么做的，比如 HotSpot ，它使用一种叫做 **OopMap** （ordinary object pointer) 普通对象指针的数据结构来记录这类信息。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1142, 103, 'OopMap 是做什么的?有什么好处?', 'OopMap 是做什么的?有什么好处?', '我们知道，一个线程意味着一个栈，一个栈由多个栈帧组成，一个栈帧对应着一个方法，一个方法里面可能有多个安全点。gc 发生时，程序首先运行到最近的一个安全点停下来，然后更新自己的 OopMap ，记下栈上哪些位置代表着引用。枚举根节点时，递归遍历每个栈帧的 OopMap ，通过栈中记录的被引用对象的内存地址，即可找到这些对象（ GC Roots ）。使用 OopMap 可以**避免全栈扫描**，加快枚举根节点的速度。但这并不是它的全部用意。它的另外一个更根本的作用是，可以帮助 HotSpot 实现准确式 GC (即使用准确式内存管理，虚拟机可用知道内存中某个位置的数据具体是什么类型) 。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1143, 103, '什么是安全点?', '什么是安全点?', '从线程角度看，安全点可以理解成是在**代码执行过程中**的一些**特殊位置**，当线程执行到这些位置的时候，说明**虚拟机当前的状态是安全**的。比如：**方法调用、循环跳转、异常跳转等这些地方才会产生安全点**。如果有需要，可以在这个位置暂停，比如发生GC时，需要暂停所有活动线程，但是线程在这个时刻，还没有执行到一个安全点，所以该线程应该继续执行，到达下一个安全点的时候暂停，等待 GC 结束。那么如何让线程在垃圾回收的时候都跑到最近的安全点呢？这里有**两种方式**：

- **抢先式中断**
   - 抢先式中断：就是在stw的时候，先让所有线程**完全中断**，如果中断的地方不在安全点上，然后**再激活**，**直到运行到安全点的位置**再中断。
- **主动式中断**
   - 主动式中断：在安全点的位置打一个标志位，每个线程执行都去轮询这个标志位，如果为真，就在最近的安全点挂起。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1144, 103, '垃圾回收器?', '垃圾回收器?', '前面和大家聊了很多垃圾收集算法，所以在真正实践的时候会有多种选择，垃圾回收器就是真正的实践者，接下来就和大家聊聊10种垃圾回收器

**1、Serial**

Serial是一个**单线程**的垃圾回收器，**采用复制算法负责新生代**的垃圾回收工作，可以与 CMS 垃圾回收器一起搭配工作。

在 STW 的时候**只会有一条线程**去进行垃圾收集的工作，所以可想而知，它的效率会比较慢。但是他确是所有垃圾回收器里面消耗额外内存最小的，没错，就是因为简单。

**2、ParNew**

ParNew 是一个**多线程**的垃圾回收器，采用复制算法负责新生代的垃圾回收工作，可以与CMS垃圾回收器一起搭配工作。

它其实就是 Serial 的多线程版本，主要区别就是在 STW 的时候可以用多个线程去清理垃圾。

**3、Pararllel Scavenge**

Pararllel Scavenge 是一个**多线程**的垃圾回收器，**采用复制算法负责新生代**的垃圾回收工作，可以与 Serial Old ， Parallel Old 垃圾回收器一起搭配工作。

是与 ParNew 类似，都是用于年轻代回收的使用复制算法的并行收集器，与 ParNew 不同的是，Parallel Scavenge 的**目标是达到一个可控的吞吐量**。吞吐量=程序运行时间/（程序运行时间+GC时间）。如程序运行了99s，GC耗时1s，吞吐量=99/（99+1）=99%。Parallel Scavenge 提供了两个参数用以精确控制吞吐量，分别是用以控制最大 GC 停顿时间的 -XX:MaxGCPauseMillis 及直接控制吞吐量的参数 -XX:GCTimeRatio.**停顿时间越短就越适合需要与用户交互的程序**，良好的响应速度能提升用户体验，而高吞吐量则可以高效的利用 CPU 时间，尽快完成程序的运算任务，主要适合在后台运算而不需要太多交互的任务。

**4、Serial Old**

Serial Old 是一个**单线程**的垃圾回收器，**采用标记整理算法负责老年代**的垃圾回收工作，有可能还会配合 **CMS** 一起工作。

其实它就是 Serial 的老年代版本，整体链路和 Serial 大相径庭。

**5、Parallel Old**

Parallel Old 是一个**多线程**的垃圾回收器，**采用标记整理算法负责老年代**的垃圾回收工作，可以与 Parallel Scavenge 垃圾回收器一起搭配工作。

Parallel Old 是 Pararllel Scavenge 的老年代版本，它的设计思路也是以吞吐量优先的，ps+po 是很常用的一种组合。

**6、CMS**

CMS可以说是一款具有"跨时代"意义的垃圾回收器，支持了和用户线程一起工作，做到了**一起并发回收垃圾**的"壮举"。

- **1.初始标记**
   - 初始标记只是标记出来**和 GC Roots 直接关联**的对象，整个速度是非常快的，为了保证标记的准确，这部分会在 **STW** 的状态下运行。
- **2.并发标记**
   - 并发标记这个阶段会直接根据第一步关联的对象找到**所有的引用**关系，这一部分时刻用户线程**并发运行**的，虽然耗时较长，但是不会有很大的影响。
- **3.重新标记**
   - 重新标记是为了解决第二步并发标记所导致的标错情况，这里简单举个例子：并发标记时a没有被任何对象引用，此时垃圾回收器将该对象标位垃圾，在之后的标记过程中，a又被其他对象引用了，这时候如果不进行重新标记就会发生**误清除**。这部分内容也是在**STW**的情况下去标记的。
- **4.并发清除**
   - 这一步就是最后的清除阶段了，将之前**真正确认为垃圾的对象回收**，这部分会和用户线程一起并发执行。

CMS的**三个缺点**：

- **1.影响用户线程的执行效率**
   - CMS默认启动的回收线程数是（处理器核心数 + 3）/ 4 ,由于是和用户线程一起并发清理，那么势必会影响到用户线程的执行速度，并且这个影响**随着核心线程数的递减而增加**。所以 JVM 提供了一种 "**增量式并发收集器**"的 CMS 变种，主要是用来减少垃圾回收线程独占资源的时间，所以会感觉到回收时间变长，这样的话**单位时间内处理垃圾的效率就会降低**，也是一种缓和的方案。
- **2.会产生"浮动垃圾"**
   - 之前说到 CMS 真正清理垃圾是和用户线程一起进行的，在**清理**这部分垃圾的时候**用户线程会产生新的垃圾**，这部分垃圾就叫做浮动垃圾，并且只能等着下一次的垃圾回收再清除。
- **3.会产生碎片化的空间**

   - CMS 是使用了标记删除的算法去清理垃圾的，而这种算法的缺点就是会产生**碎片化**，后续可能会**导致大对象无法分配**从而触发**和 Serial Old 一起配合使用**来处理碎片化的问题，当然这也处于 **STW**的情况下，所以当 java 应用非常庞大时，如果采用了 CMS 垃圾回收器，产生了碎片化，那么在 STW 来处理碎片化的时间会非常之久。

**7、G1**

G1(Garbage First)：顾名思义，**垃圾回收第一**，官方对它的评价是在垃圾回收器技术上具有**里程碑式**的成果。G1 回收的目标不再是整个新生代，不再是整个老年代，也不再是整个堆了。G1 可以**面向堆内存的任何空间来进行**回收，衡量的标准也不再是根据年代来区分，而是哪块**空间的垃圾最多就回收哪**块儿空间，这也符合 G1 垃圾回收器的名字，垃圾第一，这就是 G1 的 **Mixed GC** 模式。当然我的意思是**垃圾回收不根据年代来区分**，但是 G1 还是**根据年代来设计**的，我们先来看下 G1 对于堆空间的划分：

G1 垃圾回收器把堆划分成一个个**大小相同的Region**，每个 Region 都会扮演一个角色，H、S、E、O。E代表伊甸区，S代表 Survivor 区，H代表的是 Humongous(G1用来分配**大对象的区域**，对于 Humongous 也分配不下的超大对象，会分配在连续的 N 个 Humongous 中)，剩余的深蓝色代表的是 Old 区，灰色的代表的是空闲的 region。在 HotSpot 的实现中，整个堆被划分成2048左右个 Region。每个 Region 的大小在1-32 MB之间，具体多大取决于堆的大小。在并发标记垃圾时也会产生新的对象，G1 对于这部分对象的处理是这样的：将 Region **新增一块并发回收过程中分配对象的空间**，并为此设计了两个 TAMS(Top at Mark Start)指针，这块区域专门用来在并发时分配新对象，有对象新增只需要将 TAMS 指针移动下就可以了，并且这些**新对象默认是标记为存活**，这样就**不会干扰到标记过程**。

但是这种方法也会有个问题，有可能**垃圾回收的速度小于新对象分配的速度**，这样会导致 "Full GC" 而产生长时间的 STW。在 G1 的设计理念里，**最小回收单元是 Region**，每次回收的空间大小都是Region的N倍，那么G1是**怎么选择要回收哪块儿区域**的呢？G1 会跟踪各个 Region 区域内的垃圾价值，和回收空间大小回收时间有关，然后**维护一个优先级列表**，来收集那些价值最高的Reigon区域。', 3, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1145, 103, 'G1 回收过程？', 'G1 回收过程？', '1、初始标记（会STW）
  
仅仅只是标记一下 GC Roots 能直接关联到的对象，并且修改TAMS指针的值，让下一阶段用户线程并发运行时，能正确地在可用的Region中分配新对象。这个阶段需要停顿线程，但耗时很短，而且是借用进行Minor GC的时候同步完成的，所以G1收集器在这个阶段实际并没有额外的停顿。

2、并发标记
  
从 GC Roots 开始对堆中对象进行可达性分析，递归扫描整个堆里的对象图，找出要回收的对象，这阶段耗时较长，但可与用户程序并发执行。当对象图扫描完成以后，还要重新处理在并发时有引用变动的对象。

3. 最终标记（会STW）

对用户线程做短暂的暂停，处理并发阶段结束后仍有引用变动的对象。

4. 清理阶段（会STW）

更新Region的统计数据，对各个Region的回收价值和成本进行排序，根据用户所期望的停顿时间来制定回收计划，可以自由选择任意多个Region构成回收集，然后把决定回收的那一部分Region的存活对象复制到空的Region中，再清理掉整个旧Region的全部空间。这里的操作涉及存活对象的移动，必须暂停用户线程，由多条回收器线程并行完成的。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1146, 103, 'Minor GC 和 Full GC 区别？', 'Minor GC 和 Full GC 区别？', 'Minor GC：只收集新生代的GC。
 
 Full GC: 收集整个堆，包括 新生代，老年代，永久代(在 JDK 1.8及以后，永久代被移除，换为metaspace 元空间)等所有部分的模式。

**Minor GC触发条件**：当Eden区满时，触发Minor GC。

**Full GC触发条件：** 

1、通过Minor GC后进入老年代的平均大小大于老年代的可用内存。如果发现统计数据说之前Minor GC的平均晋升大小比目前old gen剩余的空间大，则不会触发Minor GC而是转为触发full GC。 

2、老年代空间不够分配新的内存（或永久代空间不足，但只是JDK1.7有的，这也是用元空间来取代永久代的原因，可以减少Full GC的频率，减少GC负担，提升其效率）。

3、由Eden区、From Space区向To Space区复制时，对象大小大于To Space可用内存，则把该对象转存到老年代，且老年代的可用内存小于该对象大小。

4、调用System.gc时，系统建议执行Full GC', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1147, 103, '什么情况下会发生栈内存溢出？', '什么情况下会发生栈内存溢出？', '1、栈是线程私有的，栈的生命周期和线程一样，每个方法在执行的时候就会创建一个 **栈帧**，它包含局部变量表、操作数栈、动态链接、方法出口等信息，局部变量表又包括基本数据类型和对象的引用；

2、当线程请求的栈深度超过了虚拟机允许的最大深度，会抛出StackOverFlowError异常，方法递归调用容易出现该问题；

3、通过参数-xss调整 jvm 栈的大小', 1, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1148, 103, '如何排查 OOM 问题？', '如何排查 OOM 问题？', '1、增加两个参数 -XX:+HeapDumpOnOutOfMemoryError、 -XX:HeapDumpPath=/tmp/heapdump.hprof，当 OOM 发生时自动 dump 堆内存信息到指定目 录；

2、同时 jstat 查看监控 JVM 的内存和 GC 情况，先观察问题大概出在什么区域；

3、使用 MAT 工具载入 dump 文件，分析大对象的占用情况，比如 HashMap 做缓存未清理，时间 长了就会内存溢出，可以把改为弱引用', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1149, 103, '类加载机制是什么?', '类加载机制是什么?', '**类加载机制**:

- Java 虚拟机**把描述类的数据从 Class 文件加载到内存，并对数据进行校验、转换解析和初始化，最终形成可以被 Jvm 可以直接使用的类型**，这个过程就可以成为虚拟机的类加载机制。

**加载、验证、准备、初始化、卸载这五个阶段的顺序是确定的，是依次有序的**。但是**解析阶段有可能会在初始化之后才会进行**，这是**为了支持 Java 动态绑定**的特性。

**动态绑定**:

- **在运行时根据具体对象的类型进行绑定**。提供了一些机制，可在运行期间判断对象的类型，并分别调用适当的方法。也就是说，编译器此时依然不知道对象的类型，但方法调用机制能自己去调查，找到正确的方法主体。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1150, 103, '类加载过程？', '类加载过程？', '1、加载，加载分为三步：

- 通过类的全限定性类名获取该类的二进制流；
- 将该二进制流的静态存储结构转为方法区的运行时数据结构；
- 在堆中为该类生成一个class对象；

2、验证：验证该class文件中的字节流信息符合虚拟机的要求，不会威胁到 jvm 的安全； 

3、准备：为class对象的静态变量分配内存，初始化其初始值； 

4、解析：该阶段主要完成符号引用转化成直接引用； 

5、初始化：到了初始化阶段，才开始执行类中定义的java代码；初始化阶段是调用类构造器的过程', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1151, 103, '常见的类加载器有哪些？', '常见的类加载器有哪些？', '类加载器是指：通过一个类的全限定性类名获取该类的二进制字节流叫做类加载器；类加载器分为以下四种： 

1、启动类加载器（BootStrapClassLoader）：用来加载java核心类库，无法被java程序直接引用； 

2、扩展类加载器（Extension ClassLoader）：用来加载java的扩展库，java的虚拟机实现会提供一个扩展库目录，该类加载器在扩展库目录里面查找并加载java类； 

3、应用类加载器（AppClassLoader）：它根据java的类路径来加载类，一般来说，java应用的类都是 通过它来加载的；

4、自定义类加载器：由java语言实现，继承自ClassLoader', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1152, 103, '什么是双亲委派 ?', '什么是双亲委派 ?', '**双亲委派模型**：简而言之，就是说一个类加载器收到了类加载的请求，不会自己先加载，而是把它**交给自己的父类去加载，层层迭代**。

如果应用程序类加载器收到了一个类加载的请求，会先给扩展类加载器，然后再给启动类加载器，如果启动类加载器无法完成这个类加载的请求，再返回给扩展类加载器，如果扩展类加载器也无法完成，就返回给应用类加载器。

**好处:**

- 说这个问题前我要先和大家说一个概念，JVM中**类的唯一性是由类本身和加载这个类的类加载器决定的。**简单的说，如果有个a类，如果被两个不同的类加载器加载，那么他们必不相等。你看到这里会不会想到所有类的父类都是 Object 是怎么实现的了吗？是因为无论哪一个类加载器加载 Object 类，都会交给最顶层的启动类加载器去加载，这样就**保证了 Object 类在 JVM 中是唯一的**。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1153, 103, '对象的栈上分配?', '对象的栈上分配?', '如果所有对象都分配在堆中那么会给 GC 带来许多不必要的压力，比如有些对象的生命周期只是在当前线程中，为了减少临时对象在堆内分配的数量，就**可以在栈上分配**，随着线程的消亡而消亡。当然栈上空间必须充足，否则也无法分配，在判断是否能分配到栈上的另一条件就是要经过逃逸分析。

**逃逸分析(Escape Analysis)**:

- 简单来讲就是：Java Hotspot 虚拟机判断这个新对象是否只会被当前线程引用，并且决定是否能够在 Java 堆上分配内存。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1154, 103, '对象的内存布局是怎样的?', '对象的内存布局是怎样的?', '**1、对象头**: 对象头又分为 **MarkWord** 和 **Class Pointer** 两部分。

   - **MarkWord**:包含一系列的标记位，比如轻量级锁的标记位，偏向锁标记位，gc记录信息等等。
   - **ClassPointer**:用来指向对象对应的 Class 对象（其对应的元数据对象）的内存地址。在 32 位系统占 4 字节，在 64 位系统中占 8 字节。

**2、Length**: 只在数组对象中存在，用来记录数组的长度，占用 4 字节
**3、Instance data**: 对象实际数据，对象实际数据包括了对象的所有成员变量，其大小由各个成员变量的大小决定。(这里不包括静态成员变量，因为其是在方法区维护的)
**4、Padding**: Java 对象占用空间是 8 字节对齐的，即所有 Java 对象占用 bytes 数必须是 8 的倍数,是因为当我们从磁盘中取一个数据时，不会说我想取一个字节就是一个字节，都是按照一块儿一块儿来取的，这一块大小是 8 个字节，所以为了完整，padding 的作用就是补充字节，**保证对象是 8 字节的整数倍**。', 2, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1155, 103, 'JVM 调优命令？', 'JVM 调优命令？', '* 1、jps：JVM Process Status Tool,显示指定系统内所有的HotSpot虚拟机进程。 
* 2、jstat：jstat(JVM statistics Monitoring)是用于监视虚拟机运行时状态信息的命令，它可以显示出虚拟机进程中的类装载、内存、垃圾收集、JIT编译等运行数据。 
* 3、jmap：jmap(JVM Memory Map)命令用于生成heap dump文件，如果不使用这个命令，还可以使用-XX:+HeapDumpOnOutOfMemoryError参数来让虚拟机出现OOM的时候，自动生成dump文件。
jmap不仅能生成dump文件，还可以查询finalize执行队列、Java堆和永久代的详细信息，如当前使 用率、当前使用的是哪种收集器等。 
* 4、jhat：jhat(JVM Heap Analysis Tool)命令是与jmap搭配使用，用来分析jmap生成的dump，jhat内置了一个微型的HTTP/HTML服务器，生成dump的分析结果后，可以在浏览器中查看。在此要注意，一般不会直接在服务器上进行分析，因为jhat是一个耗时并且耗费硬件资源的过程，一般把服务器生成的dump文件复制到本地或其他机器上进行分析。 
* 5、jstack：jstack用于生成java虚拟机当前时刻的线程快照。jstack来查看各个线程的调用堆栈，就可 以知道没有响应的线程到底在后台做什么事情，或者等待什么资源。 如果java程序崩溃生成core文 件，jstack工具可以用来获得core文件的java stack和native stack的信息，从而可以轻松地知道 java程序是如何崩溃和在程序何处发生问题。', 3, 1, 'technology-talk/interview/tech/JVM 那点破事.md', 1, NOW(3)),
  (1156, 206, 'ISR、AR代表什么？', 'ISR、AR代表什么？', '答案<br />

- AR: 分区中的**所有 Replica 统称为 AR**
- ISR: 所有与 Leader 副本**保持一定程度同步**的 Replica (包括 Leader 副本在内) 组成 ISR
- OSR: 与 Leader 副本**同步滞后过多的** Replica 组成了 OSR

Leader 负责维护和跟踪 ISR 集合中所有 Follower 副本的滞后状态，当 Follower 副本落后过多时，就会将其放入 OSR 集合，当 Follower 副本追上了 Leader 的进度时，就会将其放入 ISR 集合。

:::info
只有 ISR 中的副本才有资格晋升为 Leader。
:::', 2, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1157, 206, '生产者发送数据，ack为 0，1，-1 的含义？', '生产者发送数据，ack为 0，1，-1 的含义？', '<br />这个参数用来指定分区中有多少个副本收到这条消息，生产者才认为这条消息是写入成功的，这个参数有三个值：

- acks = 1，默认为1。生产者发送消息，**只要 leader 副本成功写入消息，就代表成功**。这种方案的问题在于，当返回成功后，如果 leader 副本和 follower 副本还**没有来得及同步**，leader 就崩溃了，那么在选举后新的 leader 就没有这条**消息，也就丢失了**。
- acks = 0。生产者发送消息后直接算写入成功，不需要等待响应。这个方案的问题很明显，**只要服务端写消息时出现任何问题，都会导致消息丢失**。
- acks = -1 或 acks = all。生产者发送消息后，需要等待 ISR 中的所有副本都成功写入消息后才能收到服务端的响应。毫无疑问这种方案的**可靠性是最高**的，但是如果 ISR 中只有leader 副本，那么就和 acks = 1 毫无差别了。', 2, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1158, 206, 'Producer 发送消息？', 'Producer 发送消息？', '<br />Producer 使用带回调通知的发送 API， producer.send(msg, callback)。<br />设置 acks = all。Producer 的一个参数，表示所有副本都成功接收到消息，该消息才算是“已提交”，最高等级，acks的其它值说明。min.insync.replicas > 1，表示消息至少要被写入到多少个副本才算是“已提交”<br />retries 是 Producer 的参数。当出现网络的瞬时抖动时，消息发送可能会失败，此时配置了 retries > 0 的 Producer 能够自动重试消息发送，避免消息丢失。', 2, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1159, 206, '消息解压缩？', '消息解压缩？', '<br />当 Consumer pull消息时，Broker 会原样发送出去，当消息到达 Consumer 端后，由 Consumer 自行解压缩还原成之前的消息。', 1, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1160, 206, '什么是消费者组？', '什么是消费者组？', '<br />消费者组（Consumer Group）允许你分割数据，一个消费者组中可以包含多个消费者进程，他们共同消费该topic的数据。<br />同一个组下的每个实例都配置有相同的组 ID，被分配订阅不同的 topic 分区。当某个实例挂掉的时候，其他实例会自动地承担起它负责消费的分区。 因此，消费者组在一定程度上也保证了消费者程序的高可用性。', 1, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1161, 206, '消费端拉取（批量）、ACK？', '消费端拉取（批量）、ACK？', '<br />消费端先拉取并消费消息，然后再ack更新offset。<br />1）消费者程序启动多个线程，每个线程维护专属的 KafkaConsumer 实例，负责完整的消息拉取、消息处理流程。一个KafkaConsumer负责一个分区，能保证分区内的消息消费顺序。<br />缺点：线程数受限于 Consumer 订阅topic的总分区数。<br />2）任务切分成了消息获取和消息处理两个部分。消费者程序使用单或多线程拉取消息，同时创建专门线程池执行业务逻辑。优点：可以灵活调节消息获取的线程数，以及消息处理的线程数。<br />缺点：无法保证分区内的消息消费顺序。另外引入多组线程，使得整个消息消费链路被拉长，最终导致正确位移提交会变得异常困难，可能会出现消息的重复消费或丢失。', 2, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1162, 206, '分区数越多越好吗？吞吐量就会越高吗？', '分区数越多越好吗？吞吐量就会越高吗？', '<br />一般类似于这种问题的答案，都是持否定态度的。<br />但是可以说，**在一定条件下，分区数的数量是和吞吐量成正比的，分区数和性能也是成正比的**。<br />那么为什么说超过了一定限度，就会对性能造成影响呢？原因如下:<br /><br />**1、客户端/服务器端需要使用的内存就越多**

- 服务端在很多组件中都维护了分区级别的缓存，分区数越大，**缓存成本**也就越大。
- 消费端的消费线程数是和分区数挂钩的，分区数越大消费线程数也就越多，**线程的开销成本**也就越大
- 生产者发送消息有缓存的概念，会为每个分区缓存消息，当积累到一定程度或者时间时会将消息发送到分区，**分区越多，这部分的缓存**也就越大

**2、文件句柄的开销**  <br />**每个 partition 都会对应磁盘文件系统的一个目录**。在 Kafka 的数据日志文件目录中，每个日志数据段都会分配两个文件，一个索引文件和一个数据文件。**每个 broker 会为每个日志段文件打开一个 index 文件句柄和一个数据文件句柄**。因此，随着 partition 的增多，所需要保持打开状态的文件句柄数也就越多，最终可能超过底层操作系统配置的文件句柄数量限制。<br />**3、越多的分区可能增加端对端的延迟**  <br />Kafka 会将分区 HW 之前的消息暴露给消费者。**分区越多则副本之间的同步数量就越多**，在默认情况下，每个 broker 从其他 broker 节点进行数据副本复制时，该 broker 节点只会为此工作分配一个线程，该线程需要完成该 broker 所有 partition 数据的复制。<br />**4、降低高可用性**  <br />在第 13 问我们提到了分区再分配，会将数据复制到另一份副本当中，**分区数量越多，那么恢复时间也就越长**，而如果发生宕机的 broker 恰好是 controller 节点时：在这种情况下，新 leader 节点的选举过程在 controller 节点恢复到新的 broker 之前不会启动。controller 节点的错误恢复将会自动地进行，但是新的 controller 节点需要从 zookeeper 中读取每一个 partition 的元数据信息用于初始化数据。例如，假设一个Kafka 集群存在 10000个partition，从 zookeeper 中恢复元数据时每个 partition 大约花费 2 ms，则 controller 的恢复将会增加约 20 秒的不可用时间窗口。', 3, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1163, 206, '如何提升消费者的消费能力？', '如何提升消费者的消费能力？', '- 1.可以考虑增加 topic 的分区数，并且同时提升消费组的消费者数量，消费者数=分区数。
- 2.如果是消费者消费不及时，可以采用多线程的方式进行消费，并且优化业务方法流程。', 1, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1164, 206, '消费者与 topic 的分区分配策略有哪些？', '消费者与 topic 的分区分配策略有哪些？', '<br /><br />**1、RangeAssignor 分配策略**<br />该分配策略是按照**消费者总数和分区总数进行整除运算**来获得一个跨度，然后分区按照跨度来进行平均分配，尽可能保证分区均匀的分配给所有的消费者。<br />对于每个 topic，该策略会讲消费者组内所有订阅这个主题的消费者**按照名称的字典顺序排序**，然后为每个消费者划分固定过的区域，**如果不够平均分配，那么字典排序考前的就会多分配一个分区**。<br />比如 2 个消费者属于一个消费者组，有 2 个 topic t1，t2，每个 topic 都有 3 个分区，p1，p2，p3，那么分配的情况如下:
```
  消费者A:t0-p0，t0-p1，t1-p0，t1-p1，
  消费者B:t0-p2，t1-p2
```
这样就会出现非配不均匀的情况

**2、RoundRobinAssignor 分配策略**<br />该分配策略是**按将消费者组内所有消费者及消费者订阅的所有主题的分区按照字典排序，然后通过轮询的方式分配给每个消费者**。<br />比如有 3 个消费者 A，B，C，订阅了 3 个 topic ，t0，t1，t2，每个 topic 各有 3 个分区 p0，p1，p2。如果 A 订阅了 t0，B 订阅了 t0 和 t1，C 订阅了 t0，t1，t2，那么分配的情况如下:
```
  消费者A:t0-p0
  消费者B:t1-p0
  消费者C:t1-p1，t2-p0，t2-p1，t2-p2
```
这样也会出现分配不均匀的情况，按照订阅情况来讲完全可以吧 t1p1 分配给消费者B

**3、StickyAssignor分配策略**<br />这种分配策略有两个目的

- 分区的分配要尽可能的均匀
- 分区的分配尽可能的与上次分配的保持相同。

当两者发生冲突时，第一个目标优先于第二个目标。<br />假设消费组内有3个消费者：**C0、C1、C2，**它们都订阅了4个主题：**t0、t1、t2、t3** <br />并且每个主题有2个分区，也就是说整个消费组订阅了，**t0p0、t0p1、t1p0、t1p1、t2p0、t2p1、t3p0、t3p1** 这8个分区。<br /> 最终的分配结果如下：
```
消费者C0：t0p0、t1p1、t3p0

消费者C1：t0p1、t2p0、t3p1

消费者C2：t1p0、t2p1
```
这样初看上去似乎与采用RoundRobinAssignor策略所分配的结果相同<br />此时假设消费者C1脱离了消费组，那么消费组就会执行再平衡操作，进而消费分区会重新分配。如果采用RoundRobinAssignor策略，那么此时的分配结果如下：
```
消费者C0：t0p0、t1p0、t2p0、t3p0

消费者C2：t0p1、t1p1、t2p1、t3p1
```
如分配结果所示，RoundRobinAssignor策略会按照消费者C0和C2进行重新轮询分配。而如果此时使用的是StickyAssignor策略，那么分配结果为：
```
消费者C0：t0p0、t1p1、t3p0、t2p0

消费者C2：t1p0、t2p1、t0p1、t3p1
```
可以看到分配结果中保留了上一次分配中对于消费者C0和C2的所有分配结果，并将原来消费者C1的“负担”分配给了剩余的两个消费者C0和C2，最终C0和C2的分配还保持了均衡。

**如果发生分区重分配，那么对于同一个分区而言有可能之前的消费者和新指派的消费者不是同一个，对于之前消费者进行到一半的处理还要在新指派的消费者中再次复现一遍，这显然很浪费系统资源。StickyAssignor策略如同其名称中的“sticky”一样，让分配策略具备一定的“粘性”，尽可能地让前后两次分配相同，进而减少系统资源的损耗以及其它异常情况的发生**。

到目前为止所分析的都是消费者的订阅信息都是相同的情况，我们来看一下订阅信息不同的情况下的处理。<br />举例：同样消费组内有3个消费者：**C0、C1、C2** <br />集群中有3个主题 **t0、t1、t2** <br />这3个主题分别有 **1、2、3**个分区 <br />也就是说集群中有 **t0p0、t1p0、t1p1、t2p0、t2p1、t2p2** 这6个分区 <br />消费者**C0订阅了主题t0，消费者C1订阅了主题t0和t1，消费者C2订阅了主题t0、t1和t2** <br />如果此时采用RoundRobinAssignor策略：
```
消费者C0：t0p0

消费者C1：t1p0

消费者C2：t1p1、t2p0、t2p1、t2p2
```
如果此时采用的是StickyAssignor策略：
```
消费者C0：t0p0

消费者C1：t1p0、t1p1

消费者C2：t2p0、t2p1、t2p2
```
此时消费者C0脱离了消费组，那么RoundRobinAssignor策略的分配结果为：
```
消费者C1：t0p0、t1p1

消费者C2：t1p0、t2p0、t2p1、t2p2
```
StickyAssignor策略，那么分配结果为：
```
消费者C1：t1p0、t1p1、t0p0

消费者C2：t2p0、t2p1、t2p2
```
可以看到StickyAssignor策略保留了消费者C1和C2中原有的5个分区的分配：
```
t1p0、t1p1、t2p0、t2p1、t2p2。
```
从结果上看StickyAssignor策略比另外两者分配策略而言显得更加的优异，这个策略的代码实现也是异常复杂。

**4、自定义分区分配策略**<br />可以通过实现 org.apache.kafka.clients.consumer.internals.PartitionAssignor 接口来实现', 3, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1165, 206, '如何保证消息的顺序性？', '如何保证消息的顺序性？', '<br />在某些业务场景下，我们需要保证对于有逻辑关联的多条MQ消息被按顺序处理，比如对于某一条数据，正常处理顺序是 新增-更新-删除 ，最终结果是数据被删除。如果消息没有按序消费，处理顺序可能是 删除-新增-更新 ，最终数据没有被删掉，可能会产生一些逻辑错误。对于如何保证消息的顺序性，主要需要考虑如下两点： <br />**1、如何保证消息在 Kafka 中顺序性**<br />对于 Kafka ，如果我们创建了一个 topic ，默认有三个 partition 分区。生产者在写数据的时候，可以指定一个 key ，比如在订单 topic 中我们可以指定订单 id 作为 key ，那么相同订单 id 的数据，会被分发到同一个 partition 中，这个 partition 中的数据一定是有顺序的。消费者从partition 中取出来数据的时候，也一定是有顺序的。通过制定 key 的方式首先可以保证在 kafka 内部消息是有序的。 <br />**2、如何保证消费者处理消费的顺序性**<br />对于某个 topic 的一个 partition ，只能被同组内部的一个 consumer 消费，如果这个 consumer内部还是单线程处理，那么其实只要保证消息在 MQ 内部是有顺序的就可以保证消费也是有顺序的。但是单线程吞吐量太低，在处理大量 MQ 消息时，我们一般会开启多线程消费机制，那么如何保证消息在多个线程之间是被顺序处理的呢？对于多线程消费我们可以预先设置 N 个内存 Queue ，具有相同 key的数据都放到同一个内存 Queue 中；然后开启 N 个线程，每个线程分别消费一个内存 Queue 的数据即可，这样就能保证顺序性。当然，消息放到内存 Queue 中，有可能还未被处理， consumer 发生宕机，内存 Queue 中的数据会全部丢失，这就转变为上面提到的如何保证消息的可靠传输的问题了', 3, 1, 'technology-talk/interview/tech/Kafka 那点破事.md', 1, NOW(3)),
  (1166, 230, 'Kubernetes 特点？', 'Kubernetes 特点？', '<br />1、可移植: 支持公有云、私有云、混合云、多重云（multi-cloud）。<br />2、可扩展: 模块化、插件化、可挂载、可组合。<br />3、自动化: 自动部署、自动重启、自动复制、自动伸缩/扩展。', 1, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1167, 230, '常见的部署方式？', '常见的部署方式？', '<br />1、二进制：从官方下载发行的包，手动部署每个组件，组成 Kubernetes 集群。二进制是 k8s 早期部署方式，相比 Kubeadm 更易维护，容易排查问题<br />2、minikube：在本地轻松运行一个单节点 Kubernetes 集群的工具。<br />3、kubeadm：是一个工具，提供 kubeadm init 和 kubeadm join，用于快速部署 kubernetes，经过时间的考验，也经常使用于生产环境。', 2, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1168, 230, 'Kubernetes 集群相关组件？', 'Kubernetes 集群相关组件？', '- Kubernetes API Server：作为Kubernetes系统的入口，其封装了核心对象的增删改查操作，以RESTful API接口方式提供给外部客户和内部组件调用，集群内各个功能模块之间数据交互和通信的中心枢纽。
- Kubernetes Scheduler：为新建立的Pod进行节点(node)选择(即分配机器)，负责集群的资源调度。
- Kubernetes Controller：负责执行各种控制器，目前已经提供了很多控制器来保证Kubernetes的正常运行。
- Replication Controller：保证Replication Controller定义的副本数量与实际运行Pod数量一致。
- Node Controller：管理维护Node，定期检查Node的健康状态，标识出(失效|未失效)的Node节点。
- Namespace Controller：管理维护Namespace，定期清理无效的Namespace，包括Namesapce下的API对象，比如Pod、Service等。
- Service Controller：管理维护Service，提供负载以及服务代理。
- EndPoints Controller：管理维护Endpoints，关联Service和Pod，创建Endpoints为Service的后端，当Pod发生变化时，实时更新Endpoints。
- Service Account Controller：管理维护Service Account，为每个Namespace创建默认的Service Account，同时为Service Account创建Service Account Secret。
- Persistent Volume Controller：管理维护Persistent Volume和Persistent Volume Claim，为新的Persistent Volume Claim分配Persistent Volume进行绑定，为释放的Persistent Volume执行清理回收。
- Daemon Set Controller：管理维护Daemon Set，负责创建Daemon Pod，保证指定的Node上正常的运行Daemon Pod。
- Deployment Controller：管理维护Deployment，关联Deployment和Replication Controller，保证运行指定数量的Pod。当Deployment更新时，控制实现Replication Controller和Pod的更新。
- Job Controller：管理维护Job，为Jod创建一次性任务Pod，保证完成Job指定完成的任务数目
- Pod Autoscaler Controller：实现Pod的自动伸缩，定时获取监控数据，进行策略匹配，当满足条件时执行Pod的伸缩动作。', 3, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1169, 230, 'Kubernetes Replica Set 和 Replication Controller 区别？', 'Kubernetes Replica Set 和 Replication Controller 区别？', '<br />Replica Set 和 Replication Controller 类似，都是确保在任何给定时间运行指定数量的 Pod 副本。不同之处在于RS 使用基于集合的选择器，而 Replication Controller 使用基于权限的选择器。', 1, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1170, 230, '什么是静态Pod？', '什么是静态Pod？', '<br />静态pod是由kubelet进行管理的仅存在于特定Node的Pod上，他们不能通过API Server进行管理，无法与ReplicationController、Deployment或者DaemonSet进行关联，并且kubelet无法对他们进行健康检查。静态Pod总是由kubelet进行创建，并且总是在kubelet所在的Node上运行。', 1, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1171, 230, '创建一个 Pod 主要流程？', '创建一个 Pod 主要流程？', '<br />1、客户端提交Pod的配置信息（可以是yaml文件定义的信息）到kube-apiserver。<br />2、Apiserver 收到指令后，通知给 controller-manager 创建一个资源对象。<br />3、Controller-manager通过api-server将pod的配置信息存储到ETCD数据中心中。<br />4、Kube-scheduler检测到pod信息会开始调度预选，会先过滤掉不符合Pod资源配置要求的节点，然后开始调度调优，主要是挑选出更适合运行pod的节点，然后将pod的资源配置单发送到node节点上的kubelet组件上。<br />5、Kubelet根据scheduler发来的资源配置单运行pod，运行成功后，将pod的运行信息返回给scheduler，scheduler将返回的pod运行状况的信息存储到etcd数据中心。', 2, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1172, 230, 'Kubernetes中Pod 健康检查方式？', 'Kubernetes中Pod 健康检查方式？', '<br />对Pod的健康检查可以通过两类探针来检查：LivenessProbe和ReadinessProbe。

- LivenessProbe探针：用于判断容器是否存活（running状态），如果LivenessProbe探针探测到容器不健康，则kubelet将杀掉该容器，并根据容器的重启策略做相应处理。若一个容器不包含LivenessProbe探针，kubelet认为该容器的LivenessProbe探针返回值用于是“Success”。
- ReadinessProbe探针：用于判断容器是否启动完成（ready状态）。如果ReadinessProbe探针探测到失败，则Pod的状态将被修改。Endpoint Controller将从Service的Endpoint中删除包含该容器所在Pod的Eenpoint。
- startupProbe探针：启动检查机制，应用一些启动缓慢的业务，避免业务长时间启动而被上面两类探针kill掉。', 2, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1173, 230, 'Kubernetes deployment 升级策略？', 'Kubernetes deployment 升级策略？', '<br />在Deployment的定义中，可以通过spec.strategy指定Pod更新的策略，目前支持两种策略：Recreate（重建）和RollingUpdate（滚动更新），默认值为RollingUpdate。<br />1、Recreate：设置spec.strategy.type=Recreate，表示Deployment在更新Pod时，会先杀掉所有正在运行的Pod，然后创建新的Pod。<br />2、RollingUpdate：设置spec.strategy.type=RollingUpdate，表示Deployment会以滚动更新的方式来逐个更新Pod。同时，可以通过设置spec.strategy.rollingUpdate下的两个参数（maxUnavailable和maxSurge）来控制滚动更新的过程。', 2, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1174, 230, 'Kubernetes Service 类型？', 'Kubernetes Service 类型？', '<br />通过创建Service，可以为一组具有相同功能的容器应用提供一个统一的入口地址，并且将请求负载分发到后端的各个容器应用上。其主要类型有：

- ClusterIP：虚拟的服务IP地址，该地址用于Kubernetes集群内部的Pod访问，在Node上kube-proxy通过设置的iptables规则进行转发；
- NodePort：使用宿主机的端口，使能够访问各Node的外部客户端通过Node的IP地址和端口号就能访问服务；
- LoadBalancer：使用外接负载均衡器完成到服务的负载分发，需要在spec.status.loadBalancer字段指定外部负载均衡器的IP地址，通常用于公有云。', 2, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1175, 230, 'Kubernetes 各模块如何与 API Server 通信？', 'Kubernetes 各模块如何与 API Server 通信？', '<br />Kubernetes API Server作为集群的核心，负责集群各功能模块之间的通信。集群内的各个功能模块通过API Server将信息存入etcd，当需要获取和操作这些数据时，则通过API Server提供的REST接口（用GET、LIST或WATCH方法）来实现，从而实现各模块之间的信息交互。<br />如kubelet进程与API Server的交互：每个Node上的kubelet每隔一个时间周期，就会调用一次API Server的REST接口报告自身状态，API Server在接收到这些信息后，会将节点状态信息更新到etcd中。<br />如kube-controller-manager进程与API Server的交互：kube-controller-manager中的Node Controller模块通过API Server提供的Watch接口实时监控Node的信息，并做相应处理。<br />如kube-scheduler进程与API Server的交互：Scheduler通过API Server的Watch接口监听到新建Pod副本的信息后，会检索所有符合该Pod要求的Node列表，开始执行Pod调度逻辑，在调度成功后将Pod绑定到目标节点上。', 2, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1176, 230, 'Kubernetes Scheduler作用及实现原理？', 'Kubernetes Scheduler作用及实现原理？', '<br />Kubernetes Scheduler是负责Pod调度的重要功能模块，Kubernetes Scheduler在整个系统中承担了“承上启下”的重要功能，“承上”是指它负责接收Controller Manager创建的新Pod，为其调度至目标Node；“启下”是指调度完成后，目标Node上的kubelet服务进程接管后继工作，负责Pod接下来生命周期。<br />Kubernetes Scheduler的作用是将待调度的Pod（API新创建的Pod、Controller Manager为补足副本而创建的Pod等）按照特定的调度算法和调度策略绑定（Binding）到集群中某个合适的Node上，并将绑定信息写入etcd中。<br />在整个调度过程中涉及三个对象，分别是待调度Pod列表、可用Node列表，以及调度算法和策略。<br />Kubernetes Scheduler通过调度算法调度为待调度Pod列表中的每个Pod从Node列表中选择一个最适合的Node来实现Pod的调度。随后，目标节点上的kubelet通过API Server监听到Kubernetes Scheduler产生的Pod绑定事件，然后获取对应的Pod清单，下载Image镜像并启动容器。', 2, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1177, 230, 'Kubernetes Scheduler使用哪两种算法将Pod绑定到worker节点？', 'Kubernetes Scheduler使用哪两种算法将Pod绑定到worker节点？', '<br />Kubernetes Scheduler根据如下两种调度算法将 Pod 绑定到最合适的工作节点：

- 预选（Predicates）：输入是所有节点，输出是满足预选条件的节点。kube-scheduler根据预选策略过滤掉不满足策略的Nodes。如果某节点的资源不足或者不满足预选策略的条件则无法通过预选。如“Node的label必须与Pod的Selector一致”。
- 优选（Priorities）：输入是预选阶段筛选出的节点，优选会根据优先策略为通过预选的Nodes进行打分排名，选择得分最高的Node。例如，资源越富裕、负载越小的Node可能具有越高的排名。', 2, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1178, 230, 'Kubernetes Requests 和 Limits 如何影响Pod的调度？', 'Kubernetes Requests 和 Limits 如何影响Pod的调度？', '<br />当一个Pod创建成功时，Kubernetes调度器（Scheduler）会为该Pod选择一个节点来执行。对于每种计算资源（CPU和Memory）而言，每个节点都有一个能用于运行Pod的最大容量值。调度器在调度时，首先要确保调度后该节点上所有Pod的CPU和内存的Requests总和，不超过该节点能提供给Pod使用的CPU和Memory的最大容量值。', 1, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1179, 230, 'Kubernetes 如何进行优雅的节点关机维护？', 'Kubernetes 如何进行优雅的节点关机维护？', '<br />由于Kubernetes节点运行大量Pod，因此在进行关机维护之前，建议先使用kubectl drain将该节点的Pod进行驱逐，然后进行关机维护。', 1, 1, 'technology-talk/interview/tech/Kubernetes 那点破事.md', 1, NOW(3)),
  (1180, 206, '消息队列缺点？', '消息队列缺点？', '**1、 系统可用性降低**
系统引入的外部依赖越多，越容易挂掉。
**2、 系统复杂度提高**
加入了消息队列，要多考虑很多方面的问题，比如：一致性问题、如何保证消息不被重复消费、如何保证消息可靠性传输等。因此，需要考虑的东西更多，复杂性增大。
**3、 一致性问题**
A 系统处理完了直接返回成功了，人都以为你这个请求就成功了；但是问题是，要是 BCD 三个系统那里，BD 两个系统写库成功了，结果 C 系统写库失败了，这就数据不一致了', 2, 1, 'technology-talk/interview/tech/MQ 那点破事.md', 1, NOW(3)),
  (1181, 110, 'DATETIME 和 TIMESTAMP 的区别？', 'DATETIME 和 TIMESTAMP 的区别？', '<br />**相同点**：

1. 两个数据类型存储时间的表现格式一致。均为 YYYY-MM-DD HH:MM:SS
2. 两个数据类型都包含「日期」和「时间」部分。
3. 两个数据类型都可以存储微秒的小数秒（秒后6位小数秒）

**区别**：

1. **日期范围**：DATETIME 的日期范围是 1000-01-01 00:00:00.000000 到 9999-12-31 23:59:59.999999；TIMESTAMP 的时间范围是1970-01-01 00:00:01.000000 UTC 到 2038-01-09 03:14:07.999999 UTC
2. **存储空间**：DATETIME 的存储空间为 8 字节；TIMESTAMP 的存储空间为 4 字节
3. **时区相关**：DATETIME 存储时间与时区无关；TIMESTAMP 存储时间与时区有关，显示的值也依赖于时区
4. **默认值**：DATETIME 的默认值为 null；TIMESTAMP 的字段默认不为空(not null)，默认值为当前时间(CURRENT_TIMESTAMP)', 2, 1, 'technology-talk/interview/tech/MySQL 那点破事.md', 1, NOW(3)),
  (1182, 110, '如何排查死锁问题？', '如何排查死锁问题？', '1. 查看死锁日志， show engine innodb status;
2. 找出死锁 sql
3. 分析 sql 加锁情况
4. 模拟死锁案发
5. 分析死锁日志
6. 分析死锁结果', 1, 1, 'technology-talk/interview/tech/MySQL 那点破事.md', 1, NOW(3)),
  (1183, 110, 'Hash 索引和 B+ 树索引区别是什么？', 'Hash 索引和 B+ 树索引区别是什么？', '答案 ：

- B+ 树可以进行范围查询，Hash 索引不能。
- B+ 树支持联合索引的最左侧原则，Hash 索引不支持。
- B+ 树支持 order by 排序，Hash 索引不支持。
- Hash 索引在等值查询上比 B+ 树效率更高。
- B+ 树使用 like 进行模糊查询的时候，like 后面（比如 % 开头）的话可以起到优化的作用，Hash 索引根本无法进行模糊查询。', 1, 1, 'technology-talk/interview/tech/MySQL 那点破事.md', 1, NOW(3)),
  (1184, 110, '什么是索引下推优化？', '什么是索引下推优化？', '<br />索引条件下推优化（Index Condition Pushdown (ICP) ）是 MySQL 5.6 添加的，用于优化数据查询。

- 不使用索引条件下推优化时存储引擎通过索引检索到数据，然后返回给MySQL Server，MySQL Server进行过滤条件的判断。
- 当使用索引条件下推优化时，如果存在某些被索引的列的判断条件时，MySQL Server将这一部分判断条件**下推**给存储引擎，然后由存储引擎通过判断索引是否符合MySQL Server传递的条件，只有当索引符合条件时才会将数据检索出来返回给MySQL服务器。

例如一张表，建了一个联合索引（name, age），查询语句：select * from t_user where name like ''张%'' and age=10;，由于name使用了范围查询，根据最左匹配原则：<br />不使用 ICP，引擎层查找到name like ''张%''的数据，再由 Server 层去过滤age=10这个条件，这样一来，就回表了两次，浪费了联合索引的另外一个字段age。<br />但是，使用了索引下推优化，把 where 条件放到引擎层执行，直接根据name like ''张%'' and age=10的条件进行过滤，减少了回表的次数。
:::info
索引条件下推优化可以减少存储引擎查询基础表的次数，也可以减少MySQL服务器从存储引擎接收数据的次数。
:::', 2, 1, 'technology-talk/interview/tech/MySQL 那点破事.md', 1, NOW(3)),
  (1185, 110, '如何判断SQL语句有没有用到索引？', '如何判断SQL语句有没有用到索引？', '<br />通过explain 命令

- id：在一个大的查询语句中每个SELECT关键字都对应一个唯一的id ，如explain select * from s1 where id = (select id from s1 where name = ''egon1''); 第一个select的id是1，第二个select的id是 2。有时候会出现两个select，但是id却都是1，这是因为优化器把子查询变成了连接查询 。
- select_type：select关键字对应的那个查询的类型，如：SIMPLE、PRIMARY、SUBQUERY、DEPENDENT、SNION 
- table：查询对应的表名 
- type： type 字段比较重要，它提供了判断查询是否高效的重要依据依据。通过 type 字段, 我们判断此次查询是 全表扫描 还是 索引扫描 等。如const (主键索引或者唯一二级索引进行等值匹配的情况下)，ref(普通的二级索引列与常量进行等值匹配)，index(扫描全表索引的覆盖索引)   通常来说, 不同的 type 类型的性能如下: ALL < index < range ~ index_merge < ref < eq_ref < const < system ALL 类型因为是全表扫描，相同查询条件下，速度最慢。而 index 类型的查询虽然不是全表扫描，但是它扫描了所有的索引，因此比 ALL 类型的稍快.
- possible_key：查询中可能用到的索引 (可以把用不到的删掉，降低优化器的优化时间) 。
- key：当前查询真正使用到的索引。
- filtered：查询器预测满足下一次查询条件的百分比 。
- rows ：估算 SQL 要查找到结果集需要扫描读取的数据行数， rows 越少越好。
- extra：表示额外信息，如：Using where、Start temporary、End temporary、Using temporary等。

更多内容：[MySQL的explain，你真的会用吗？](https://mp.weixin.qq.com/s/nmT-LCOyChTmbON3bCMoiA)', 3, 1, 'technology-talk/interview/tech/MySQL 那点破事.md', 1, NOW(3)),
  (1186, 110, '数据库 cpu 飙升的话，如何排查？', '数据库 cpu 飙升的话，如何排查？', '1. 使用 top 命令观察，确定是 MySQL 导致还是其他原因。
2. 如果是 MySQL 导致的，show processlist，查看 session 情况，确定是不是有消耗资源的 sql 在运行。
3. 找出消耗高的 sql，看看执行计划是否准确， 索引是否缺失，数据量是否太大。

**如何处理：**

1. kill 掉这些线程 (同时观察 cpu 使用率是否下降)
2. 进行相应的调整 (比如说加索引、改 sql、改内存参数)
3. 重新跑这些 SQL。

**其他情况：**<br />也有可能是每个 sql 消耗资源并不多，但是突然之间，有大量的新 session 连接进来导致 cpu 飙升，这种情况就需要跟应用一起来分析为何连接数会激增，再做出相应的调整，比如说限制连接数等。', 2, 1, 'technology-talk/interview/tech/MySQL 那点破事.md', 1, NOW(3)),
  (1187, 224, '什么是 Nginx？', '什么是 Nginx？', '<br />Nginx是一款免费的、开源的、高性能 HTTP 服务器和反向代理服务器，以其高性能、稳定性、丰富的功能、简单的配置和低资源消耗而闻名。支持 HTTP、HTTPS、SMTP、POP3 和 IMAP 协议。<br />解决了服务器的C10K（就是在一秒之内连接客户端的数目为10k即1万）问题。它的设计不像传统的服务器那样使用线程处理请求，而是一个更加高级的机制，是一种异步事件驱动结构。', 1, 1, 'technology-talk/interview/tech/Nginx 那点破事.md', 1, NOW(3)),
  (1188, 224, 'Nginx 如何处理请求？', 'Nginx 如何处理请求？', '```
server { # 第一个Server区块开始，表示一个独立的虚拟主机站点
   listen       80；# 提供服务的端口，默认80
   server_name localhost; # 提供服务的域名主机名
   location / { # 第一个location区块开始
         root   html; # 站点的根目录，相当于Nginx的安装目录
         index  index.html index.html; # 默认的首页文件，多个用空格分开
} 
```

1、首先，Nginx 在启动时，会解析配置文件，得到需要监听的端口与 IP 地址，然后在 Nginx 的 Master 进程里面先初始化好这个监控的Socket(创建 Socket，设置 addr、reuse 等选项，绑定到指定的 ip 地址端口，再 listen 监听)。<br />2、然后，再 fork(一个现有进程可以调用 fork 函数创建一个新进程。由 fork 创建的新进程被称为子进程 )出多个子进程出来。<br />3、之后，子进程会竞争 accept 新的连接。此时，客户端就可以向 nginx 发起连接了。当客户端与nginx进行三次握手，与 nginx 建立好一个连接后。此时，某一个子进程会 accept 成功，得到这个建立好的连接的 Socket ，然后创建 nginx 对连接的封装，即 ngx_connection_t 结构体。<br />4、接着，设置读写事件处理函数，并添加读写事件来与客户端进行数据的交换。<br />5、最后，Nginx 或客户端来主动关掉连接，到此，一个连接就寿终正寝了。', 3, 1, 'technology-talk/interview/tech/Nginx 那点破事.md', 1, NOW(3)),
  (1189, 224, 'Nginx 如何实现高并发？', 'Nginx 如何实现高并发？', '<br />**异步非阻塞、 epoll 事件机制。**<br />每进来一个 request ，会有一个 worker 进程去处理。但不是全程的处理，处理到什么程度呢？处理到可能发生阻塞的地方，比如向上游（后端）服务器转发 request ，并等待请求返回。那么，这个处理的worker 不会这么傻等着，他会在发送完请求后，注册一个事件：“如果 upstream 返回了，告诉我一声，我再接着干”。于是他就休息去了。此时，如果有新的 request 进来，他可以很快再按这种方式处理。而一旦上游服务器返回了，就会触发这个事件，worker 才会来接手，这个 request 才会接着往下走。', 2, 1, 'technology-talk/interview/tech/Nginx 那点破事.md', 1, NOW(3)),
  (1190, 224, '什么是正向代理？', '什么是正向代理？', '<br />一个位于客户端和原始服务器(origin server)之间的服务器，为了从原始服务器取得内容，客户端向代理发送一个请求并指定目标 (原始服务器)，然后代理向原始服务器转交请求并将获得的内容返回给客户端。客户端才能使用正向代理。
> 总结就一句话：代理的是客户端。比如：我们使用的OpenVPN 等', 1, 1, 'technology-talk/interview/tech/Nginx 那点破事.md', 1, NOW(3)),
  (1191, 224, 'Nginx 负载均衡的算法有哪些?', 'Nginx 负载均衡的算法有哪些?', '<br />为了避免服务器崩溃，通过负载均衡的方式来分担服务器压力。将对台服务器组成一个集群，当用户访问时，先访问到一个转发服务器，再由转发服务器将访问分发到压力更小的服务器。

Nginx 负载均衡实现的策略有以下五种：<br />**1 .轮询(默认)**<br />每个请求按时间顺序逐一分配到不同的后端服务器，如果后端某个服务器宕机，能自动剔除故障系统。
```
upstream backserver {
 server 192.168.0.12;
 server 192.168.0.13;
}
```

**2. 权重 weight**<br />weight的值越大，分配到的访问概率越高，主要用于后端每台服务器性能不均衡的情况下。其次是为在主从的情况下设置不同的权值，达到合理有效的地利用主机资源。
```
# 权重越高，在被访问的概率越大，如上例，分别是20%，80%。
upstream backserver {
 server 192.168.0.12 weight=2;
 server 192.168.0.13 weight=8;
}
```

**3. ip_hash( IP绑定)**<br />每个请求按访问IP的哈希结果分配，使来自同一个IP的访客固定访问一台后端服务器，并且可以有效解决动态网页存在的session共享问题
```
upstream backserver {
 ip_hash;
 server 192.168.0.12:88;
 server 192.168.0.13:80;
}
```

**4. fair(第三方插件)**<br />必须安装upstream_fair模块。对比 weight、ip_hash更加智能的负载均衡算法，fair算法可以根据页面大小和加载时间长短智能地进行负载均衡，响应时间短的优先分配。
```
# 哪个服务器的响应速度快，就将请求分配到那个服务器上。
upstream backserver {
 server server1;
 server server2;
 fair;
}
```

**5.url_hash(第三方插件)**<br />必须安装Nginx的hash软件包按访问url的hash结果来分配请求，使每个url定向到同一个后端服务器，可以进一步提高后端缓存服务器的效率。
```
upstream backserver {
 server squid1:3128;
 server squid2:3128;
 hash $request_uri;
 hash_method crc32;
}
```', 3, 1, 'technology-talk/interview/tech/Nginx 那点破事.md', 1, NOW(3)),
  (1192, 224, 'Nginx 如何实现后端服务的健康检查？', 'Nginx 如何实现后端服务的健康检查？', '<br />1、利用 nginx 自带模块 ngx_http_proxy_module 和 ngx_http_upstream_module 对后端节点做健康检查。<br />2、利用 nginx_upstream_check_module 模块对后端节点做健康检查，推荐该方式。', 1, 1, 'technology-talk/interview/tech/Nginx 那点破事.md', 1, NOW(3)),
  (1193, 224, 'Nginx 如何开启压缩？', 'Nginx 如何开启压缩？', '<br />开启nginx `gzip` 压缩后，网页、css、js 等静态资源的大小会大大的减少，从而可以节约大量的网络带宽，提高传输效率，给用户快的体验。<br />虽然会消耗cpu资源，但是为了给用户更好的体验是值得的。开启的配置如下：将以下配置放到nginx.conf 的 http{ … } 模块中
```
http {
  # 开启gzip
  gzip on;
 
  # 启用gzip压缩的最小文件；小于设置值的文件将不会被压缩
  gzip_min_length 1k;
 
  # gzip 压缩级别 1-10
  gzip_comp_level 2;
 
  # 进行压缩的文件类型
  gzip_types text/plain application/javascript application/x-javascript text/css application/xml text/javascript application/x-httpd-php image/jpeg image/gif image/png;
 
  # 是否在http header中添加Vary: Accept-Encoding，建议开启
  gzip_vary on;
}
```

保存并重启nginx，刷新页面（为了避免缓存，请强制刷新）就能看到效果了', 2, 1, 'technology-talk/interview/tech/Nginx 那点破事.md', 1, NOW(3)),
  (1194, 120, 'RDB 优缺点？', 'RDB 优缺点？', '<br />把某个时间点 redis 内存中的数据以二进制的形式存储的一个.rdb为后缀的文件当中，也就是「周期性的备份redis中的整个数据」，这是redis默认的持久化方式，也就是我们说的快照(snapshot)，是采用 fork 子进程的方式来写时同步的。<br />**优点：**

- 将某一时间点redis内的所有数据保存下来，当我们做「大型的数据恢复时，RDB的恢复速度会很快」
- 由于RDB的FROK子进程这种机制，对客户端提供读写服务的影响会非常小

**缺点：**

- 举个例子假设我们定时5分钟备份一次，在10:00的时候 redis 备份了数据，但是如果在10:04的时候服务挂了，那么我们就会丢失在10:00到10:04的整个数据
- 1:「有可能会产生长时间的数据丢失」
- 2:可能会有长时间停顿：我们前面讲了，fork 子进程这个过程是和 redis 的数据量有很大关系的，如果「数据量很大,那么很有可能会使redis暂停几秒', 2, 1, 'technology-talk/interview/tech/Redis 缓存那点破事.md', 1, NOW(3)),
  (1195, 120, '什么时候触发 RDB 机制？', '什么时候触发 RDB 机制？', '<br />1、通过配置文件，设置一定时间后自动执行RDB<br />2、如采用主从复制过程，会自动执行RDB<br />3、Redis 执行shutdown时，在未开启AOF后会执行RDB', 1, 1, 'technology-talk/interview/tech/Redis 缓存那点破事.md', 1, NOW(3)),
  (1196, 120, 'AOF 持久化策略？', 'AOF 持久化策略？', '<br />1、always：每执行一次数据修改命令就将其命令写入到磁盘日志文件上。<br />2、everysec：每秒将命令写入到磁盘日志文件上。<br />3、no：不主动设置，由操作系统决定什么时候写入到磁盘日志文件上。', 1, 1, 'technology-talk/interview/tech/Redis 缓存那点破事.md', 1, NOW(3)),
  (1197, 120, '缓存集中失效如何解决？', '缓存集中失效如何解决？', '<br />当业务系统查询数据时，首先会查询缓存，如果缓存中数据不存在，然后查询DB再将数据预热到Cache中，并返回。缓存的性能比 DB 高 50~100 倍以上。<br />很多业务场景，如：秒杀商品、微博热搜排行、或者一些活动数据，都是通过跑任务方式，将DB数据批量、集中预热到缓存中，缓存数据有着近乎相同的过期时间。<br />当过这批数据过期时，会一起过期，此时，对这批数据的所有请求，都会出现缓存失效，从而将压力转嫁到DB，DB的请求量激增，压力变大，响应开始变慢。<br />**那么有没有解呢？**<br />当然有了。<br />我们可以从缓存的过期时间入口，将原来的固定过期时间，调整为过期时间=基础时间+随机时间，让缓存慢慢过期，避免瞬间全部过期，对DB产生过大压力。', 2, 1, 'technology-talk/interview/tech/Redis 缓存那点破事.md', 1, NOW(3)),
  (1198, 120, '缓存雪崩如何解决？', '缓存雪崩如何解决？', '<br />缓存雪崩是指部分缓存节点不可用，进而导致整个缓存体系甚至服务系统不可用的情况。<br />分布式缓存设计一般选择一致性Hash，当有部分节点异常时，采用 rehash 策略，即把异常节点请求平均分散到其他缓存节点。但是，当较大的流量洪峰到来时，如果大流量 key 比较集中，正好在某 1～2 个缓存节点，很容易将这些缓存节点的内存、网卡过载，缓存节点异常 Crash，然后这些异常节点下线，这些大流量 key 请求又被 rehash 到其他缓存节点，进而导致其他缓存节点也被过载 Crash，缓存异常持续扩散，最终导致整个缓存体系异常，无法对外提供服务。

**解决方案：**

- 方案一：增加实时监控，及时预警。通过机器替换、各种故障自动转移策略，快速恢复缓存对外的服务能力
- 方案二：缓存增加多个副本，当缓存异常时，再读取其他缓存副本。为了保证副本的可用性，尽量将多个缓存副本部署在不同机架上，降低风险。
- 方案三：设置热点数据永远不过期
- 方案四：采用多级缓存，分层扛压
- 方案五：缓存数据的过期时间随机，防止同一时间大量数据集中过期。', 2, 1, 'technology-talk/interview/tech/Redis 缓存那点破事.md', 1, NOW(3)),
  (1199, 120, '缓存 key 过大如何解决？', '缓存 key 过大如何解决？', '<br />当访问缓存时，如果key对应的value过大，读写、加载很容易超时，容易引发网络拥堵。另外缓存的字段较多时，每个字段的变更都会引发缓存数据的变更，频繁的读写，导致慢查询。如果大key过期被缓存淘汰失效，预热数据要花费较多的时间，也会导致慢查询。<br />所以我们在设计缓存的时候，要注意缓存的粒度，既不能过大，如果过大很容易导致网络拥堵；也不能过小，如果太小，查询频率会很高，每次请求都要查询多次。<br />**解决方案：**

- 方案一：设置一个阈值，当value的长度超过阈值时，对内容启动压缩，降低kv的大小
- 方案二：评估大key所占的比例，由于很多框架采用池化技术，如：Memcache，可以预先分配大对象空间。真正业务请求时，直接拿来即用。
- 方案三：颗粒划分，将大key拆分为多个小key，独立维护，成本会降低不少
- 方案四：大key要设置合理的过期时间，尽量不淘汰那些大key', 2, 1, 'technology-talk/interview/tech/Redis 缓存那点破事.md', 1, NOW(3)),
  (1200, 206, '为什么要主动拉取消息而不是事件监听方式？', '为什么要主动拉取消息而不是事件监听方式？', '<br />事件驱动方式是建立好长连接，由事件（发送数据）的方式来实时推送。<br />如果broker主动推送消息的话有可能push速度快，消费速度慢的情况，那么就会造成消息在consumer端堆积过多，同时又不能被其他consumer消费的情况。而pull的方式可以根据当前自身情况来拉取，不会造成过多的压力而造成瓶颈，所以采取了pull的方式。', 1, 1, 'technology-talk/interview/tech/RocketMQ 那点破事.md', 1, NOW(3)),
  (1201, 206, 'RocketMQ 如何保证消息不丢失？', 'RocketMQ 如何保证消息不丢失？', '<br />首先在如下三个部分都可能会出现丢失消息的情况：

- Producer端
- Broker端
- Consumer端 

**1 、Producer端如何保证消息不丢失**

- 采取send()同步发消息，发送结果是同步感知的。
- 发送失败后可以重试，设置重试次数。默认3次。
- 集群部署，比如发送失败了的原因可能是当前Broker宕机了，重试的时候会发送到其他Broker上。 

**2、Broker端如何保证消息不丢失**

- 修改刷盘策略为同步刷盘。默认情况下是异步刷盘的
- 集群部署，主从模式，高可用

**3、Consumer端如何保证消息不丢失**

- 完全消费正常后在进行手动ack确认', 2, 1, 'technology-talk/interview/tech/RocketMQ 那点破事.md', 1, NOW(3)),
  (1202, 206, 'RocketMQ 消息堆积如何处理？', 'RocketMQ 消息堆积如何处理？', '<br />首先要找到是什么原因导致的消息堆积，是Producer太多了，Consumer太少了导致的还是说其他情 况，总之先定位问题。<br />然后看下消息消费速度是否正常，正常的话，可以通过上线更多consumer临时解决消息堆积问题', 1, 1, 'technology-talk/interview/tech/RocketMQ 那点破事.md', 1, NOW(3)),
  (1203, 170, 'Spring 框架的好处？', 'Spring 框架的好处？', '答案 ：<br />1、轻量：Spring 是轻量的，基本的版本大约2MB<br />2、控制反转：Spring 通过控制反转实现了松散耦合，对象们给出它们的依赖，而不是创建或查找依赖的对象们<br />3、面向切面的编程(AOP)：Spring支持面向切面的编程，并且把应用业务逻辑和系统服务分开<br />4、容器：Spring 包含并管理应用中对象的生命周期和配置<br />5、MVC框架：Spring的WEB框架是个精心设计的框架，是Web框架的一个很好的替代品<br />6、事务管理：Spring 提供一个持续的事务管理接口，可以扩展到上至本地事务下至全局事务（JTA）<br />7、异常处理：Spring 提供方便的API把具体技术相关的异常（比如由JDBC，Hibernate or JDO抛出的）转化为一致的unchecked 异常。', 2, 1, 'technology-talk/interview/tech/Spring 那点破事.md', 1, NOW(3)),
  (1204, 170, 'Bean 的作用域?', 'Bean 的作用域?', '<br />1、singleton : 唯一 bean 实例，Spring 中的 bean 默认都是单例的。<br />2、prototype : 每次请求都会创建一个新的 bean 实例。<br />3、request : 每一次HTTP请求都会产生一个新的bean，该bean仅在当前 HTTP request 内有效。<br />4、session : ：在一个HTTP Session中，一个Bean定义对应一个实例。该作用域仅在基于web的 Spring ApplicationContext情形下有效。<br />5、global-session： 全局session作用域，仅仅在基于portlet的web应用中才有意义，Spring5已经没有了。Portlet是能够生成语义代码(例如：HTML)片段的小型Java Web插件。它们基于portlet容器，可以像servlet一样处理HTTP请求。但是，与 servlet 不同，每个 portlet 都有不同的会话', 2, 1, 'technology-talk/interview/tech/Spring 那点破事.md', 1, NOW(3)),
  (1205, 170, 'Bean 生命周期扩展方式？', 'Bean 生命周期扩展方式？', '<br />1、 InitializingBean 和 DisposableBean 回调接口<br />2、针对特殊行为的其他 Aware 接口<br />3、实现 BeanPostProcessor 接口，则会回调该接口的前置和后置处理增强<br />4、Bean 配置文件中的 init()方法和 destroy()方法<br />5、@PostConstruct 和 @PreDestroy 注解方式', 1, 1, 'technology-talk/interview/tech/Spring 那点破事.md', 1, NOW(3)),
  (1206, 171, 'Spring Boot Starter 自动配置原理？', 'Spring Boot Starter 自动配置原理？', '<br />1、Spring Boot 关于自动配置的源码在 spring-boot-autoconfigure-x.x.x.x.jar 中<br />2、@SpringBootApplication 中有一个注解@EnableAutoConfiguration，负责开启自动配置<br />3、通过SpringFactoriesLoader.loadFactoryNames() 扫描 META-INF/spring.factories配置文件中的自动配置类，是一组一组的key=value 键值对<br /><br />4、其中一个key是EnableAutoConfiguration类的全类名，而它的 value 是一个 xxxxAutoConfiguration 的类名的列表，它实际上是一个javaConfig 形式的 Spring 容器配置类，根据 @ConditionalOnClass注解条件，选择性的将这些自动配置类加载到Spring容器中。

**自动配置生效**<br />每一个XxxxAutoConfiguration 自动配置类都是在某些条件之下才会生效的，这些条件的限制在Spring Boot中以注解的形式体现，常见的条件注解有如下几项：

- @ConditionalOnBean：当容器里有指定的bean的条件下。
- @ConditionalOnMissingBean：当容器里不存在指定bean的条件下。
- @ConditionalOnClass：当类路径下有指定类的条件下。
- @ConditionalOnMissingClass：当类路径下不存在指定类的条件下。
- @ConditionalOnProperty：指定的属性是否有指定的值，比如@ConditionalOnProperties(prefix=”xxx.xxx”, value=”enable”, matchIfMissing=true)，代表当xxx.xxx为enable时条件的布尔值为true，如果没有设置的情况下也为true。', 3, 1, 'technology-talk/interview/tech/Spring Boot 那点破事.md', 1, NOW(3)),
  (1207, 171, '什么是**YAML**？', '什么是**YAML**？', '<br />YAML 是⼀种⼈类可读的数据序列化语⾔。它通常⽤于配置⽂件。与属性⽂件相⽐，如果我们想要在配置⽂件中添加复杂的属性，YAML ⽂件就更加结构化，⽽且更少混淆。可以看出 YAML 具有分层配置数据。', 1, 1, 'technology-talk/interview/tech/Spring Boot 那点破事.md', 1, NOW(3)),
  (1208, 171, '什么是 Spring Data JPA？', '什么是 Spring Data JPA？', '<br />SpringData JPA ，全称Java Persistence API。是 Spring Data 框架下的一个基于JPA标准操作数据的模块。简化操作持久层的代码，只需要编写接口就可以。<br />JPA 和 Mybatis 作用是相同的，都是持久层框架。', 1, 1, 'technology-talk/interview/tech/Spring Boot 那点破事.md', 1, NOW(3)),
  (1209, 171, 'Spring Boot 打成的 jar 和普通的 jar 有什么区别 ?', 'Spring Boot 打成的 jar 和普通的 jar 有什么区别 ?', '<br />Spring Boot的项目终止以jar包的形式进行打包，这种jar包可以通过可以通过命令（java -jar xxx.jar）来运行的，这种jar包不能被其他项目所依赖，即使被依赖了也不能直接使用其中的类。<br />普通的jar包，解压后直接就是包名，包里就是我们的代码，而 Spring Boot 打包成的可执行 jar 解压后，在 \\BOOT-INF\\classes 目录下才是我们的代码，因此无法被直接引用。如果非要引用，可以在 pom.xml 文件中增加配置，将 Spring Boot 项目打包成两个 jar ，一个可执行，一个可引用。

```
<build>
        <plugins>
            <plugin>
                <groupId>org.springframework.boot</groupId>
                <artifactId>spring-boot-maven-plugin</artifactId>
                <executions>
                    <execution>
                        <goals>
                            <!--可以把依赖的包都打包到生成的Jar包中 -->
                            <goal>repackage</goal>
                        </goals>
                        <!--可以生成不含依赖包的不可执行Jar包 -->
                        <configuration>
                            <classifier>exec</classifier>
                        </configuration>
                    </execution>
                </executions>
            </plugin>
            <plugin>
                <artifactId>maven-compiler-plugin</artifactId>
                <configuration>
                    <source>1.8</source>
                    <target>1.8</target>
                </configuration>
            </plugin>
        </plugins>
    </build>
```
一次打包生成两个jar包，其中XXX.jar 可作为其它工程的依赖，XXX-exec.jar可被执行<br />', 3, 1, 'technology-talk/interview/tech/Spring Boot 那点破事.md', 1, NOW(3)),
  (1210, 171, '开启 **Spring Boot**特性有哪⼏种⽅式？', '开启 **Spring Boot**特性有哪⼏种⽅式？', '<br />1、继承 spring-boot-starter-parent 项⽬<br />2、添加 spring-boot-dependencies jar包依赖', 1, 1, 'technology-talk/interview/tech/Spring Boot 那点破事.md', 1, NOW(3)),
  (1211, 171, 'SpringBoot、Spring MVC 和 Spring 有什么区别？', 'SpringBoot、Spring MVC 和 Spring 有什么区别？', '<br />**1、 Spring**<br />Spring最重要的特征是依赖注入。所有 Spring Modules 不是依赖注入就是 IOC 控制反转。当我们恰当的使用 DI 或者是 IOC 的时候，我们可以开发松耦合应用。<br />**2、 Spring MVC**<br />Spring MVC 提供了一种分离式的方法来开发 Web 应用。通过像 DispatcherServlet，ModelAndView 和 ViewResolver 等一些简单的概念，开发 Web 应用将会变的非常简单。<br />**3、 Spring Boot**<br />Spring 和 SpringMVC 的问题在于需要配置大量的参数。SpringBoot 通过一个自动配置来解决这个问题。为了更快的构建产品，SpringBoot 提供了一些非功能性特征。', 2, 1, 'technology-talk/interview/tech/Spring Boot 那点破事.md', 1, NOW(3)),
  (1212, 205, '什么是 Spring Cloud？', '什么是 Spring Cloud？', '<br />Spring Cloud 是一个服务治理平台，是若干个框架的集合，提供了全套的分布式系统解决方案。<br />包含：服务注册与发现、配置中心、服务网关、智能路由、负载均衡、断路器、监控跟踪、分布式消息队列等等。', 1, 1, 'technology-talk/interview/tech/Spring Cloud 那点破事.m', 1, NOW(3)),
  (1213, 205, 'Spring Cloud 的优缺点？', 'Spring Cloud 的优缺点？', '答案<br />微服务的框架那么多⽐如：dubbo、Kubernetes，为什么还要使⽤Spring Cloud呢？<br />**优点：**<br />1、出自 Spring家族，应用广泛，可以保证后续的更新、完善<br />2、组件丰富，功能⻬全。Spring Cloud 为微服务架构提供了⾮常完整的⽀持。如：配置管理、服务发现、断路器、微服务⽹关等；<br />3、Spring Cloud 社区活跃度很⾼，遇到问题很容易找到解决⽅案<br />4、服务拆分粒度更细，耦合度⽐较低，有利于资源重复利⽤，提⾼开发效率<br />5、可以更精准的制定优化服务⽅案，提⾼系统的可维护性<br />6、减轻团队的成本，前期预先定义好接口规范，并⾏开发<br />7、跨平台性，可以⽤任何⼀种语⾔开发<br />8、适于互联⽹时代的快节奏，产品迭代周期更短<br />**缺点：**<br />1、微服务过多，系统治理成本⾼，不利于维护系统<br />2、分布式系统开发的成本⾼（容错，分布式事务等）对团队挑战⼤', 2, 1, 'technology-talk/interview/tech/Spring Cloud 那点破事.m', 1, NOW(3)),
  (1214, 205, '服务注册和发现是什么？', '服务注册和发现是什么？', '<br />当我们开始⼀个项⽬时，我们通常在属性⽂件中进⾏相应的配置。随着越来越多的服务开发和部署，添加和修改这些属性变得更加复杂。有些服务可能会下线，⽽有些服务地址可能会发⽣变化。⼿动更改成本高。<br />Eureka 服务注册和发现可以解决这个问题。所有服务都在 Eureka 服务器上注册并通过调⽤ Eureka 服务器完成查找，因此⽆需处理服务单点的任何更改和处理。', 1, 1, 'technology-talk/interview/tech/Spring Cloud 那点破事.m', 1, NOW(3)),
  (1215, 150, '分布式 Session 解决方案？', '分布式 Session 解决方案？', '- 客户端存储：直接将信息存储在cookie中，cookie是存储在客户端上的一小段数据，客户端通过 http协议和服务器进行 cookie 交互，通常用来存储一些不敏感信息
- Nginx ip_hash 策略：服务端使用 Nginx 代理，每个请求按访问 IP 的 hash 分配，这样来自同一 IP 固定访问一个后台服务器，避免了在服务器 A 创建 Session，第二次分发到服务器 B 的现象。
- Session 复制：任何一个服务器上的 Session 发生改变（增删改），该节点会把这个 Session 的所有内容序列化，然后广播给所有其它节点。
- 共享 Session：服务端无状态话，将用户的 Session 等信息使用缓存中间件（如：Redis）来统一管理，保障分发到每一个服务器的响应结果都一致。', 2, 1, 'technology-talk/interview/tech/TCP 网络那点破事.md', 1, NOW(3)),
  (1216, 150, '如何避免 SQL 注入？', '如何避免 SQL 注入？', '<br />SQL 注入就是在用户输入的字符串中加入 SQL 语句，如果在设计不良的程序中忽略了检查，那么这些注入进去的 SQL 语句就会被数据库服务器误认为是正常的 SQL 语句而运行，攻击者就可以执行计划外的命令或访问未被授权的数据。<br />**解决方案：**

- 限制数据库权限，给用户提供仅仅能够满足其工作的最低权限。
- 对进入数据库的特殊字符（’”\\尖括号&*;等）转义处理。
- 提供参数化查询接口，不要直接使用原生SQL。', 2, 1, 'technology-talk/interview/tech/TCP 网络那点破事.md', 1, NOW(3)),
  (1217, 206, '消息队列有什么优缺点？', '消息队列有什么优缺点？', '**优点：**

解耦、异步、削峰

**缺点：**

系统可用性降低。系统引入的外部依赖越多，越容易挂掉。本来你就是 A 系统调用 BCD 三个系统的接口就好了，人 ABCD 四个系统好好的，没啥问题，你偏加个 MQ 进来，万一 MQ 挂了咋整，MQ 一挂，整套系统崩溃的，你不就完了？

系统复杂度提高。硬生生加个 MQ 进来，你怎么保证消息没有重复消费？怎么处理消息丢失的情况？怎么保证消息传递的顺序性？头大头大，问题一大堆，痛苦不已。

一致性问题 A 系统处理完了直接返回成功了，人都以为你这个请求就成功了；但是问题是，要是 BCD 三个系统那里，BD 两个系统写库成功了，结果 C 系统写库失败了，咋整？你这数据就不一致了。

所以消息队列实际是一种非常复杂的架构，你引入它有很多好处，但是也得针对它带来的坏处做各种额外的技术方案和架构来规避掉，做好之后，你会发现，妈呀，系统复杂度提升了一个数量级，也许是复杂了 10 倍。但是关键时刻，用，还是得用的。', 2, 1, 'technology-talk/middleware/mq/关于消息队列，面试官一般都会问哪些.md', 1, NOW(3)),
  (1218, 206, '如何保证消息队列的高可用？', '如何保证消息队列的高可用？', 'Kafka 一个最基本的架构认识：由多个 broker 组成，每个 broker 是一个节点；你创建一个 topic，这个 topic 可以划分为多个 partition，每个 partition 可以存在于不同的 broker 上，每个 partition 就放一部分数据。这就是天然的分布式消息队列，就是说一个 topic 的数据，是分散放在多个机器上的，每个机器就放一部分数据。

实际上 RabbmitMQ 之类的，并不是分布式消息队列，它就是传统的消息队列，只不过提供了一些集群、HA(High Availability, 高可用性) 的机制而已，因为无论怎么玩儿，RabbitMQ 一个 queue 的数据都是放在一个节点里的，镜像集群下，也是每个节点都放这个 queue 的完整数据。

Kafka 0.8 以前，是没有 HA 机制的，就是任何一个 broker 宕机了，那个 broker 上的 partition 就废了，没法写也没法读，没有什么高可用性可言。比如说，我们假设创建了一个 topic，指定其 partition 数量是 3 个，分别在三台机器上。但是，如果第二台机器宕机了，会导致这个 topic 的 1/3 的数据就丢了，因此这个是做不到高可用的。

Kafka 0.8 以后，提供了 HA 机制，就是 replica（复制品） 副本机制。每个 partition 的数据都会同步到其它机器上，形成自己的多个 replica 副本。所有 replica 会选举一个 leader 出来，那么生产和消费都跟这个 leader 打交道，然后其他 replica 就是 follower。写的时候，leader 会负责把数据同步到所有 follower 上去，读的时候就直接读 leader 上的数据即可。只能读写 leader？很简单，要是你可以随意读写每个 follower，那么就要 care 数据一致性的问题，系统复杂度太高，很容易出问题。Kafka 会均匀地将一个 partition 的所有 replica 分布在不同的机器上，这样才可以提高容错性。

这么搞，就有所谓的高可用性了，因为如果某个 broker 宕机了，没事儿，那个 broker 上面的 partition 在其他机器上都有副本的。如果这个宕机的 broker 上面有某个 partition 的 leader，那么此时会从 follower 中重新选举一个新的 leader 出来，大家继续读写那个新的 leader 即可。这就有所谓的高可用性了。

写数据的时候，生产者就写 leader，然后 leader 将数据落地写本地磁盘，接着其他 follower 自己主动从 leader 来 pull 数据。一旦所有 follower 同步好数据了，就会发送 ack 给 leader，leader 收到所有 follower 的 ack 之后，就会返回写成功的消息给生产者。（当然，这只是其中一种模式，还可以适当调整这个行为）

消费的时候，只会从 leader 去读，但是只有当一个消息已经被所有 follower 都同步成功返回 ack 的时候，这个消息才会被消费者读到。', 3, 1, 'technology-talk/middleware/mq/关于消息队列，面试官一般都会问哪些.md', 1, NOW(3)),
  (1219, 206, '如何保证消息消费的幂等性？', '如何保证消息消费的幂等性？', '首先，比如 RabbitMQ、RocketMQ、Kafka，都有可能会出现消息重复消费的问题，正常。因为这问题通常不是 MQ 自己保证的，是由我们开发来保证的。挑一个 Kafka 来举个例子，说说怎么重复消费吧。

Kafka 实际上有个 offset 的概念，就是每个消息写进去，都有一个 offset，代表消息的序号，然后 consumer 消费了数据之后，每隔一段时间（定时定期），会把自己消费过的消息的 offset 提交一下，表示“我已经消费过了，下次我要是重启啥的，你就让我继续从上次消费到的 offset 来继续消费吧”。

但是凡事总有意外，比如我们之前生产经常遇到的，就是你有时候重启系统，看你怎么重启了，如果碰到点着急的，直接 kill 进程了，再重启。这会导致 consumer 有些消息处理了，但是没来得及提交 offset，尴尬了。重启之后，少数消息会再次消费一次。

举个栗子。有这么个场景。数据 1/2/3 依次进入 kafka，kafka 会给这三条数据每条分配一个 offset，代表这条数据的序号，我们就假设分配的 offset 依次是 152/153/154。消费者从 kafka 去消费的时候，也是按照这个顺序去消费。假如当消费者消费了 offset=153 的这条数据，刚准备去提交 offset 到 zookeeper，此时消费者进程被重启了。那么此时消费过的数据 1/2 的 offset 并没有提交，kafka 也就不知道你已经消费了 offset=153 这条数据。那么重启之后，消费者会找 kafka 说，嘿，哥儿们，你给我接着把上次我消费到的那个地方后面的数据继续给我传递过来。由于之前的 offset 没有提交成功，那么数据 1/2 会再次传过来，如果此时消费者没有去重的话，那么就会导致重复消费。

如果消费者干的事儿是拿一条数据就往数据库里写一条，会导致说，你可能就把数据 1/2 在数据库里插入了 2 次，那么数据就错啦。其实重复消费不可怕，可怕的是你没考虑到重复消费之后，怎么保证幂等性。

举个例子吧。假设你有个系统，消费一条消息就往数据库里插入一条数据，要是你一个消息重复两次，你不就插入了两条，这数据不就错了？但是你要是消费到第二次的时候，自己判断一下是否已经消费过了，若是就直接扔了，这样不就保留了一条数据，从而保证了数据的正确性。一条数据重复出现两次，数据库里就只有一条数据，这就保证了系统的幂等性。

所以第二个问题来了，怎么保证消息队列消费的幂等性？其实还是得结合业务来思考，我这里给几个思路：

* 比如你拿个数据要写库，你先根据主键查一下，如果这数据都有了，你就别插入了，update 一下好吧。

* 比如你是写 Redis，那没问题了，反正每次都是 set，天然幂等性。

* 比如你不是上面两个场景，那做的稍微复杂一点，你需要让生产者发送每条数据的时候，里面加一个全局唯一的 id，类似订单 id 之类的东西，然后你这里消费到了之后，先根据这个 id 去比如 Redis 里查一下，之前消费过吗？如果没有消费过，你就处理，然后这个 id 写 Redis。如果消费过了，那你就别处理了，保证别重复处理相同的消息即可。

* 比如基于数据库的唯一键来保证重复数据不会重复插入多条。因为有唯一键约束了，重复数据插入只会报错，不会导致数据库中出现脏数据。', 3, 1, 'technology-talk/middleware/mq/关于消息队列，面试官一般都会问哪些.md', 1, NOW(3)),
  (1220, 206, '生产者会不会弄丢数据？', '生产者会不会弄丢数据？', '如果按照上述的思路设置了 acks=all，一定不会丢，要求是，你的 leader 接收到消息，所有的 follower 都同步到了消息之后，才认为本次写成功了。如果不满足这个条件，生产者会自动不断的重试，重试无限次。', 1, 1, 'technology-talk/middleware/mq/关于消息队列，面试官一般都会问哪些.md', 1, NOW(3)),
  (1221, 206, '如何保证消息传递的顺序性？', '如何保证消息传递的顺序性？', '我举个例子，我们以前做过一个 mysql binlog 同步的系统，压力还是非常大的，日同步数据要达到上亿，就是说数据从一个 mysql 库原封不动地同步到另一个 mysql 库里面去（mysql -> mysql）。常见的一点在于说比如大数据 team，就需要同步一个 mysql 库过来，对公司的业务系统的数据做各种复杂的操作。

你在 mysql 里增删改一条数据，对应出来了增删改 3 条 binlog 日志，接着这三条 binlog 发送到 MQ 里面，再消费出来依次执行，起码得保证人家是按照顺序来的吧？不然本来是：增加、修改、删除；你楞是换了顺序给执行成删除、修改、增加，不全错了么。

本来这个数据同步过来，应该最后这个数据被删除了；结果你搞错了这个顺序，最后这个数据保留下来了，数据同步就出错了。

**先看看顺序会错乱的场景：**

比如说我们建了一个 topic，有三个 partition。生产者在写的时候，其实可以指定一个 key，比如说我们指定了某个订单 id 作为 key，那么这个订单相关的数据，一定会被分发到同一个 partition 中去，而且这个 partition 中的数据一定是有顺序的。消费者从 partition 中拉取数据的时候，也一定是有顺序的。到这里，顺序还是 ok 的，没有错乱。接着，我们在消费者里可能会搞多个线程来并发处理消息。因为如果消费者是单线程消费处理，而处理比较耗时的话，比如处理一条消息耗时几十 ms，那么 1 秒钟只能处理几十条消息，这吞吐量太低了。而多个线程并发跑的话，顺序可能就乱掉了。

**解决方案**

* 一个 topic，一个 partition，一个 consumer，内部单线程消费，单线程吞吐量太低，一般不会用这个。

* 写 N 个内存 queue，具有相同 key 的数据都到同一个内存 queue；然后对于 N 个线程，每个线程分别消费一个内存 queue 即可，这样就能保证顺序性。', 3, 1, 'technology-talk/middleware/mq/关于消息队列，面试官一般都会问哪些.md', 1, NOW(3)),
  (1222, 206, '如何解决消息队列的延时以及过期失效问题？消息队列满了以后该怎么处理？有几百万消息持续积压几小时，说说怎么解决？', '如何解决消息队列的延时以及过期失效问题？消息队列满了以后该怎么处理？有几百万消息持续积压几小时，说说怎么解决？', '你看这问法，其实本质针对的场景，都是说，可能你的消费端出了问题，不消费了；或者消费的速度极其慢。接着就坑爹了，可能你的消息队列集群的磁盘都快写满了，都没人消费，这个时候怎么办？或者是这整个就积压了几个小时，你这个时候怎么办？或者是你积压的时间太长了，导致比如 RabbitMQ 设置了消息过期时间后就没了怎么办？

所以就这事儿，其实线上挺常见的，一般不出，一出就是大 case。一般常见于，举个例子，消费端每次消费之后要写 mysql，结果 mysql 挂了，消费端 hang 那儿了，不动了；或者是消费端出了个什么岔子，导致消费速度极其慢。', 2, 1, 'technology-talk/middleware/mq/关于消息队列，面试官一般都会问哪些.md', 1, NOW(3)),
  (1223, 206, 'Kafka、ActiveMQ、RabbitMQ、RocketMQ  有什么优缺点 ？', 'Kafka、ActiveMQ、RabbitMQ、RocketMQ  有什么优缺点 ？', '**综上，各种对比之后，有如下建议**：

* 一般的业务系统要引入 MQ，最早大家都用 ActiveMQ，但是现在确实大家用的不多了，没经过大规模吞吐量场景的验证，社区也不是很活跃，所以大家还是算了吧，我个人不推荐用这个了；

* 后来大家开始用 RabbitMQ，但是确实 erlang 语言阻止了大量的 Java 工程师去深入研究和掌控它，对公司而言，几乎处于不可控的状态，但是确实人家是开源的，比较稳定的支持，活跃度也高；

* 不过现在确实越来越多的公司会去用 RocketMQ，确实很不错，毕竟是阿里出品，但社区可能有突然黄掉的风险（目前 RocketMQ 已捐给 Apache，但 GitHub 上的活跃度其实不算高）对自己公司技术实力有绝对自信的，推荐用 RocketMQ，否则回去老老实实用 RabbitMQ 吧，人家有活跃的开源社区，绝对不会黄。

* 所以中小型公司，技术实力较为一般，技术挑战不是特别高，用 RabbitMQ 是不错的选择；大型公司，基础架构研发实力较强，用 RocketMQ 是很好的选择。

* 如果是大数据领域的实时计算、日志采集等场景，用 Kafka 是业内标准的，绝对没问题，社区活跃度很高，绝对不会黄，何况几乎是全世界这个领域的事实性规范。', 2, 1, 'technology-talk/middleware/mq/关于消息队列，面试官一般都会问哪些.md', 1, NOW(3)),
  (1224, 206, '为什么使用kafka？', '为什么使用kafka？', '* 削峰填谷。缓冲上下游瞬时突发流量，保护“脆弱”的下游系统不被压垮，避免引发全链路服务“雪崩”。
* 系统解耦。发送方和接收方的松耦合，一定程度简化了开发成本，减少了系统间不必要的直接依赖。

**Kafka 名词术语，一网打尽**

* Broker：接收客户端发送过来的消息，对消息进行持久化
* 主题：Topic。主题是承载消息的逻辑容器，在实际使用中多用来区分具体的业务。
* 分区：Partition。一个有序不变的消息序列。每个主题下可以有多个分区。
* 消息：这里的消息就是指 Kafka 处理的主要对象。
* 消息位移：Offset。表示分区中每条消息的位置信息，是一个单调递增且不变的值。
* 副本：Replica。Kafka 中同一条消息能够被拷贝到多个地方以提供数据冗余，这些地方就是所谓的副本。副本还分为领导者副本和追随者副本，各自有不同的角色划分。每个分区可配置多个副本实现高可用。一个分区的N个副本一定在N个不同的Broker上。
* 生产者：Producer。向主题发布新消息的应用程序。
* 消费者：Consumer。从主题订阅新消息的应用程序。
* 消费者位移：Consumer Offset。表示消费者消费进度，每个消费者都有自己的消费者位移。offset保存在broker端的内部topic中，不是在clients中保存
* 消费者组：Consumer Group。多个消费者实例共同组成的一个组，同时消费多个分区以实现高吞吐。
* 重平衡：Rebalance。消费者组内某个消费者实例挂掉后，其他消费者实例自动重新分配订阅主题分区', 2, 1, 'technology-talk/middleware/mq/聊聊 Kafka 那点破事.md', 1, NOW(3)),
  (1225, 206, 'ZooKeeper 在里面的职责是什么？', 'ZooKeeper 在里面的职责是什么？', '它是一个分布式协调框架，负责协调管理并保存 Kafka 集群的所有元数据信息，比如集群都有哪些 Broker 在运行、创建了哪些 Topic，每个 Topic 都有多少分区以及这些分区的 Leader 副本都在哪些机器上等信息。', 1, 1, 'technology-talk/middleware/mq/聊聊 Kafka 那点破事.md', 1, NOW(3)),
  (1226, 206, 'Kafka Broker 是如何存储数据？', 'Kafka Broker 是如何存储数据？', 'Kafka 使用消息日志（Log）来保存数据，一个日志就是磁盘上一个只能追加写（Append-only）消息的物理文件。因为只能追加写入，故避免了缓慢的随机 I/O 操作，改为性能较好的顺序 I/O 写操作，这也是实现 Kafka 高吞吐量特性的一个重要手段。

不过如果你不停地向一个日志写入消息，最终也会耗尽所有的磁盘空间，因此 Kafka 必然要定期地删除消息以回收磁盘。怎么删除呢？

简单来说就是通过日志段（Log Segment）机制。在 Kafka 底层，一个日志又近一步细分成多个日志段，消息被追加写到当前最新的日志段中，当写满了一个日志段后，Kafka 会自动切分出一个新的日志段，并将老的日志段封存起来。Kafka 在后台还有定时任务会定期地检查老的日志段是否能够被删除，从而实现回收磁盘空间的目的。', 2, 1, 'technology-talk/middleware/mq/聊聊 Kafka 那点破事.md', 1, NOW(3)),
  (1227, 206, '为什么要引入消费者组?', '为什么要引入消费者组?', '主要是为了提升消费者端的吞吐量。多个消费者实例同时消费，加速整个消费端的吞吐量（TPS）。

在一个消费者组下，`一个分区只能被一个消费者消费`，`但一个消费者可能被分配多个分区`，因而在提交位移时也就能提交多个分区的位移。如果1个topic有2个分区，消费者组有3个消费者，有一个消费者将无法分配到任何分区，处于idle状态。

> 理想情况下，Consumer 实例的数量应该等于该 Group 订阅topic（可能多个）的分区总数。', 1, 1, 'technology-talk/middleware/mq/聊聊 Kafka 那点破事.md', 1, NOW(3)),
  (1228, 110, '如何计算B+树的高度？', '如何计算B+树的高度？', '在`InnoDB ` 的表空间文件中，约定`page number = 3`表示主键索引的根页

```
SELECT
b.name, a.name, index_id, type, a.space, a.PAGE_NO
FROM
information_schema.INNODB_SYS_INDEXES a,
information_schema.INNODB_SYS_TABLES b
WHERE
a.table_id = b.table_id AND a.space <> 0
and b.name like ''%sp_job_log'';
```

> 从图中可以看出，每个表的主键索引的根页的`page number`都是3，而其他的二级索引`page number`为4

在根页偏移量为`64`的地方存放了该B+树的`page level`。主键索引B+树的根页在整个表空间文件中的第3个页开始，所以算出它在文件中的偏移量：`16384*3  + 64 = 49152 + 64 =49216`，前2个字节中。

首先，找到MySql数据库物理文件存放位置：

```
show global variables like "%datadir%" ;
```

hexdump工具，查看表空间文件指定偏移量上的数据：

```
hexdump -s 49216 -n 10  sp_job_log.ibd
```

page_level 值是 1，那么 B+树高度为 `page level + 1 = 2`

**特别说明：**

* 查询数据库时，不论读一行，还是读多行，都是将这些行所在的整页数据加载，然后在内存中匹配过滤出最终结果。

* 表的检索速度跟树的深度有直接关系，毕竟一次页加载就是一次IO，而磁盘IO又是比较费时间。`对于一张千万级条数B+树高度为3的表与几十万级B+树高度也为3的表，其实查询效率相差不大。`', 3, 1, 'technology-talk/middleware/mysql/mysql 一棵 B+ 树能存多少', 1, NOW(3)),
  (1229, 110, '一棵B+树可以存放多少行数据？', '一棵B+树可以存放多少行数据？', '**假设B+树的深度为2**

这棵B+树的存储总记录数 = `根节点指针数 * 单个叶子节点记录条数`

**那么指针数如何计算？**

假设主键ID为`bigint`类型，长度为`8字节`，而指针大小在InnoDB源码中设置为`6字节`，这样一共`14字节`。

那么一个页中能存放多少这样的组合，就代表有多少指针，即 `16384 / 14 = 1170`。那么可以算出一棵高度为2 的B+树，能存放 `1170 * 16 = 18720` 条这样的数据记录。

同理：

高度为3的B+树可以存放的行数 =  `1170 * 1170 * 16 = 21902400 `

> 千万级的数据存储只需要约3层B+树，查询数据时，每加载一页（page）代表一次IO。所以说，根据主键id索引查询约3次IO便可以找到目标结果。

**对于一些复杂的查询，可能需要走二级索引，那么通过二级索引查找记录最多需要花费多少次IO呢？**

首先，从二级索引B+树中，根据`name` 找到对应的主键id

然后，再根据主键id 从 聚簇索引查找到对应的记录。如上图所示，二级索引有3层，聚簇索引有3层，那么最多花费的IO次数是：3+3 = 6

聚簇索引默认是主键，如果表中没有定义主键，InnoDB 会选择一个唯一的非空索引代替。如果没有这样的索引，InnoDB 会隐式定义一个主键来作为聚簇索引。

> 这也是为什么InnoDB表必须有主键，并且推荐使用整型的自增主键！！！

> InnoDB使用的是聚簇索引，将主键组织到一棵B+树中，而行数据就储存在叶子节点上

**举例说明：**

1、若使用`"where id = 14"`这样的条件查找记录，则按照B+树的检索算法即可查找到对应的叶节点，之后获得行数据。

2、若对Name列进行条件搜索，则需要两个步骤：

* 第一步在辅助索引B+树中检索Name，到达其叶子节点获取对应的主键值。
* 第二步使用主键值在主索引B+树中再执行一次B+树检索操作，最终到达叶子节点即可获取整行数据。（重点在于通过其他键需要建立辅助索引）', 3, 1, 'technology-talk/middleware/mysql/mysql 一棵 B+ 树能存多少', 1, NOW(3)),
  (1230, 110, '什么是高可用？', '什么是高可用？', '**维基百科定义：**

> 高可用性（high availability，缩写 HA），指系统无中断地执行其功能的能力，代表系统的可用性程度。高可用性通常通过提高系统的容错能力来实现。

**MySQL 的高可用是如何实现的呢？**

首先，我们来看张图

过程：

* 开始时，处理流程主要是 `场景一`
* 客户端`读、写`，访问的是主库
* 主库通过某种机制，将数据实时同步给备库
* 当主库突然发生故障（如：磁盘损坏等），无法正常响应客户端的请求。此时会`自动主备切换`，进入 `场景二`
* 客户端读写，访问的是备库（此时备库升级为新主库）

看似天衣无缝，那是不是可以高枕无忧了呢？？？兄弟，想多了

主备切换，确实能满足高可用。但有个前提，主备库的数据要同步。

不过，`数据同步`是个异步操作，不可能做到实时，所以说`主备延迟`是一定存在的', 2, 1, 'technology-talk/middleware/mysql/MySQL 主备延迟有哪些坑？主备', 1, NOW(3)),
  (1231, 110, '什么是主备延迟？', '什么是主备延迟？', '* 主库完成一个事务，写入binlog。binlog 中有一个时间字段，用于记录主库写入的时间【时刻 t1】
* binlog 同步给备库，备库接收并存储到中继日志 【时刻 t2】
* 备库SQL执行线程执行binlog，数据写入到备库表中 【时刻 t3】

主备延迟时间计算公式：

> t3 - t1

有没有简单命令，直接查看。在备库执行 `show slave status` 命令

> seconds_behind_master，表示当前备库延迟了多少秒

**心细的同学会有疑问了， t3 和 t1 分属于两台机器，如果时钟不一致怎么办？**

初始化时，备库连接到主库，会执行 `SELECT UNIX_TIMESTAMP()` 来获得当前主库的系统时间。

如果发现主库的系统时间与备库不一致，备库在计算 `seconds_behind_master` 会自动减掉这个差值。

注意：

> binlog 数据传输的时间（t2 - t1）非常短，可以忽略。主要延迟花费在备库执行binlog日志', 2, 1, 'technology-talk/middleware/mysql/MySQL 主备延迟有哪些坑？主备', 1, NOW(3)),
  (1232, 120, 'Redis Cluster 主节点宕机，如何是好？', 'Redis Cluster 主节点宕机，如何是好？', '只要是系统，就有宕机的风险。哨兵模式，通过单独部署哨兵集群，对整个Redis集群进行监控，具体的操作流程之前文章有介绍过。

Redis Cluster 并没有单独部署哨兵节点，而是通过master节点之间的心跳来彼此监控。

简单来说，针对A节点，某一个节点认为A宕机了，那么此时是主观下线。而如果集群内超过半数的节点认为A挂了， 那么此时A就会被标记为客观下线。

一旦节点A被标记为了客观下线，集群就会开始执行故障转移。其余正常运行的master节点会进行投票选举，从A节点的slave节点中选举出一个，将其切换成新的master对外提供服务。当某个slave获得了超过半数的master节点投票，就成功当选。

> 来源：https://segmentfault.com/a/1190000038528812

当选成功之后，新的master会执行`slaveof no one`来让自己停止复制A节点，使自己成为master。然后将A节点所负责处理的slot，全部转移给自己，然后就会向集群发PONG消息来广播自己的最新状态。

> 注意：Redis Cluster中的读、写请求都是在master上完成，从节点只是用于数据的容灾备份。', 2, 1, 'technology-talk/middleware/redis/秒杀活动技术方案，Redis申请3', 1, NOW(3)),
  (1233, 120, '什么是数据倾斜？', '什么是数据倾斜？', '单台机器的硬件配置有上限制约，一般我们会采用分布式架构将多台机器组成一个集群，下图的集群就是由三台Redis单机组成。客户端通过一定的路由策略，将读写请求转发到具体的实例上。

由于业务数据特殊性，按照指定的分片规则，可能导致不同的实例上数据分布不均匀，大量的数据集中到了一台或者几台机器节点上计算，从而导致这些节点负载多大，而其他节点处于空闲等待中，导致最终整体效率低下。', 1, 1, 'technology-talk/middleware/redis/如何解决 Redis 数据倾斜、热', 1, NOW(3)),
  (1234, 120, 'Redis Cluster 为什么不用一致性Hash?', 'Redis Cluster 为什么不用一致性Hash?', 'Redis Cluster 集群有16384个哈希槽，每个`key`通过`CRC16`校验后对`16384`取模来决定放置哪个槽。集群的每个节点负责一部分hash槽，举个例子，比如当前集群有3个节点，那么 `node-1` 包含 0 到 5460 号哈希槽，`node-2` 包含 5461 到 10922 号哈希槽，`node-3`包含 10922  到 16383 号哈希槽。

一致性哈希算法是 1997年麻省理工学院的 Karger 等人提出了，为的就是解决分布式缓存的问题。

一致性哈希算法本质上也是一种取模算法，不同于按服务器数量取模，一致性哈希是对固定值 2^32 取模。

> 公式 = hash（key） % 2^32

其取模的结果必然是在 [0, 2^32-1] 这个区间中的整数，从圆上映射的位置开始顺时针方向找到的第一个节点即为存储key的节点

一致性哈希算法大大缓解了扩容或者缩容导致的缓存失效问题，只影响本节点负责的那一小段key。如果集群的机器不多，且平时单机的负载水位很高，某个节点宕机带来的压力很容易引发雪崩效应。

举个例子：

> Redis 集群 总共有4台机器，假设数据分布均衡，每台机器承担 四分之一的流量，如果某一台机器突然挂了，顺时针方向下一台机器将要承担这多出来的 四分之一 流量，最终要承担 二分之一 的流量，还是有点恐怖。

但是如果采用 `CRC16`计算后，并结合槽位与实例的绑定关系，无论是扩容还是缩容，只需将相应节点的key做下数据平滑迁移，广播存储新的槽位映射关系，不会产生缓存失效，灵活性很高。

另外，如果服务器节点配置存在差异化，我们可以自定义分配不同节点负责的 slot 编号，调整不同节点的负载能力，非常方便。

当然可能有些小伙伴会好奇，Redis Cluster 为什么是  16384 个槽位？可以看下之前写的一篇文章

[https://mp.weixin.qq.com/s/gQ7Ibg9y3PlJUFM6z6McjA](https://mp.weixin.qq.com/s/gQ7Ibg9y3PlJUFM6z6McjA)', 3, 1, 'technology-talk/middleware/redis/如何解决 Redis 数据倾斜、热', 1, NOW(3)),
  (1235, 120, '缓存没有命中，怎么办？', '缓存没有命中，怎么办？', '* ①我们先查询缓存，判断缓存中是否有数据
* ②如果有数据，直接返回
* ③如果缓存为空，我们需要再查一次数据库，并将数据格式异构化，然后预热到缓冲中，然后将结果返回

注意：

步骤 ③ 存在风险漏洞，如果缓存中数据不存在，压力会转嫁给数据库。假如被竞争对手利用，搞无效请求流量攻击，瞬间大量请求打到数据库中，对系统性能产生很大影响，很容易把数据库打挂，这种现象称为缓存穿透。', 1, 1, 'technology-talk/middleware/redis/什么是布隆过滤器？如何解决高并发缓', 1, NOW(3)),
  (1236, 120, '如何处理缓存穿透？', '如何处理缓存穿透？', '我们的思路是，缓存中能不能判断这个数据库值的存在性，如果真的不存在，直接返回，也避免一次数据库查询。

由于不存在是个`无限边界`，所以，我们采用反向策略，将存在的值建立一个高效的检索。每次缓存取值时，先走一次判空检索。

简单归纳下，这个框架的要求：

* 快速检索
* 内存空间要非常小

经调研，我们发现`布隆过滤器`具备以上两个条件。', 1, 1, 'technology-talk/middleware/redis/什么是布隆过滤器？如何解决高并发缓', 1, NOW(3)),
  (1237, 120, '什么是布隆过滤器？', '什么是布隆过滤器？', '布隆过滤器（Bloom Filter）是1970年由布隆提出的。它实际上是一个很长的二进制向量和一系列随机映射函数。布隆过滤器可以用于检索一个元素是否在一个集合中。

* 优点：空间效率和查询时间都远远超过一般的算法。
* 缺点：有一定的误识别率，删除困难。', 1, 1, 'technology-talk/middleware/redis/什么是布隆过滤器？如何解决高并发缓', 1, NOW(3)),
  (1238, 120, '布隆过滤器如何构建？', '布隆过滤器如何构建？', '布隆过滤器本质上是一个 n 位的二进制数组，用0和1表示。

假如我们以商品为例，有三件商品，商品编码分别为，`id1`、`id2`、`id3`

1、首先，对`id1`，进行三次哈希，并确定其在二进制数组中的位置。

> 三次哈希，对应的二进制数组下标分别是 2、5、8，将原始数据从 0 变为 1。

2、对`id2`，进行三次哈希，并确定其在二进制数组中的位置。

> 三次哈希，对应的二进制数组下标分别是 2、7、98，将原始数据从 0 变为 1。

下标 2，之前已经被操作设置成 1，则本次认为是哈希冲突，不需要改动。

Hash 规则：如果在 Hash 后，原始位它是 0 的话，将其从 0 变为 1；如果本身这一位就是 1 的话，则保持不变。', 2, 1, 'technology-talk/middleware/redis/什么是布隆过滤器？如何解决高并发缓', 1, NOW(3)),
  (1239, 120, '布隆过滤器如何使用？', '布隆过滤器如何使用？', '跟初始化的过程有点类似，当查询一件商品的缓存信息时，我们首先要判断这件商品是否存在。

* 通过三个哈希函数对商品id计算哈希值
* 然后，在布隆数组中查找访问对应的位值，0或1
* 判断，三个值中，只要有一个不是1，那么我们认为数据是不存在的。

注意：布隆过滤器只能精确判断数据不存在情况，对于存在我们只能说是可能，因为存在Hash冲突情况，当然这个概率非常低。', 1, 1, 'technology-talk/middleware/redis/什么是布隆过滤器？如何解决高并发缓', 1, NOW(3)),
  (1240, 120, '如何减少布隆过滤器的误判？', '如何减少布隆过滤器的误判？', '1、增加二进制位数组的长度。这样经过hash后数据会更加的离散化，出现冲突的概率会大大降低

2、增加Hash的次数，变相的增加数据特征，特征越多，冲突的概率越小', 1, 1, 'technology-talk/middleware/redis/什么是布隆过滤器？如何解决高并发缓', 1, NOW(3)),
  (1241, 120, '布隆过滤器会不会很费内存？', '布隆过滤器会不会很费内存？', '带着疑问，我们来做个实验

假设有1千万个数据，我们需要记录其是否存在。存在的话标记1，不存在标记为0。技术选型，框架采用Redis的`BitMap`存储。

数据初始化预热代码：

```
redisTemplate.executePipelined(new RedisCallback<Long>() {
    @Nullable
    @Override
    public Long doInRedis(RedisConnection connection) throws DataAccessException {
        connection.openPipeline();
        for (int offset = 10000000; offset >= 0; offset--) {
            boolean value = offset % 2 == 0 ? true : false;
            connection.setBit("bloom-filter-data-1".getBytes(), offset, value);
        }
        connection.closePipeline();
        return null;
    }
});
System.out.println("数据预热完成");
```

> 性能有点慢，我们也可以采用分组形式，10000个数一组，多批次提交。

数据上传完了后，大小 1.19M，跟我们设想的一样。

计算公式： 10000000/8/1024/1024=1.19M', 3, 1, 'technology-talk/middleware/redis/什么是布隆过滤器？如何解决高并发缓', 1, NOW(3)),
  (1242, 120, '布隆过滤器二进制数组，如何处理删除？', '布隆过滤器二进制数组，如何处理删除？', '初始化后的布隆过滤器，可以直接拿来使用了。但是如果原始数据删除了怎么办？布隆过滤器二进制数组如何维护？

直接删除不行吗？

还真不行！因为这里面有Hash冲突的可能，会导致误删。

怎么办？

1、开发定时任务，每隔几个小时，自动创建一个新的布隆过滤器数组，替换老的，有点`CopyOnWriteArrayList`的味道

2、布隆过滤器增加一个等长的数组，存储计数器，主要解决冲突问题，每次删除时对应的计数器减一，如果结果为0，更新主数组的二进制值为0', 2, 1, 'technology-talk/middleware/redis/什么是布隆过滤器？如何解决高并发缓', 1, NOW(3)),
  (1243, 120, '疑问来了，槽位总数为什么是 16384 ？ 65536 不可以吗？', '疑问来了，槽位总数为什么是 16384 ？ 65536 不可以吗？', '这个问题，Redis 官方 Issues 也有朋友提出来过

> 地址：https://github.com/redis/redis/issues/2576

 `antirez` 大神对这个问题做了回复，简单归纳起来，有以下原因：

* 正常的心跳数据包携带节点的完整配置，它能以幂等方式来更新配置。如果采用 16384 个插槽，占空间 2KB （16384/8）；如果采用 65536 个插槽，占空间 8KB (65536/8)。

* Redis Cluster 不太可能扩展到超过 1000 个主节点，太多可能导致网络拥堵。

* 16384 个插槽范围比较合适，当集群扩展到1000个节点时，也能确保每个master节点有足够的插槽，

8KB 的心跳包看似不大，但是这个是心跳包每秒都要将本节点的信息同步给集群其他节点。比起 16384 个插槽，头大小增加了4倍，ping消息的消息头太大了，浪费带宽。

Redis主节点的哈希槽配置信息是通过 `bitmap` 来保存的

传输过程中，会对bitmap进行压缩，bitmap的填充率越低，压缩率越高。

> bitmap 填充率 = slots / N (N表示节点数)，

所以，插槽数偏低的话， 填充率会降低，压缩率会升高。

综合下来，从心跳包的大小、网络带宽、心跳并发、压缩率等维度考虑，16384 个插槽更有优势且能满足业务需求。

万事万物，都是相互制衡的，”大“ 不一定是最好的，合适最重要。', 2, 1, 'technology-talk/middleware/redis/为什么Redis Cluster是', 1, NOW(3)),
  (1244, 120, '好奇的宝宝可能要问了，为什么从库不能写？', '好奇的宝宝可能要问了，为什么从库不能写？', '考虑到数据合并的复杂性，假如一个key，多次更新，每次操作在不同的实例上执行，为了保证数据的全局一致性，势必要加全局锁，保证在集群范围上串行化操作且在最新的数据基础上更新，这个成本还是很大的。

为了降低系统复杂度，节约成本。主从同步架构方案一般都是在主库上写，在从库上读。分工明确，职责单一。

可能有同学会提到 Redis Cluster 模式，这个是另一种设计方案。采用水平分割方式，通过CRC16（key）算法，将数据拆分到若干个实例中，每个实例只对自己负责的槽位的数据读、写，从而分摊集群压力。这个属于另一种玩法，本期就不深入展开了。', 2, 1, 'technology-talk/middleware/redis/Redis 宕机，数据丢了，老板要', 1, NOW(3)),
  (1245, 120, '哨兵集群如何构建？', '哨兵集群如何构建？', '**首先，在redis-sentinel 的conf文件里添加两个配置项：**

```
sentinel monitor <master-name> <ip> <redis-port> <quorum> 
```

* master-name：对某个master+slave 组合的一个区分标识（一套sentinel是可以监听多套master+slave这样的组合）
* ip 和 port： 就是master节点的 ip 和 端口号。
* quorum：进行客观下线的一个依据，意思是至少有 quorum 个sentinel主观的认为这个master有故障，才会对这个master下线或故障转移。

```
sentinel down-after-milliseconds <master-name>  <timeout>
```

* timeout：毫秒值，如果这台sentinel超过timeout时间无法连通master或slave（slave不需要客观下线，因为不需要故障转移），就会主观认为该master已经下线（实际下线需要客观下线的判断通过才会真正下线）', 2, 1, 'technology-talk/middleware/redis/Redis主节点宕机，要如何处理？', 1, NOW(3)),
  (1246, 120, '哨兵如何知道所有从库地址呢？', '哨兵如何知道所有从库地址呢？', '我们知道每个哨兵实例的配置参数里有配置主库的ip和port，而每个主库要同步数据给从库，自然有挂载的所有从库信息。

所以，哨兵实例只需向主库发送`INFO`命令即可获取到所需要的信息，然后哨兵实例在依次与从库建立连接。

**至此，一个哨兵实例便可以收集到整个Redis 集群的数据，包含三块：**

* 所有的哨兵节点ip、port
* 主节点ip、port
* 主节点挂载的所有从节点的 ip、port

其他哨兵实例也是一样道理，这里就不在赘述了。', 2, 1, 'technology-talk/middleware/redis/Redis主节点宕机，要如何处理？', 1, NOW(3)),
  (1247, 120, '如何选哨兵Leader？', '如何选哨兵Leader？', '上图画了个流程实例，三个哨兵节点在 t1~t6 不同时刻点的投票情况。

当一个哨兵实例收到超过 设置的`quorum` 票Y后，它会成为新的Leader。然后由它（哨兵S3）负责后面的从库选主，通知从库与新主库建立关系并同步数据，通知客户端访问新主库。

如果本轮没有选出Leader节点，等哨兵故障转移超时时间的 2 倍时间后，重新发起新一轮选举。

为了保证哨兵Leader选举的顺利进行，除了对网络质量有要求外，最好配置奇数个哨兵节点且最好三个以上。', 2, 1, 'technology-talk/middleware/redis/Redis主节点宕机，要如何处理？', 1, NOW(3)),
  (1248, 120, '哨兵也是实例，如果挂了怎么办？', '哨兵也是实例，如果挂了怎么办？', '哨兵主要是用来监控Redis集群的健康状况，本身并不提供服务。

