  (1249, 120, '哨兵集群完成了主从切换，客户端如何感知？', '哨兵集群完成了主从切换，客户端如何感知？', '我们知道Redis有`pub/sub`机制，为了便于外部知道当前的切换进度，哨兵提供了多个订阅频道。

