  (1256, 170, '如何实现一个通用的代理类？', '如何实现一个通用的代理类？', '目前动态代理的实现方案有很多种，如JDK 动态代理、Cglib、Javassist、ASM、Byte Buddy等

JDK 动态代理的代理类是运行时通过字节码生成的，我们通过Proxy.newProxyInstance方法获取的接口实现类就是这个字节码生成的代理类

定义代理类`RpcInvocationHandler`，继承`InvocationHandler`接口，并重写invoke()方法。

```
public class RpcInvocationHandler implements InvocationHandler {

    private final String serviceVersion;
    private final long timeout;

    public RpcInvocationHandler(String serviceVersion, long timeout) {
        this.serviceVersion = serviceVersion;
        this.timeout = timeout;
    }

    @Override
    public Object invoke(Object proxy, Method method, Object[] args) {
        // todo
        // 1、封装RpcProtocol对象
        // 2、对象编码
        // 3、发送请求到服务端
        // 4、获取返回结果

        // 模拟生成一个订单号
        Long orderId = Long.valueOf(new Random().nextInt(100));

        String s = String.format("【RpcInvocationHandler】 调用方法：%s , 参数：%s ,订单id：%d", method.getName(), JSON.toJSONString(args), orderId);
        System.out.println(s);
        return orderId;
    }
```', 3, 1, 'technology-talk/spring/spring/如何实现注解RPC Consumer属性', 1, NOW(3)),
  (1257, 170, '如何在消费端动态注入接口的代理对象？', '如何在消费端动态注入接口的代理对象？', '构造一个自定义Bean，并对该Bean下执行的所有方法拦截，增加额外处理逻辑。

> `OrderService`是一个订单接口类，client端没有该接口的实现类。

定义注解`@RpcReference`，用于描述代理类的参数信息。

```
@Retention(RetentionPolicy.RUNTIME)
@Target(ElementType.FIELD)
@Autowired
public @interface RpcReference {
    String serviceVersion() default "1.0";
    long timeout() default 5000;
}
```

Spring 的 FactoryBean 接口可以帮助我们实现自定义的 Bean，FactoryBean 是一种特殊的工厂 Bean，通过 getObject() 方法返回对象，而并不是 FactoryBean 本身。

```
public class RpcReferenceBean implements FactoryBean<Object> {

    private Class<?> interfaceClass;

    private String serviceVersion;

    private long timeout;

    private Object object;

    @Override
    public Object getObject() throws Exception {
        return object;
    }

    @Override
    public Class<?> getObjectType() {
        return interfaceClass;
    }

    public void init() throws Exception {
        object = Proxy.newProxyInstance(
                interfaceClass.getClassLoader(),
                new Class<?>[]{interfaceClass},
                new RpcInvocationHandler(serviceVersion, timeout));
    }
}
```

但是 `RpcReferenceBean`如何被spring容器识别并加载呢？需要借助Spring的其他扩展点：

1、`BeanFactoryPostProcessor`，在Spring 容器加载 Bean 的定义之后以及 Bean 实例化之前执行，方便用户对 Bean 的配置元数据进行二次修改。

2、`ApplicationContextAware`，通过它Spring容器会自动把上下文环境对象调用ApplicationContextAware接口中的setApplicationContext方法。通过ApplicationContext可以查找Spring容器中的Bean对象。

3、`BeanClassLoaderAware`, 获取 Bean 的类加载器

```
public class RpcConsumerPostProcessor implements ApplicationContextAware, BeanClassLoaderAware, BeanFactoryPostProcessor {

    private ApplicationContext applicationContext;
    private ClassLoader classLoader;
    private final Map<String, BeanDefinition> rpcBeanDefinitions = new LinkedHashMap<>();

    @Override
    public void setApplicationContext(ApplicationContext applicationContext) throws BeansException {
        this.applicationContext = applicationContext;
    }

    @Override
    public void setBeanClassLoader(ClassLoader classLoader) {
        this.classLoader = classLoader;
    }

    @Override
    public void postProcessBeanFactory(ConfigurableListableBeanFactory beanFactory) throws BeansException {
        for (String beanDefinitionName : beanFactory.getBeanDefinitionNames()) {
            BeanDefinition beanDefinition = beanFactory.getBeanDefinition(beanDefinitionName);
            String beanClassName = beanDefinition.getBeanClassName();
            if (beanClassName != null) {
                Class<?> clazz = ClassUtils.resolveClassName(beanClassName, this.classLoader);
                ReflectionUtils.doWithFields(clazz, this::parseRpcReference);
            }
        }

        // 自定义bean注册到容器中
        BeanDefinitionRegistry registry = (BeanDefinitionRegistry) beanFactory;
        this.rpcBeanDefinitions.forEach((beanName, beanDefinition) -> {
            if (applicationContext.containsBean(beanName)) {
                throw new IllegalArgumentException("spring context already has a bean named " + beanName);
            }
            registry.registerBeanDefinition(beanName, beanDefinition);
            System.out.println(String.format("registered RpcReferenceBean %s success!", beanName));
        });
    }

    private void parseRpcReference(Field field) {
        RpcReference annotation = AnnotationUtils.getAnnotation(field, RpcReference.class);
        if (annotation != null) {
            // 创建RpcReferenceBean类的Bean定义
            BeanDefinitionBuilder beanDefinitionBuilder = BeanDefinitionBuilder.genericBeanDefinition(RpcReferenceBean.class);
            beanDefinitionBuilder.setInitMethodName("init");
            beanDefinitionBuilder.addPropertyValue("interfaceClass", field.getType());
            beanDefinitionBuilder.addPropertyValue("serviceVersion", annotation.serviceVersion());
            beanDefinitionBuilder.addPropertyValue("timeout", annotation.timeout());

            BeanDefinition beanDefinition = beanDefinitionBuilder.getBeanDefinition();
            rpcBeanDefinitions.put(field.getName(), beanDefinition);
        }
    }

}
```

`RpcConsumerPostProcessor` 从 beanFactory 中获取所有 Bean 的定义信息，然后对每个Bean下的field检测，如果field被声明了`@RpcReference`注解，通过`BeanDefinitionBuilder`重新构造
`RpcReferenceBean`的定义，并为成员变量赋值。

最后借助`BeanDefinitionRegistry`将新定义的Bean重新注册到Spring容器中。由容器来实例化Bean对象，并完成IOC依赖注入', 3, 1, 'technology-talk/spring/spring/如何实现注解RPC Consumer属性', 1, NOW(3)),
  (1258, 170, '如何定位排查？', '如何定位排查？', '普通研发人员一般会采用下面方式，在很多位置点埋入开始时间戳、结束时间戳，相减便得到耗时。代码如下：

```
long start1 = System.currentTimeMillis();
// 模拟业务逻辑处理
Thread.sleep(300);
long end1 = System.currentTimeMillis();

long start2 = System.currentTimeMillis();
// 模拟业务逻辑处理
Thread.sleep(730);
long end2 = System.currentTimeMillis();

System.out.println("执行操作1，耗时:" + (end1 - start1));
System.out.println("执行操作2，耗时:" + (end2 - start2));
```

虽然书写简单，但导致系统中充斥着大量低级代码，比较烦人，很容易让人怀疑你的技术实力。

我们的直接想法是能不能写个工具类，即统计`代码块`耗时，还能将分析结果直观展示出来

恰好 Spring框架提供了一个工具类，`org.springframework.util.StopWatch`，提供了轻量级统计功能，对应的pom文件依赖

```
<dependency>
    <groupId>org.springframework</groupId>
    <artifactId>spring-core</artifactId>
    <version>5.2.9.RELEASE</version>
</dependency>
```', 3, 1, 'technology-talk/spring/spring/统计代码块耗时的小工具.md', 1, NOW(3)),
  (1259, 206, '如何保证顺序消息？', '如何保证顺序消息？', '顺序由producer发送到broker的消息队列是满足FIFO的，所以发送是顺序的，单个queue里的消息是顺序的。多个Queue同时消费是无法绝对保证消息的有序性的。所以，同一个topic，同一个queue，发消息的时候一个线程发送消息，消费的时候一个线程去消费一个queue里的消息。', 1, 1, 'technology-talk/spring/springboot/RocketMQ.md', 1, NOW(3)),
  (1260, 206, '怎么保证消息发到同一个queue里？', '怎么保证消息发到同一个queue里？', 'RocketMQ给我们提供了MessageQueueSelector接口，可以重写里面的接口，实现自己的算法，比如判断i%2==0，那就发送消息到queue1否则发送到queue2。', 1, 1, 'technology-talk/spring/springboot/RocketMQ.md', 1, NOW(3)),
  (1261, 206, '如何实现消息过滤？', '如何实现消息过滤？', '有两种方案，一种是在broker端按照Consumer的去重逻辑进行过滤，这样做的好处是避免了无用的消息传输到Consumer端，缺点是加重了Broker的负担，实现起来相对复杂。另一种是在Consumer端过滤，比如按照消息设置的tag去重，这样的好处是实现起来简单，缺点是有大量无用的消息到达了Consumer端只能丢弃不处理。', 1, 1, 'technology-talk/spring/springboot/RocketMQ.md', 1, NOW(3)),
  (1262, 206, '如果由于网络等原因，多条重复消息投递到了Consumer端，你怎么进行消息去重？', '如果由于网络等原因，多条重复消息投递到了Consumer端，你怎么进行消息去重？', '这个得先说下消息的幂等性原则：就是用户对于同一种操作发起的多次请求的结果是一样的，不会因为操作了多次就产生不一样的结果。只要保持幂等性，不管来多少条消息，最后处理结果都一样，需要Consumer端自行实现。

去重的方案：因为每个消息都有一个MessageId, 保证每个消息都有一个唯一键，可以是数据库的主键或者唯一约束，也可以是Redis缓存中的键，当消费一条消息前，先检查数据库或缓存中是否存在这个唯一键，如果存在就不再处理这条消息，如果消费成功，要保证这个唯一键插入到去重表中。', 2, 1, 'technology-talk/spring/springboot/RocketMQ.md', 1, NOW(3)),
  (1263, 206, 'RocketMQ 怎么实现分布式事务消息的？', 'RocketMQ 怎么实现分布式事务消息的？', '* Producer向broker发送半消息
* Producer端收到响应，消息发送成功，此时消息是半消息，标记为“不可投递”状态，Consumer消费不了。
* Producer端执行本地事务。
* 正常情况本地事务执行完成，Producer向Broker发送Commit/Rollback，如果是Commit，Broker端将半消息标记为正常消息，Consumer可以消费，如果是Rollback，Broker丢弃此消息。
* 异常情况，Broker端迟迟等不到二次确认。在一定时间后，会查询所有的半消息，然后到Producer端查询半消息的执行情况。
* Producer 端查询本地事务的状态
* 根据事务的状态提交commit/rollback到broker端。', 2, 1, 'technology-talk/spring/springboot/RocketMQ.md', 1, NOW(3)),
  (1264, 206, '从Producer角度分析，如何确保消息成功发送到了Broker？', '从Producer角度分析，如何确保消息成功发送到了Broker？', '* 采用同步发送，即发送一条数据等到接受者返回响应之后再发送下一个数据包。如果返回响应OK，表示消息成功发送到了broker，状态超时或者失败都会触发二次重试。MQ Server端会有幂等控制。

* 可以采用分布式事务消息的投递方式。

* 如果一条消息发送之后超时，也可以通过查询日志的API，来检查是否在Broker存储成功。
总的来说，Producer还是采用同步发送来保证的。', 1, 1, 'technology-talk/spring/springboot/RocketMQ.md', 1, NOW(3)),
  (1265, 206, '从Broker角度分析，如何确保消息持久化?', '从Broker角度分析，如何确保消息持久化?', '* 消息只要持久化到CommitLog（日志文件）中，即使Broker宕机，未消费的消息也能重新恢复再消费。
* Broker的刷盘机制：同步刷盘和异步刷盘，不管哪种刷盘都可以保证消息一定存储在page cache，但是同步刷盘更可靠，它是Producer发送消息后等数据持久化到磁盘之后再返回响应给Producer。
* Broker支持多Master多Slave同步双写和多Master多Slave异步复制模式，消息都是发送给Master主机，但是消费既可以从Master消费，也可以从Slave消费。同步双写模式可以保证即使Master宕机，消息肯定在Slave中有备份，保证了消息不会丢失。', 2, 1, 'technology-talk/spring/springboot/RocketMQ.md', 1, NOW(3)),
  (1266, 206, '从Consumer角度分析，如何保证消息被成功消费？', '从Consumer角度分析，如何保证消息被成功消费？', 'Consumer自身维护了个持久化的offset（对应Message Queue里的min offset），用来标记已经成功消费且已经成功发回Broker的消息下标。如果Consumer消费失败，它会向Broker发回消费失败的状态，发回成功才会更新自己的offset。如果发回给broker时broker挂掉了，Consumer会定时重试，如果Consumer和Broker一起挂掉了，消息还在Broker端存储着，Consumer端的offset也是持久化的，重启之后继续拉取offset之前的消息进行消费。', 2, 1, 'technology-talk/spring/springboot/RocketMQ.md', 1, NOW(3));

